INSERT INTO `aid_ai_provider` (`id`, `provider_name`, `provider_code`, `logo_url`, `base_url`, `api_key`, `api_secret`, `auth_header`, `auth_prefix`, `extra_headers`, `extra_body`, `extra_query`, `api_key_apply_url`, `official_doc_url`, `official_price_url`, `task_query_suffix`, `status`, `del_flag`, `create_time`, `create_by`, `update_time`, `update_by`, `remark`, `supports_callback`, `schedule_strategy_json`) VALUES (21,'可灵 AI','kling',NULL,'https://api-beijing.klingai.com','','','Authorization','Bearer ',NULL,NULL,NULL,'https://klingai.com/dev','https://klingai.com/document-api','https://klingai.com/document-api/pricing/base/video','/tasks?task_ids=%s','1','0',NOW(),'system',NOW(),'system','可灵 3.0 官方新版 API；默认纯轮询；API Key 使用 Bearer；启用回调前在 api_secret 填写 whsec_ Webhook Secret',0,'{"dispatchMode":"POLL_ONLY","supportsCallback":false,"firstPollDelaySeconds":10,"baseIntervalSeconds":10,"maxIntervalSeconds":60,"backoffFactor":1.5,"maxRetryCount":180,"maxLifeSeconds":7200,"progressTimeoutSeconds":900,"maxConcurrency":1}');
-- ----------------------------
-- Table structure for aid_ai_voice_library
-- ----------------------------
DROP TABLE IF EXISTS `aid_ai_voice_library`;
CREATE TABLE `aid_ai_voice_library`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `provider_id` bigint(20) NULL DEFAULT NULL COMMENT '所属服务商ID（冗余自 aid_ai_model.provider_id）',
  `model_id` bigint(20) NOT NULL COMMENT '所属AI模型ID（主归属，关联 aid_ai_model.id）',
  `voice_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '厂商侧真实 voice_id / 音色编码',
  `voice_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '展示名称',
  `avatar_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '头像图URL',
  `avatar_prompt` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '头像提示',
  `sample_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '试听音频URL',
  `sample_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '试听文案',
  `language` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '语言区域码：zh-CN / en-US / ja-JP',
  `gender` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '性别：female / male / neutral',
  `age_range` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年龄段：child/teen/young/adult/middle/elderly',
  `character_types` json NULL COMMENT '角色类型 tag_code JSON 数组',
  `voice_styles` json NULL COMMENT '使用场景 tag_code JSON 数组',
  `tone_tags` json NULL COMMENT '音调 tag_code JSON 数组',
  `emotion_tags` json NULL COMMENT '擅长情感编码 JSON 数组（来源 aid_config.voice_emotion）',
  `supports_emotion` tinyint(1) NULL DEFAULT 0 COMMENT '是否支持情感参数',
  `supports_speed` tinyint(1) NULL DEFAULT 0 COMMENT '是否支持语速参数',
  `supports_pitch` tinyint(1) NULL DEFAULT 0 COMMENT '是否支持音调参数',
  `default_speed` decimal(4, 1) NULL DEFAULT 1.0 COMMENT '默认语速（0.5 ~ 2.0）',
  `default_pitch` decimal(4, 1) NULL DEFAULT 0.0 COMMENT '默认音调（-12 ~ 12）',
  `sample_rate` int(11) NULL DEFAULT NULL COMMENT '采样率，示例 16000/24000/48000',
  `audio_format` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '音频格式：mp3/wav/pcm',
  `offline_time` datetime NOT NULL DEFAULT '9999-12-31 00:00:00' COMMENT '下架时间(9999-12-31表示永不下架)',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序（越大越靠前）',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '状态：0启用 1停用',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志：0存在 2删除',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_model_voice`(`model_id`, `voice_code`) USING BTREE,
  INDEX `idx_status_del_flag`(`status`, `del_flag`) USING BTREE,
  INDEX `idx_status_del_offline`(`status`, `del_flag`, `offline_time`) USING BTREE,
  INDEX `idx_provider_model`(`provider_id`, `model_id`) USING BTREE,
  INDEX `idx_language_gender_age`(`language`, `gender`, `age_range`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2021 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI音色库' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aid_ai_voice_library
-- ----------------------------
INSERT INTO `aid_ai_voice_library` VALUES (1, 9, 42, 'zh_female_vv_uranus_bigtts', 'Vivi 2.0', '/aid/voice/avatar/2026/05/22/Vivi 2.0.jpg', '卡通女孩棕色长发扎成高马尾，大眼睛脸颊微红，表情温柔，暖色柔和风格，可爱简洁', '/aid/voice/sample/2026/05/17/5e4fb1b33f494a9d8dfdd86dd07abbd8.mp3', '你好呀，很高兴认识你~', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"对话\", \"角色配音\", \"多语种\"]', '[\"甜美\", \"温柔\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 500, '0', '语种：中文/日文/印尼/西语，方言：四川/陕西/东北', '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (2, 9, 42, 'zh_female_xiaohe_uranus_bigtts', '小何 2.0', '/aid/voice/avatar/2026/05/22/小何 2.0.jpg', '年轻女性，黑发柔顺，大眼睛明亮，面带微笑。风格为卡通渲染，以浅蓝和肤色为主', '/aid/voice/sample/2026/05/17/4a6e7f33a55e4ec1808bd45474200113.mp3', '我一直都在这里等你呢。', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"对话\", \"角色配音\"]', '[\"甜美\", \"温柔\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 499, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (3, 9, 42, 'zh_male_m191_uranus_bigtts', '云舟 2.0', '/aid/voice/avatar/2026/05/22/云舟 2.0.jpg', '年轻男性短发微卷，五官清秀，眼神温和，写实卡通风格，色彩柔和', '/aid/voice/sample/2026/05/17/6f2e19af65634bed83125b90bb9425e8.mp3', '放心，有我在，不会有事的。', 'zh-CN', 'male', 'young', '[\"少年\", \"青年\"]', '[\"对话\", \"角色配音\"]', '[\"沉稳\", \"磁性\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 498, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (4, 9, 42, 'zh_male_taocheng_uranus_bigtts', '小天 2.0', '/aid/voice/avatar/2026/05/22/小天 2.0.jpg', '年轻男性，短发微卷，五官立体，眼神温和。背景为浅蓝色渐变，人物面部清晰，整体风格简洁清新', '/aid/voice/sample/2026/05/17/8a02c38a64244725a363b1067cb45604.mp3', '嘿，今天咱们去哪儿玩？', 'zh-CN', 'male', 'young', '[\"少年\", \"青年\"]', '[\"对话\"]', '[\"开朗\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 497, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (5, 9, 42, 'zh_male_liufei_uranus_bigtts', '刘飞 2.0', '/aid/voice/avatar/2026/05/22/刘飞 2.0.jpg', '年轻男性面带微笑，卷曲短发，五官立体，浅灰背景，深色衣物，风格简洁自然', '/aid/voice/sample/2026/05/17/3db9e2eb24d5438a80cf8a3d2c948b54.mp3', '这事儿我来处理，你别担心。', 'zh-CN', 'male', 'adult', '[\"大叔\"]', '[\"对话\", \"角色配音\"]', '[\"沉稳\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 496, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (7, 9, 42, 'zh_female_qingxinnvsheng_uranus_bigtts', '清新女声 2.0', '/aid/voice/avatar/2026/05/22/清新女声 2.0.jpg', '年轻女性微笑，黑发齐肩，眼神明亮，浅色渐变背景，清新自然风格', '/aid/voice/sample/2026/05/17/a9892445b9914ffea7c4c3330c195ae5.mp3', '春天来了，花儿都开了。', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"对话\", \"旁白\"]', '[\"清澈\", \"甜美\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 494, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (9, 9, 42, 'zh_female_tianmeitaozi_uranus_bigtts', '甜美桃子 2.0', '/aid/voice/avatar/2026/05/22/甜美桃子 2.0.jpg', '年轻女性面带微笑，短发微卷，肤色白皙。整体风格清新柔和，色彩以粉嫩为主，背景为渐变粉色', '/aid/voice/sample/2026/05/17/5324a8e760334d43b6db544ae15e7703.mp3', '哇，这个好有趣呀！', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"对话\"]', '[\"甜美\", \"活泼\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 492, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (10, 9, 42, 'zh_female_shuangkuaisisi_uranus_bigtts', '爽快思思 2.0', '/aid/voice/avatar/2026/05/22/爽快思思 2.0.jpg', '年轻女性直视镜头，齐刘海及肩发，五官精致。妆容自然，粉嫩腮红与淡色唇彩突出柔美气质。背景纯白清新', '/aid/voice/sample/2026/05/17/562afc7ad7294fec84281d242bb6c099.mp3', '快来试试吧，绝对不会后悔！', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"对话\", \"广告\"]', '[\"直率\", \"活泼\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 491, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (13, 9, 42, 'zh_female_meilinvyou_uranus_bigtts', '魅力女友 2.0', '/aid/voice/avatar/2026/05/22/魅力女友 2.0.jpg', '短发女性面带微笑，眼神温和。背景为浅蓝色，人物穿着白色上衣，整体风格清新自然表情', '/aid/voice/sample/2026/05/17/2edf0833e5d94ecf9604addb305a9cd6.mp3', '今天累不累？我给你泡了茶。', 'zh-CN', 'female', 'young', '[\"少女\", \"御姐\"]', '[\"对话\", \"角色配音\"]', '[\"温柔\", \"磁性\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 488, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (14, 9, 42, 'zh_female_wenroumama_uranus_bigtts', '温柔妈妈 2.0', '/aid/voice/avatar/2026/05/22/温柔妈妈 2.0.jpg', '年轻女性面带微笑，短卷发，戴金边圆框眼镜，穿白衬衫配黑色领子，背景浅色柔和，整体风格清新自然', '/aid/voice/sample/2026/05/17/ec771ff3e8544e5491dbf9d3307b970c.mp3', '慢点吃，别急，还有呢。', 'zh-CN', 'female', 'middle', '[\"妈妈\"]', '[\"对话\", \"旁白\"]', '[\"温柔\", \"温暖\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 487, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
INSERT INTO `aid_ai_voice_library` VALUES (16, 9, 42, 'zh_female_tvbnv_uranus_bigtts', 'TVB女声 2.0', '/aid/voice/avatar/2026/05/22/TVB女声.jpg', '年轻女性面带微笑，黑色长发披肩，佩戴蓝色耳饰，蓝色背景，色彩明快，风格清新自然', '/aid/voice/sample/2026/05/17/1ab34b6a027a404e8cd6362747d3cabb.mp3', '做人嘛，最紧要开心啦。', 'zh-CN', 'female', 'adult', '[\"御姐\"]', '[\"对话\", \"角色配音\"]', '[\"磁性\", \"温柔\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 485, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
