INSERT INTO `aid_ai_voice_library` VALUES (55, 9, 42, 'zh_female_wenrouxiaoya_uranus_bigtts', '温柔小雅 2.0', '/aid/voice/avatar/2026/05/22/温柔小雅 2.0.jpg', '年轻女性面带微笑，短发微卷，肤色白皙。背景柔和虚化，色彩温暖，整体风格清新自然突出面部表情', '/aid/voice/sample/2026/05/17/62442fe36bea4acb97ed83fe22f5f285.mp3', '慢慢来，一切都会好起来的。', 'zh-CN', 'female', 'young', '[\"少女\"]', '[\"视频配音\", \"对话\"]', '[\"温柔\", \"甜美\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 446, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
