INSERT INTO `aid_ai_voice_library` VALUES (61, 9, 42, 'zh_male_silang_uranus_bigtts', '四郎 2.0', '/aid/voice/avatar/2026/05/22/四郎 2.0.jpg', '男子身穿深色传统服饰，头戴黑色帽子，面容清秀，眼神坚定，背景简洁。整体风格古朴典雅，色彩沉稳', '/aid/voice/sample/2026/05/17/8770faeba42f487fa0423aa14c5a6ab1.mp3', '朕意已决，不必再议。', 'zh-CN', 'male', 'adult', '[\"IP人物\"]', '[\"角色配音\", \"视频配音\"]', '[\"磁性\", \"沉稳\"]', '[\"ASMR\"]', 1, 1, 1, 1.0, 0.0, 24000, 'mp3', '9999-12-31 00:00:00', 427, '0', NULL, '0', 'admin', '2026-05-10 23:44:32', 'system', '2026-05-22 23:07:39');
