INSERT INTO `aid_comic_asset` VALUES (45, 'style', '毛绒定格', NULL, '羊毛毡定格动画风格，针毡毛绒材质，表面绒毛纤维与蓬松质感，手作缝线痕迹，微缩布景，柔和温暖的棚拍光影，柔软治愈。', '/aid/style/sample/5-linghu_09.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (46, 'style', '写实电影', NULL, '参考院线电影，真人电影风格，影视大片，真实透视比例，真实皮肤质感，自然光影，35mm胶片颗粒，细节清晰不过度锐化。', '/aid/style/sample/6-linghu_01.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (47, 'style', '复古胶片', NULL, '70年代复古胶片摄影风格，真人写实摄影，明显胶片颗粒，漏光与暗角，低饱和褪色偏黄的暖调，轻微失焦柔化，怀旧老照片质感。', '/aid/style/sample/6-linghu_02.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (48, 'style', '真实古装', NULL, '国产古装剧影像风格，强调传统古装剧的实拍质感，真人写实摄影，电影感，非精心打光，低饱和沉稳的东方色调，极致细节，实拍感。', '/aid/style/sample/6-linghu_03.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (49, 'style', '复古港片', NULL, '90年代港片影像风格，强调九十年代都市胶片摄影质感，真人写实摄影，电影感，胶片颗粒与轻微拖影，浓郁暖调、暗金、墨绿与霓虹红，暧昧疏离的复古港味。', '/aid/style/sample/6-linghu_04.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (50, 'style', '复古武侠', NULL, '港式武侠电影影像风格，真人写实摄影，电影感，画面粗粝写实、江湖气十足、硬朗生猛，青灰、墨绿、土黄的户外环境色调，风沙烟尘的空气感。', '/aid/style/sample/6-linghu_05.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (51, 'style', '真实光晕', NULL, '电影感真人写实摄影，变形宽银幕镜头，横向蓝色镜头光斑，逆光漏光与辉光，浅景深虚化，金色时刻的暖调光线，通透梦幻的光晕氛围。', '/aid/style/sample/6-linghu_06.jpg', '0', '2026-03-31 00:20:17', 'system', '2026-07-26 19:19:40', 'system', NULL);
INSERT INTO `aid_comic_asset` VALUES (52, 'reference_scene', '现代居家客厅·日·内景·春·晴·无人', 'cinematic wide shot of a modern cozy living room interior, warm sunlight streaming through large floor-to-ceiling windows casting soft shadows on beige fabric sofa, wooden coffee table with a vase of fresh cherry blossoms, cream walls with abstract art prints, open-plan connected to a bright kitchen, light oak flooring, sheer white curtains gently swaying, spring afternoon atmosphere, photorealistic, 8K --ar 1:1', '现代温馨客厅，春日午后阳光透过落地窗洒在米色布艺沙发上，木茶几上放着插有樱花的玻璃花瓶，奶油色墙面配抽象画，开放式厨房连通，浅橡木地板，白色纱帘轻摆，温暖明亮的居家氛围', '/aid/lib/scene/2026/07/09/现代居家客厅·日·内景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/现代居家客厅·日·内景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (53, 'reference_scene', '现代居家卧室·夜·内景·秋·雨·无人', 'cinematic low-key shot of a modern minimalist bedroom at night, soft warm bedside lamp glow creating intimate shadows, queen bed with grey linen bedding slightly rumpled, raindrops streaking down the window glass reflecting distant city lights, dark wood nightstand with a half-read book, plush wool rug on dark flooring, gentle melancholic autumn night atmosphere, photorealistic, 8K --ar 1:1', '深夜极简现代卧室，床头暖灯投射温柔光影，灰色亚麻床品微皱，雨滴沿窗玻璃滑落映出远方城市灯火，深木床头柜上放着半开的书，柔软羊毛毯铺在深色地板上，秋夜微愁氛围', '/aid/lib/scene/2026/07/09/现代居家卧室·夜·内景·秋·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/现代居家卧室·夜·内景·秋·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (54, 'reference_scene', '居民楼楼道·日·内景·冬·雾·无人', 'cinematic corridor perspective of a residential building hallway, pale white fluorescent ceiling lights, rows of identical grey security doors on both sides, worn terrazzo floor tiles with faint scuff marks, fog visible through the small window at the far end, walls painted light beige with slight peeling, emergency exit sign glowing green, slightly cold and desolate atmosphere, photorealistic, 8K --ar 1:1', '居民楼走廊内景，苍白荧光顶灯照亮两侧灰色防盗门，水磨石地面有淡淡磨损痕迹，尽头小窗外浓雾弥漫，米黄色墙面墙皮微微剥落，绿色应急出口标识发光，清冷寂寥的冬季白日', '/aid/lib/scene/2026/07/09/居民楼楼道·日·内景·冬·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/居民楼楼道·日·内景·冬·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (55, 'reference_scene', '城市马路·日·外景·夏·晴·无人', 'cinematic wide establishing shot of a wide urban asphalt road with white lane markings stretching into the distance, clear blue summer sky with scattered clouds, modern glass skyscrapers lining both sides reflecting sunlight, green-leafed roadside trees, clean sidewalks with street lamps, bright midday sun creating sharp shadows, slight heat-haze effect on the road, photorealistic, 8K --ar 1:1', '宽阔的城市柏油马路向远方延伸，湛蓝夏日天空白云散落，两侧现代玻璃幕墙大厦反射阳光，路边绿树成行，人行道干净整洁，正午烈日投下清晰阴影，路面微微蒸腾热浪', '/aid/lib/scene/2026/07/09/城市马路·日·外景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/城市马路·日·外景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (56, 'reference_scene', '城市马路·夜·外景·秋·雨·无人', 'cinematic night street shot of a wet urban road, reflections of neon signs and street lamps glistening on rain-soaked asphalt, yellow taxi light trails stretching across the frame, autumn leaves scattered on wet ground, tall buildings with illuminated windows on both sides, light drizzle creating dreamy bokeh city lights, moody and slightly melancholic atmosphere, photorealistic, 8K --ar 1:1', '深夜湿漉漉的城市道路，霓虹灯与路灯倒影在雨浸的柏油路面上闪烁，黄色车灯拖尾划过画面，秋叶散落湿地，两侧高楼灯光点点，细雨朦胧中城市灯火化为柔焦光斑，忧郁而迷离', '/aid/lib/scene/2026/07/09/城市马路·夜·外景·秋·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/城市马路·夜·外景·秋·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (57, 'reference_scene', '城市公园·日·外景·春·晴·无人', 'cinematic wide shot of a serene urban park pathway bordered by blooming cherry blossom trees in full pink, fresh green grass lawn with scattered white daisies, a wooden bench under a large old tree, small pond in the distance reflecting blue sky and clouds, spring breeze rustling petals onto the path, warm golden afternoon sunlight filtering through leaves, peaceful and hopeful atmosphere, photorealistic, 8K --ar 1:1', '宁静的城市公园小径，两侧樱花树盛放满枝粉色花朵，翠绿草坪上白色雏菊点缀，古老大树下木质长椅，远处小池塘倒映蓝天白云，春风轻拂花瓣飘落小径，温暖金色午后阳光透过枝叶洒下', '/aid/lib/scene/2026/07/09/城市公园·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/城市公园·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (58, 'reference_scene', '轿车内·日·内景·夏·晴·无人', 'cinematic POV shot from back seat of a mid-range sedan, view through windshield showing suburban road ahead with blurred trees passing by, summer sunlight streaming through glass creating soft lens flare, black leather seats with detailed stitching, dashboard with glowing digital display, rearview mirror reflecting the road behind, steering wheel in the foreground, photorealistic, 8K --ar 1:1', '中档轿车后座视角，前挡风玻璃外可见郊外公路与模糊掠过的行道树，夏日阳光穿透玻璃形成柔和光晕，黑色皮革座椅缝线细节清晰，仪表盘数字显示屏发光，后视镜映出身后道路，方向盘在前景中', '/aid/lib/scene/2026/07/09/轿车内·日·内景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/轿车内·日·内景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (59, 'reference_scene', '轿车内·夜·内景·冬·雪·无人', 'cinematic intimate shot inside a luxury car at night, gentle snowflakes falling and melting on the windshield, soft amber interior ambient lighting, wet snow accumulating on the car hood visible through glass, city street lights casting orange glow through snowy windshield, warm intimate atmosphere contrasting with cold winter outside, photorealistic, 8K --ar 1:1', '深夜豪华车内副驾视角，雪花轻落挡风玻璃缓缓融化，柔和琥珀色氛围灯照亮内饰，湿雪堆积在引擎盖上从玻璃望出，城市街灯在雪夜车窗上投下橙色光晕，车内温暖与外边寒冬形成鲜明对比', '/aid/lib/scene/2026/07/09/轿车内·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/轿车内·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (60, 'reference_scene', '豪华别墅客厅·日·内景·秋·晴·无人', 'cinematic establishing shot of a grand luxury villa living room with soaring double-height ceiling, enormous crystal chandelier cascading down, cream Italian marble flooring with intricate inlay patterns, white Italian leather curved sectional sofa, gold-trimmed classical European furniture, floor-to-ceiling windows overlooking manicured garden with autumn colors, grand piano in the corner, ornate fireplace with gold-framed mirror above, opulent yet tasteful, warm natural daylight flooding the space, photorealistic, 8K --ar 1:1', '挑高豪华别墅客厅，巨型水晶吊灯垂挂，意大利米色大理石地面镶嵌精美花纹，白色真皮弧形组合沙发，欧式古典描金家具，落地窗外可见秋色浓郁的精修花园，角落一架三角钢琴，华丽壁炉上方金色边框大镜', '/aid/lib/scene/2026/07/09/豪华别墅客厅·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/豪华别墅客厅·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (61, 'reference_scene', '豪华别墅主卧·夜·内景·冬·雨·无人', 'cinematic dramatic shot of a master bedroom in a luxury mansion at night, king-size bed with silk champagne bedding and velvet headboard, elegant nightstands with designer lamps casting warm pools of light, walk-in closet visible through an archway, rain streaming down panoramic windows with blurred city skyline view, dark hardwood floor with plush oversized rug, abstract modern art on walls, luxurious but slightly cold atmosphere, photorealistic, 8K --ar 1:1', '深夜豪宅主卧，特大床铺着香槟色真丝床品与天鹅绒床头，雅致床头柜上设计师台灯投下温暖光圈，拱门内步入式衣帽间隐约可见，冬雨沿全景窗流下，窗外城市天际线模糊，深色硬木地板铺着毛绒地毯', '/aid/lib/scene/2026/07/09/豪华别墅主卧·夜·内景·冬·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/豪华别墅主卧·夜·内景·冬·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (62, 'reference_scene', '豪华别墅泳池·日·外景·夏·晴·无人', 'cinematic aerial shot of a stunning infinity pool at a luxury hillside villa, crystal-clear turquoise water reflecting bright summer sunlight, white marble pool deck with elegant lounge chairs and white umbrellas, panoramic view of the city skyline in the distance, tropical palm trees and manicured hedges framing the scene, gentle ripples on the water surface creating light patterns, golden hour afternoon light, photorealistic, 8K --ar 1:1', '山顶豪宅无边际泳池鸟瞰，清澈碧蓝池水反射夏日骄阳，白色大理石池边排列着优雅躺椅与白伞，远处城市天际线尽收眼底，热带棕榈与修剪整齐的树篱围合空间，金色午后阳光洒满画面', '/aid/lib/scene/2026/07/09/豪华别墅泳池·日·外景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/豪华别墅泳池·日·外景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (63, 'reference_scene', '豪车内·夜·内景·秋·雨·无人', 'cinematic close-quarters shot inside an ultra-luxury car at night, rich cream leather seats with diamond quilting, starlight headliner ceiling twinkling above, burl wood trim and polished chrome details, rain softly streaking side window with blurred city neon reflections, ambient interior lighting in warm amber tone, view from rear seat showing partition and driver area, opulent and intimate, photorealistic, 8K --ar 1:1', '深夜超豪华轿车内部，奶白色真皮座椅菱形绗缝工艺，星空顶棚璀璨闪烁，胡桃木饰板与抛光镀铬细节，秋雨轻滑侧窗，窗外城市霓虹化为柔焦色块，氛围灯呈温暖琥珀色调，后排视角可见隔断与驾驶区', '/aid/lib/scene/2026/07/09/豪车内·夜·内景·秋·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/豪车内·夜·内景·秋·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (64, 'reference_scene', '豪门宴会厅·夜·内景·冬·晴·无人', 'cinematic wide master shot of a magnificent mansion ballroom prepared for an elite gala, three-tier crystal chandeliers casting prismatic light across the room, white and gold banquet tables with elaborate floral centerpieces, polished marble floor reflecting lights like a mirror, tall arched windows with heavy velvet burgundy drapes, grand staircase at the far end with ornate gold banister, champagne tower sparkling on a central table, opulent winter evening atmosphere, photorealistic, 8K --ar 1:1', '宏伟宅邸宴会厅为名流晚宴布置妥当，三层水晶吊灯光芒璀璨，白色与金色宴会桌鲜花簇拥，抛光大理石地面如镜面反射灯火，高挑拱窗垂挂酒红色天鹅绒厚帘，尽头金色扶手大楼梯气势恢宏，中央香槟塔晶莹闪烁', '/aid/lib/scene/2026/07/09/豪门宴会厅·夜·内景·冬·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/豪门宴会厅·夜·内景·冬·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (65, 'reference_scene', '开放式办公区·日·内景·春·晴·无人', 'cinematic wide shot of a modern open-plan office interior, rows of sleek white workstations with dual monitors and ergonomic chairs, bright natural daylight from floor-to-ceiling windows showing a spring city skyline, indoor potted plants creating green dividers between desk clusters, glass-walled meeting rooms in the background, modern track lighting in the exposed ceiling, clean minimalist Scandinavian design aesthetic, productive and professional atmosphere, photorealistic, 8K --ar 1:1', '现代开放式办公空间，成排白色工位配备双显示器与人体工学椅，落地窗引入春日自然光映出城市天际线，室内绿植盆栽区隔工作站群，背景中玻璃墙会议室隐约可见，裸露天花板上轨道射灯照明，北欧极简美学', '/aid/lib/scene/2026/07/09/开放式办公区·日·内景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/开放式办公区·日·内景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (66, 'reference_scene', '总裁办公室·日·内景·秋·晴·无人', 'cinematic establishing shot of a corner CEO office on a high floor, expansive floor-to-ceiling windows with panoramic city skyline view, large dark mahogany executive desk with sleek iMac and leather accessories, high-end black leather visitor chairs facing the desk, floor-to-ceiling bookshelf filled with leather-bound books and subtle awards, modern abstract sculpture on a pedestal, warm autumn afternoon light creating long dramatic shadows across marble floor, minimalist but powerful aesthetic conveying authority, photorealistic, 8K --ar 1:1', '高层转角CEO办公室，整面落地窗俯瞰城市全景，深色桃花心木大班台配iMac与皮具文具，对面两把高级黑色皮质访客椅，整面墙书架摆满皮面精装书与低调奖杯，底座上现代抽象雕塑点缀，秋日午后阳光在大理石地面拖出长长阴影', '/aid/lib/scene/2026/07/09/总裁办公室·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/总裁办公室·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (67, 'reference_scene', '高层会议室·夜·内景·冬·雪·无人', 'cinematic dramatic shot of a premium corporate boardroom at night, long polished ebony conference table with ten high-back leather chairs perfectly aligned, large LED screen on the wall displaying financial charts frozen mid-presentation, snow falling gently beyond the floor-to-ceiling windows showing winter cityscape, modern pendant lights casting cool white glow, glass water carafes and notepads at each seat, tense corporate atmosphere, high contrast shadows, photorealistic, 8K --ar 1:1', '深夜高级企业董事会议室，乌木长会议桌两侧十把高背皮椅整齐排列，墙面大LED屏显示停驻的财务报表，落地窗外冬雪轻落俯瞰城市夜景，现代吊灯投下冷白光线，每席配玻璃水瓶与记事本，高压紧张的商战氛围', '/aid/lib/scene/2026/07/09/高层会议室·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/高层会议室·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (68, 'reference_scene', '公司前台大堂·日·内景·夏·晴·无人', 'cinematic wide establishing shot of a stunning corporate lobby with triple-height ceiling, massive LED wall displaying motion graphics company logo, polished white marble reception desk with sleek minimalist design, modern sculptural seating area with designer armchairs, living green wall spanning three floors, glass elevator shafts with cars moving silently, bright summer sunlight through glass facade creating prismatic light patterns, high-end corporate luxury aesthetic, photorealistic, 8K --ar 1:1', '令人震撼的企业大堂三层挑空，巨型LED动态墙展示公司Logo，流线型白色大理石前台简约极致，现代雕塑感休息区配置设计师款单人沙发，整面三层绿植墙生机盎然，玻璃电梯井中轿厢无声运行，夏日阳光穿过玻璃幕墙形成棱镜光斑', '/aid/lib/scene/2026/07/09/公司前台大堂·日·内景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/公司前台大堂·日·内景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (69, 'reference_scene', '消防楼梯间·夜·内景·秋·雾·无人', 'cinematic thriller-style shot of a concrete stairwell in a modern office building at night, industrial grey concrete walls and metal stairs with anti-slip treads, harsh fluorescent emergency lighting creating stark shadows, small window on each landing showing foggy city night outside, metal handrails worn smooth from use, eerie and tense empty atmosphere, security camera in corner with blinking red light, photorealistic, 8K --ar 1:1', '深夜写字楼混凝土消防楼梯间，工业灰墙面与防滑金属楼梯，刺眼荧光应急灯投下锐利阴影，每层转角小窗外秋雾笼罩城市夜色，金属扶手经年使用磨得光滑，空荡回响的紧张氛围，角落监控摄像头红灯闪烁', '/aid/lib/scene/2026/07/09/消防楼梯间·夜·内景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/消防楼梯间·夜·内景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (70, 'reference_scene', '街边大排档·夜·外景·夏·晴·无人', 'cinematic street-level shot of a Chinese outdoor food stall at night, red plastic tables and stools neatly arranged under a portable canopy, steaming wok visible in the open kitchen with flames leaping up, strings of warm yellow fairy lights draped overhead, beer crates stacked against the wall, menu board with handwritten Chinese chalk characters, smoke rising gently into warm summer night air, nostalgic and down-to-earth atmosphere, photorealistic, 8K --ar 1:1', '深夜中国街边大排档，红色塑料桌椅在可移动雨棚下整齐排列，开放式厨房铁锅火焰腾跃热气蒸腾，暖黄串灯在头顶交织，墙边堆着啤酒箱，粉笔手写菜单黑板挂在一旁，烟气飘入温暖夏夜空气中', '/aid/lib/scene/2026/07/09/街边大排档·夜·外景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/街边大排档·夜·外景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (71, 'reference_scene', '老城区菜市场·日·外景·春·晴·无人', 'cinematic documentary-style shot of a traditional Chinese wet market in an old city district, rows of wooden stalls with red and blue striped awnings, fresh vegetables and fruits artistically arranged in woven baskets, hanging red lanterns above the butchers\' stall, narrow alleyway between stalls with worn cobblestone floor, warm spring morning sunlight filtering through gaps in the awning creating dappled light, vibrant and full of life, photorealistic, 8K --ar 1:1', '中国老城传统菜市场，红蓝条纹遮阳篷下一排排水质摊位整齐排列，编织竹篮中蔬果摆放讲究，肉铺上方红灯笼高挂，摊位间小巷卵石路面被岁月磨光，春日晨光透过篷布缝隙洒下斑驳光影', '/aid/lib/scene/2026/07/09/老城区菜市场·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/老城区菜市场·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (72, 'reference_scene', '城中村小巷·夜·外景·夏·雨·无人', 'cinematic urban realism shot of a narrow alley in a Chinese urban village at night, tangled overhead electrical wires silhouetted against dark sky, old apartment buildings with clothes drying on balcony poles, single warm yellow street lamp casting pool of light on wet concrete ground, puddles reflecting the lamp light, faded red brick walls with peeling posters and graffiti, light summer rain creating humid atmosphere, lonely stray cat silhouette, gritty yet cinematic, photorealistic, 8K --ar 1:1', '深夜中国城中村狭小巷道，杂乱电线在夜空剪影般交错，老旧居民楼阳台上晾晒衣物垂挂，一盏暖黄路灯在湿漉漉水泥地面投下光池，水洼倒映灯影，红砖墙贴满剥落海报与涂鸦，夏日细雨营造潮湿氛围，一只流浪猫剪影在垃圾桶旁', '/aid/lib/scene/2026/07/09/城中村小巷·夜·外景·夏·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/城中村小巷·夜·外景·夏·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (73, 'reference_scene', '地铁车厢内·日·内景·冬·晴·无人', 'cinematic interior shot of a modern Chinese subway train car, rows of empty stainless steel seats along both sides, handrails and hanging straps gently swaying, bright LED lighting panels in the ceiling, route map display screen showing stations in Chinese and English, large windows showing dark tunnel walls rushing by, clean and orderly atmosphere, slight motion blur on window views suggesting speed, photorealistic, 8K --ar 1:1', '现代中国地铁车厢内部，两侧不锈钢长椅空空荡荡，扶手与吊环轻轻晃动，天花板LED灯光明亮均匀，路线图显示屏中英文站名清晰可见，大窗外是飞速后退的黑暗隧道壁偶尔闪过灯光，轻微运动模糊暗示车速', '/aid/lib/scene/2026/07/09/地铁车厢内·日·内景·冬·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/地铁车厢内·日·内景·冬·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (74, 'reference_scene', '老旧居民楼天台·夜·外景·秋·雾·无人', 'cinematic atmospheric shot of a rooftop of an old residential building at night, weathered concrete surface with cracks and water stains, rusted metal railings along the edge, clotheslines with forgotten laundry hanging, mismatched satellite dishes pointing at different angles, panoramic view of a foggy cityscape with scattered apartment lights glowing through mist, a single old wooden chair left on the rooftop, lonely and contemplative autumn night atmosphere, photorealistic, 8K --ar 1:1', '深夜老旧居民楼天台，风化混凝土表面布满裂纹水渍，边缘锈迹斑斑的金属栏杆，晾衣绳上挂着遗忘的衣物，各式卫星天线朝向各异，秋雾中的城市全景灯火点点穿透雾气，天台角落孤零零一把旧木椅', '/aid/lib/scene/2026/07/09/老旧居民楼天台·夜·外景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/老旧居民楼天台·夜·外景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (75, 'reference_scene', '文艺咖啡厅·日·内景·秋·晴·无人', 'cinematic warm-tone shot of a charming artisanal coffee shop interior, warm afternoon sunlight through large windows with wooden frames, rustic exposed brick accent wall with hanging potted plants, mismatched vintage wooden tables and chairs, espresso machine gleaming on a marble counter, blackboard menu with artistic chalk lettering, bookshelf with novels and board games, soft golden hour light creating cozy atmosphere, photorealistic, 8K --ar 1:1', '迷人手工咖啡店内景，午后暖阳穿过木质窗框洒入，一面裸露砖墙搭配悬挂绿植，复古实木桌椅不成套错落有致，大理石吧台上意式咖啡机锃亮，黑板菜单粉笔字母充满艺术感，书架摆满小说与桌游，金色时光的温暖氛围', '/aid/lib/scene/2026/07/09/文艺咖啡厅·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/文艺咖啡厅·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (76, 'reference_scene', '高级西餐厅·夜·内景·冬·雪·无人', 'cinematic intimate shot of an upscale fine-dining restaurant interior at night, tables draped in pristine white linen with single rose in crystal vase, candlelight flickering on each table creating intimate ambiance, snow visible through tall arched windows, dark wood paneling and burgundy velvet banquette seating, wine cellar visible through glass wall, chandelier with warm dim lighting, romantic winter evening setting, photorealistic, 8K --ar 1:1', '高端Fine-dining西餐厅内景，每张桌铺洁白亚麻桌布水晶花瓶中单枝玫瑰，烛光摇曳营造私密氛围，高挑拱窗外可见冬雪飘落，深色实木墙裙配酒红色天鹅绒卡座，玻璃酒窖隐约可见，水晶吊灯投下温暖柔光', '/aid/lib/scene/2026/07/09/高级西餐厅·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/高级西餐厅·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (77, 'reference_scene', '电影院影厅内·夜·内景·夏·晴·无人', 'cinematic POV shot from middle row of an empty modern cinema auditorium, rows of plush red velvet seats descending toward large silver screen, the screen glowing with pre-show ambient blue light illuminating front rows, aisle lights casting subtle warm glow on carpeted steps, art deco wall sconces adding vintage charm, sound-absorbing textured wall panels, intimate and anticipatory atmosphere, photorealistic, 8K --ar 1:1', '空旷的现代影院放映厅内景，成排酒红色天鹅绒座椅向银幕倾斜，银幕散发映前环境蓝光照明前几排座椅，过道灯在铺毯台阶上投下柔和暖光，艺术装饰壁灯增添复古韵味，吸音纹理墙板，充满期待感的私密空间', '/aid/lib/scene/2026/07/09/电影院影厅内·夜·内景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/电影院影厅内·夜·内景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (78, 'reference_scene', '大型商场中庭·日·内景·夏·晴·无人', 'cinematic establishing shot from upper floor of a grand modern shopping mall atrium, soaring glass ceiling allowing bright summer sunlight to flood the space, multiple levels of white balconies with glass railings, massive suspended kinetic art sculpture in the center, escalators crisscrossing between floors, luxury brand storefronts with illuminated logos, polished white marble floors reflecting natural light, indoor palm trees and modern seating pods, upscale commercial atmosphere, photorealistic, 8K --ar 1:1', '宏伟现代购物中心中庭高层俯拍，玻璃穹顶让夏日阳光倾泻而下，多层白色阳台配玻璃栏杆层层环绕，巨型动态艺术装置悬挂正中，自动扶梯在各层交叉穿梭，奢侈品牌店面Logo发光，白色大理石地面如镜般反射自然光', '/aid/lib/scene/2026/07/09/大型商场中庭·日·内景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/大型商场中庭·日·内景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (79, 'reference_scene', '城市天台酒吧·夜·外景·夏·晴·无人', 'cinematic wide shot of a chic rooftop cocktail bar at night, panoramic view of glittering city skyline with skyscraper lights reflecting on a river below, stylish lounge seating with fire pit tables casting warm orange glow, string lights overhead creating magical canopy, sleek bar counter with illuminated glass shelves of bottles, warm summer night breeze suggested by gently swaying plants, infinity edge giving floating sensation, sophisticated and romantic, photorealistic, 8K --ar 1:1', '时尚屋顶露天酒吧夜景，璀璨城市天际线全景，摩天大楼灯光倒映下方河流，时尚躺椅配燃气火炉桌散发暖橙色光，头顶串灯交织如梦似幻，流线型吧台后酒瓶玻璃架被照亮，夏日暖风微拂', '/aid/lib/scene/2026/07/09/城市天台酒吧·夜·外景·夏·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/城市天台酒吧·夜·外景·夏·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (80, 'reference_scene', '金銮殿·日·内景·秋·晴·无人', 'cinematic wide establishing shot of the grand imperial throne hall of an ancient Chinese palace, massive gold-plated dragon throne on a raised platform with nine steps, towering red lacquered columns with intricate golden dragon carvings coiled around them, sunlight streaming through high latticed windows creating beams of light in incense-scented air, gleaming golden floor tiles reflecting the light, imperial yellow silk banners hanging from high ceiling with dragon motifs, solemn and majestic autumn atmosphere, ancient Chinese palatial photorealistic style, 8K --ar 1:1', '中国古代皇宫正殿气势恢宏，九级台阶上巨型鎏金龙椅居中高置，红色巨柱高耸盘绕金色龙纹浮雕，高窗格栅透入的日光在香火氤氲中化为光束，金色地砖如镜反光，明黄绸缎龙纹巨幅从高耸天花垂落', '/aid/lib/scene/2026/07/09/金銮殿·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/金銮殿·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (81, 'reference_scene', '御花园·日·外景·春·晴·无人', 'cinematic panorama of imperial palace garden in spring, winding paths of white pebbles through blooming peach and plum trees with pink and white petals drifting in breeze, an ornate pavilion with upturned eaves and blue-glazed roof tiles beside a koi pond, stone bridges arching over water reflecting blue sky, carefully manicured bonsai and rock formations, butterflies among flowers, soft golden spring sunlight creating dreamlike atmosphere, peaceful and elegant, ancient Chinese garden photorealistic, 8K --ar 1:1', '皇宫御花园春日盛景，白色鹅卵石蜿蜒小径穿过盛开桃花李花林，粉白花瓣随风飘落，飞檐蓝琉璃瓦凉亭伫立锦鲤池畔，石拱桥跨越水面倒映蓝天，盆景与假山精心布置，蝴蝶飞舞花间', '/aid/lib/scene/2026/07/09/御花园·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/御花园·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (82, 'reference_scene', '后宫庭院·夜·外景·秋·雾·无人', 'cinematic atmospheric night scene of an imperial harem courtyard, rows of red palace lanterns casting warm red glow through autumn fog, cobblestone courtyard with fallen golden ginkgo leaves scattered, elegant palace architecture with carved wooden lattice windows showing faint candlelight within, stone lanterns along pathway emitting soft light, a swing hanging from an old locust tree in the corner, misty and melancholic atmosphere, full moon partially visible through fog, ancient Chinese palace photorealistic, 8K --ar 1:1', '深夜后宫庭院，成排红色宫灯在秋雾中投下暖红光影，卵石地面散落金黄银杏落叶，精雕木格窗中透出微弱烛光，石灯笼沿路散发柔和光芒，庭院角落老槐树下秋千静悬，满月半掩于雾中', '/aid/lib/scene/2026/07/09/后宫庭院·夜·外景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/后宫庭院·夜·外景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (83, 'reference_scene', '御书房·夜·内景·冬·雪·无人', 'cinematic intimate shot of the emperor\'s private study at night, walls lined with ancient scrolls and books in dark rosewood shelves, large zitan wood desk with inkstone brush holder and half-unrolled memorial scroll, bronze incense burner releasing thin smoke tendrils, single dragon-patterned palace lantern providing warm focused light, snow visible through paper-latticed window accumulating on sill, thick silk carpets on the floor, solemn and scholarly atmosphere with imperial authority, ancient Chinese interior photorealistic, 8K --ar 1:1', '深夜皇帝御书房，深色紫檀书架满墙陈列古籍卷轴，大紫檀书案上摆着砚台笔架和半展的奏折，铜香炉青烟袅袅，一盏龙纹宫灯投下集中暖光，纸格窗外可见积雪覆窗棂，地面铺着厚丝毯', '/aid/lib/scene/2026/07/09/御书房·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/御书房·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (84, 'reference_scene', '王府正厅·日·内景·秋·晴·无人', 'cinematic wide shot of the main hall of a prince\'s mansion, dark nanmu wood furniture with intricate mother-of-pearl inlay, large tiger skin rug on polished stone floor, calligraphy scrolls and landscape paintings mounted on walls, antique porcelain vases on carved display stands, warm autumn sunlight filtering through lattice windows casting geometric shadows, tea set arranged on a side table, wealthy and refined ancient noble atmosphere, dignified but less formal than imperial palace, ancient Chinese interior photorealistic, 8K --ar 1:1', '王府正厅内景，暗色楠木家具镶嵌精美螺钿，虎皮大毯铺于光洁石地，墙面悬挂名家书法与山水立轴，古董瓷瓶陈列于雕花展架，秋日暖阳透过格窗投下几何光影，茶具摆放在侧几上', '/aid/lib/scene/2026/07/09/王府正厅·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/王府正厅·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (85, 'reference_scene', '王府后花园·夜·外景·夏·雾·无人', 'cinematic atmospheric garden shot of the rear garden of a prince\'s mansion at night, serene lotus pond reflecting full summer moon, fireflies glowing and drifting among weeping willows and bamboo groves, stone pathways winding through rock gardens, small pavilion with silk curtains slightly billowing in warm breeze, ancient pine trees silhouetted against moonlit sky, ground mist hovering over water creating ethereal atmosphere, elegant and mysterious, ancient Chinese garden photorealistic, 8K --ar 1:1', '深夜王府后花园，宁静荷塘倒映盛夏满月，萤火虫在垂柳与竹林间飞舞发光，石径蜿蜒穿过假山石园，凉亭纱帘在暖风中微拂，古松剪影映衬月色，水面薄雾营造空灵意境', '/aid/lib/scene/2026/07/09/王府后花园·夜·外景·夏·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/王府后花园·夜·外景·夏·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (86, 'reference_scene', '王府书房·夜·内景·冬·雪·无人', 'cinematic warm interior shot of a prince\'s private study at night, tall rosewood bookshelves filled with ancient texts and scrolls, large writing desk with fine brush set and unfinished mountain landscape painting, bronze charcoal brazier providing warmth and soft orange light, snow building up on window lattice outside visible through paper panes, ceremonial sword displayed on weapon rack on the wall, thick brocade cushions on carved chairs, scholarly and refined atmosphere with subtle military undertones, ancient Chinese study photorealistic, 8K --ar 1:1', '深夜王爷书房，紫檀书架高耸满载古籍卷轴，大书案上文房四宝齐备未竟山水画铺展，铜炭火盆散发温暖橙色柔光，纸窗外积雪渐厚覆满窗棂，墙上兵器架陈列宝剑，儒雅中暗含将门之气', '/aid/lib/scene/2026/07/09/王府书房·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/王府书房·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (87, 'reference_scene', '古镇街道·日·外景·春·晴·无人', 'cinematic tracking shot of an ancient Chinese town street in spring, centuries-old cobblestone road winding between traditional wooden buildings with grey-tiled roofs and upturned eaves, red silk lanterns hanging from every shopfront gently swaying, wooden signboards with golden calligraphy, cherry blossom petals drifting through air and settling on stone path, small stone bridge arching over clear canal in distance, warm spring sunlight creating dappled patterns, lively and picturesque wuxia atmosphere, ancient Chinese town photorealistic, 8K --ar 1:1', '春日中国古镇街道，数百年卵石路蜿蜒于传统木构建筑之间，灰瓦飞檐连绵，红绸灯笼自每家铺面垂下轻摆，木质招牌金色书法赫然，樱花花瓣飘落石径，远处小石桥拱跨清澈水渠，暖春阳光投下斑驳光影', '/aid/lib/scene/2026/07/09/古镇街道·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/古镇街道·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (88, 'reference_scene', '竹林深处·日·外景·秋·雾·无人', 'cinematic low-angle wide shot deep within a vast bamboo forest, towering green bamboo stalks stretching endlessly upward with golden autumn light filtering through canopy, narrow dirt path winding into misty depths, fallen bamboo leaves covering ground in warm brown tones, ground fog swirling around base of bamboo creating otherworldly atmosphere, sunlight creating dramatic beams through mist and leaves, utterly peaceful and meditative, iconic wuxia landscape, photorealistic, 8K --ar 1:1', '莽莽竹林深处仰拍广角，翠绿竹竿冲天而起望不到顶，秋日金光透过密叶洒落，窄土路蜿蜒没入迷雾深处，落叶覆地呈温暖棕色，地面雾气在竹根间缭绕如仙境，阳光穿过雾与叶形成戏剧性光束', '/aid/lib/scene/2026/07/09/竹林深处·日·外景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/竹林深处·日·外景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (89, 'reference_scene', '江湖客栈大堂·夜·内景·冬·雪·无人', 'cinematic wide interior shot of the main hall of an ancient Chinese inn at night, wooden tables and benches arranged across ground floor with grand staircase leading to upper rooms, warm lantern light from paper lamps hanging from dark wood beams, large wine jar display behind the counter, snow visible through open doorway with heavy cotton curtain partially drawn, cooking smoke drifting from kitchen area, swords and travel packs leaning against walls suggesting travelers, warm and rustic wuxia atmosphere, ancient Chinese inn photorealistic, 8K --ar 1:1', '深夜古代客栈大堂，木桌条凳遍布一楼大厅，宏大楼梯通向楼上客房，纸灯笼自黑木横梁垂下散发暖光，柜台后巨坛美酒高高陈列，敞开的门口厚棉帘半掀，门外可见落雪，厨房方向飘来炊烟', '/aid/lib/scene/2026/07/09/江湖客栈大堂·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/江湖客栈大堂·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (90, 'reference_scene', '悬崖绝壁·日·外景·秋·雾·无人', 'cinematic extreme wide shot of a dramatic cliff edge in the mountains, lone ancient pine tree growing horizontally from cliff face, swirling mist in vast valley below creating sea of clouds, distant mountain peaks piercing through fog like islands, weathered stone platform at cliff edge with ancient sword marks, golden autumn light from setting sun casting long shadows and painting clouds orange and pink, epic and awe-inspiring wuxia landscape, photorealistic ancient Chinese landscape, 8K --ar 1:1', '群山之巅绝壁极广角画面，一棵孤松自崖壁横向生长，谷底云雾翻涌如海，远山峰顶刺破雾海如孤岛，崖边风化石台残留远古剑痕，秋日夕阳金光拉长阴影将云海染成橙粉', '/aid/lib/scene/2026/07/09/悬崖绝壁·日·外景·秋·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/悬崖绝壁·日·外景·秋·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (91, 'reference_scene', '古代集市·日·外景·春·晴·无人', 'cinematic wide street shot of a vibrant ancient Chinese market, vendors\' stalls with colorful silk canopies lining both sides of dirt road, baskets overflowing with exotic fruits, spices in woven sacks, bolts of colorful silk fabric draped over wooden racks, street food stalls with steam rising from bamboo steamers, terracotta roof tiles on surrounding buildings, temple roof visible in distance, warm spring morning light creating lively atmosphere, rich daily life in ancient China, photorealistic, 8K --ar 1:1', '热闹的中国古代集市街景，各色丝绸华盖摊位沿土路两侧排开，柳条篮中异域水果满溢，麻袋装香料成堆，木架上各色丝绸布匹垂挂，竹蒸笼蒸汽升腾的小吃摊，四周建筑陶瓦屋顶，远方庙宇屋顶隐约可见', '/aid/lib/scene/2026/07/09/古代集市·日·外景·春·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/古代集市·日·外景·春·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (92, 'reference_scene', '古风茶馆·日·内景·秋·雨·无人', 'cinematic intimate interior shot of an elegant traditional Chinese tea house, dark rosewood tables and stools arranged across polished floor, tea master\'s station with full gongfu tea set and copper kettle steaming gently, antique scrolls of calligraphy on walls, bamboo blinds partially lowered over open windows showing autumn rain falling on small courtyard garden, soft daylight filtering through paper lanterns, warm and tranquil atmosphere, ancient Chinese tea house photorealistic, 8K --ar 1:1', '雅致中国传统茶馆内景，深色红木桌椅在光洁地面错落分布，茶艺台上一套功夫茶具配铜壶蒸汽袅袅，墙面悬挂古书法卷轴，竹帘半垂，敞开的窗外可见秋雨洒落小天井花园，纸灯笼滤出柔和日光', '/aid/lib/scene/2026/07/09/古风茶馆·日·内景·秋·雨·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/古风茶馆·日·内景·秋·雨·无人.png');
INSERT INTO `aid_comic_asset` VALUES (93, 'reference_scene', '运河码头·夜·外景·夏·雾·无人', 'cinematic waterfront shot of an ancient canal dock at night, wooden fishing boats and cargo junks moored along stone embankment with lanterns reflecting in dark water, wooden planks of pier worn smooth by years of use, fog rolling in from water creating mysterious atmosphere, silhouette of three-arch stone bridge in background, wooden warehouses and taverns along waterfront with warm light glowing through windows, humid summer night, atmospheric ancient Chinese noir setting, photorealistic, 8K --ar 1:1', '深夜古运河码头，木渔船与货船沿石堤停泊，船上灯笼倒映幽暗水面，码头木板经年踩踏已磨得光滑，水面雾气弥漫营造神秘氛围，远方三孔石桥剪影朦胧，岸边木造仓库酒馆窗中透出暖光', '/aid/lib/scene/2026/07/09/运河码头·夜·外景·夏·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/运河码头·夜·外景·夏·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (94, 'reference_scene', '仙山云海·日·外景·春·雾·无人', 'cinematic aerial establishing shot of a breathtaking immortal realm mountain peak rising above sea of clouds at sunrise, ancient Taoist temple complex with flying eaves and golden-glazed roof tiles clinging to mountainside, stone steps carved into cliff leading upward through swirling mist, ancient cypress trees with twisting branches, waterfall cascading from higher peak disappearing into cloud sea below, cranes flying in distance, golden and pink dawn light illuminating scene with divine radiance, epic transcendent xianxia atmosphere, Chinese mythology photorealistic style, 8K --ar 1:1', '日出时分仙境山峰破云而出，古道教宫观飞檐金琉璃瓦依附山腰而立，石阶凿入悬崖盘旋向上没入雾中，古柏虬枝苍劲，高处瀑布飞泻坠入云海之下，远方仙鹤翱翔，金粉晨曦照耀万物如同神迹', '/aid/lib/scene/2026/07/09/仙山云海·日·外景·春·雾·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/仙山云海·日·外景·春·雾·无人.png');
INSERT INTO `aid_comic_asset` VALUES (95, 'reference_scene', '仙门大殿·日·内景·秋·晴·无人', 'cinematic wide interior shot of the grand hall of an immortal sect, towering white jade pillars carved with dragon and phoenix motifs reaching to ceiling painted with constellations, floating crystal throne on central dais radiating soft blue light, spiritual energy visible as floating particles of light throughout the hall, ancient formation patterns glowing faintly on polished white jade floor, incense burners emitting ethereal smoke that forms mystical shapes, open walls revealing mountain peaks and cloud sea beyond, divine and otherworldly autumn atmosphere, photorealistic xianxia style, 8K --ar 1:1', '仙门宗派大殿内景，高耸白玉巨柱雕龙刻凤直达绘满星图的天花板，中央高台水晶王座悬浮散发淡蓝柔光，灵气化为光点漂浮满殿，古阵法纹样在白玉地面上微微发光，香炉飘出袅袅仙烟幻化妙形，开放墙壁外可见仙山云海', '/aid/lib/scene/2026/07/09/仙门大殿·日·内景·秋·晴·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/仙门大殿·日·内景·秋·晴·无人.png');
INSERT INTO `aid_comic_asset` VALUES (96, 'reference_scene', '魔域暗殿·夜·内景·冬·雪·无人', 'cinematic dramatic shot of a dark throne hall in the demon realm, obsidian pillars carved with writhing demon faces glowing with faint crimson light, massive throne made of black iron and bone on volcanic rock platform, dark purple and red spiritual energy swirling in the air, eerie bioluminescent crystals embedded in walls providing only light, chains hanging from impossibly high ceiling disappearing into darkness, frost forming on stone floor despite hellish aura, oppressive and malevolent winter atmosphere, dark fantasy xianxia style, photorealistic, 8K --ar 1:1', '魔域黑暗王座大殿，黑曜石柱上恶魔面孔浮雕散发微弱猩红光芒，黑铁与骨骸铸就的王座矗立在火山岩台基上，紫黑色灵气在空中翻涌，墙内嵌生物荧光水晶是唯一光源，铁链自不可见之顶垂下没入黑暗，冰霜覆于石地', '/aid/lib/scene/2026/07/09/魔域暗殿·夜·内景·冬·雪·无人.png', '0', NULL, '', NULL, '', '/aid/lib/scene/2026/07/09/魔域暗殿·夜·内景·冬·雪·无人.png');
INSERT INTO `aid_comic_asset` VALUES (97, 'reference_character', '霸道总裁·男·28-35岁', 'cinematic portrait of a handsome young Chinese CEO, 30 years old, sharp angular jawline, intense deep-set eyes with piercing gaze, well-groomed slicked-back black hair, tall athletic build, wearing a perfectly tailored dark charcoal three-piece suit with white dress shirt slightly unbuttoned at collar, Patek Philippe watch on wrist, standing in front of floor-to-ceiling windows overlooking city skyline, confident powerful posture, slight frown, cold and domineering aura, photorealistic, 8K --ar 1:1', '冷峻凌厉的年轻商界精英，五官深邃棱角分明，剑眉星目，身高185+宽肩窄腰，定制深色西装三件套，白衬衫解开第一颗扣，腕间百达翡丽，短发利落后梳，气场强大微蹙眉头眼神锐利', '/aid/lib/character/2026/07/09/霸道总裁·男·28-35岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/霸道总裁·男·28-35岁.png');
INSERT INTO `aid_comic_asset` VALUES (98, 'reference_character', '灰姑娘女主·女·22-26岁', 'cinematic portrait of a beautiful young Chinese woman, 24 years old, delicate oval face with clear porcelain skin, large innocent almond-shaped eyes with a hint of determination, long straight black hair flowing over shoulders, slender petite figure, wearing a simple white blouse with light blue jeans and white canvas sneakers, canvas crossbody bag, natural minimal makeup, warm gentle expression with quiet resilience, standing on a sunlit street, photorealistic, 8K --ar 1:1', '清纯坚韧的普通女孩，鹅蛋脸白皙素净，杏眼清澈明亮带一丝倔强，黑长直发披肩，身材纤细娇小，穿着简约白色衬衫配浅蓝牛仔裤帆布鞋，斜挎帆布包，淡妆或素颜，善良温暖中透出不屈', '/aid/lib/character/2026/07/09/灰姑娘女主·女·22-26岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/灰姑娘女主·女·22-26岁.png');
INSERT INTO `aid_comic_asset` VALUES (99, 'reference_character', '豪门千金·恶毒女配·女·25-30岁', 'cinematic portrait of a stunning wealthy Chinese socialite, 28 years old, sharp v-shaped face with flawless makeup and dramatic winged eyeliner, seductive foxy eyes, long wavy chestnut brown hair cascading down, curvaceous figure, wearing an elegant figure-hugging red evening gown with a thigh slit, sparkling diamond necklace and drop earrings, designer clutch in hand, glossy red lips curved in a haughty smirk, cold condescending gaze, photorealistic, 8K --ar 1:1', '精致美艳的富家千金，瓜子脸妆容精致，眼线上挑媚眼如丝，波浪大卷长发栗棕色，身材凹凸有致，身穿红色或黑色修身晚礼服，钻石项链与耳坠闪耀，手拿名牌手包，红唇微勾神情高傲带刺', '/aid/lib/character/2026/07/09/豪门千金·恶毒女配·女·25-30岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/豪门千金·恶毒女配·女·25-30岁.png');
INSERT INTO `aid_comic_asset` VALUES (100, 'reference_character', '温柔男二·医生·男·26-32岁', 'cinematic portrait of a gentle warm-hearted Chinese man, 29 years old, soft handsome features with kind smiling eyes, slightly wavy medium-length brown hair, slender build, wearing a cream-colored cashmere sweater over a light blue collared shirt, delicate thin-rimmed glasses, warm friendly smile, clean well-groomed appearance, standing by a sunlit window in a cozy coffee shop, gentle healing aura, photorealistic, 8K --ar 1:1', '温润如玉的暖男，五官清秀柔和，眼神温暖含笑，蓬松中短发微卷，身高178-183身材修长不壮硕，米色针织衫或浅蓝衬衫配卡其裤，戴细框眼镜，手指修长干净，周身散发着治愈系温暖气质', '/aid/lib/character/2026/07/09/温柔男二·医生·男·26-32岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/温柔男二·医生·男·26-32岁.png');
INSERT INTO `aid_comic_asset` VALUES (101, 'reference_character', '冷酷保镖·男·28-38岁', 'cinematic portrait of a stoic Chinese bodyguard, 33 years old, chiseled square jaw with hard angular features, piercing hawk-like vigilant eyes, buzz cut military hairstyle, tall muscular build towering at 190cm, wearing a fitted black tactical suit with black turtleneck underneath, concealed earpiece visible, scarred knuckles from training, stern expressionless face, intimidating protective presence, standing alert in a dim corridor, photorealistic, 8K --ar 1:1', '冷硬专业的高级保镖，国字脸线条硬朗如刀削，眼神如鹰隼般锐利警觉，极短寸头，身高188+肌肉结实但不夸张，黑色修身战术西装内搭黑色高领，佩戴隐形耳麦，手上有训练老茧，面无表情气势逼人', '/aid/lib/character/2026/07/09/冷酷保镖·男·28-38岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/冷酷保镖·男·28-38岁.png');
INSERT INTO `aid_comic_asset` VALUES (102, 'reference_character', '职场OL·秘书·女·24-28岁', 'cinematic portrait of a professional Chinese office lady, 26 years old, neat pleasant features with light professional makeup, medium-length dark hair tied in a low sleek ponytail, well-proportioned figure, wearing a tailored navy blue business suit with pencil skirt and crisp white blouse, simple elegant wristwatch, holding a tablet and documents, black modest heels, focused competent expression, standing in a bright modern office, photorealistic, 8K --ar 1:1', '干练职业的办公室女性，五官端正大方淡妆得体，中长发扎低马尾或盘起，身材匀称，深色修身西装套裙配白衬衫，黑色中跟皮鞋，腕间简约手表，手拿文件夹或平板，专注认真的职业表情', '/aid/lib/character/2026/07/09/职场OL·秘书·女·24-28岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/职场OL·秘书·女·24-28岁.png');
INSERT INTO `aid_comic_asset` VALUES (103, 'reference_character', '实习小白·职场新人·女·21-24岁', 'cinematic portrait of a fresh young Chinese intern, 22 years old, round youthful face with soft baby fat, large curious nervous eyes, black hair with neat bangs tied in a ponytail, petite small frame, wearing a slightly oversized new navy business suit that still looks a bit stiff, large commuter tote bag on shoulder, clutching a thick stack of files, eager but slightly flustered expression, standing in a modern office lobby, photorealistic, 8K --ar 1:1', '青涩稚嫩的应届毕业生，圆脸带婴儿肥眼睛大而好奇又有些紧张，黑发齐刘海扎马尾，身材娇小，穿着略不合身的新买职业装，背着大号通勤包，手里抱着厚厚的文件夹，努力认真但略带慌张', '/aid/lib/character/2026/07/09/实习小白·职场新人·女·21-24岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/实习小白·职场新人·女·21-24岁.png');
INSERT INTO `aid_comic_asset` VALUES (104, 'reference_character', '精英女强人·总监·女·30-38岁', 'cinematic portrait of a powerful Chinese executive woman, 34 years old, striking defined features with sharp sophisticated makeup, eyes radiating authority and decisiveness, sleek chin-length bob hairstyle, tall statuesque figure, wearing an expensive tailored white power suit with a silk champagne blouse underneath, Jaeger-LeCoultre watch, stiletto heels, one hand casually in pocket, commanding confident posture, standing in a high-rise corner office, photorealistic, 8K --ar 1:1', '气场强大的职场女王，轮廓分明妆容精致凌厉，眼中透着杀伐决断，短发干练或波浪盘发，身材高挑气场一米八，高级定制白色或灰色西装套装配真丝衬衫，细高跟鞋腕间积家手表，单手插兜姿态自信', '/aid/lib/character/2026/07/09/精英女强人·总监·女·30-38岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/精英女强人·总监·女·30-38岁.png');
INSERT INTO `aid_comic_asset` VALUES (105, 'reference_character', '中年老板·董事长·男·45-55岁', 'cinematic portrait of a distinguished middle-aged Chinese business magnate, 50 years old, weathered distinguished face with fine lines around wise penetrating eyes, salt-and-pepper hair neatly combed at the temples, well-maintained build with slight middle-age bulk, wearing an elegant tailored dark navy mandarin-collar suit, holding a fine porcelain teacup, calm authoritative presence, sitting in a luxurious leather armchair in a wood-paneled office, photorealistic, 8K --ar 1:1', '沉稳威严的中年企业家，眼角已有细纹但不减锐利，眼神洞悉世事，头发微灰两鬓染霜，身材保持良好微有肚腩，定制深灰或藏蓝中山装立领西装，手持雪茄或茶杯，气场沉稳如山', '/aid/lib/character/2026/07/09/中年老板·董事长·男·45-55岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/中年老板·董事长·男·45-55岁.png');
INSERT INTO `aid_comic_asset` VALUES (106, 'reference_character', '知性闺蜜·律师·女·26-32岁', 'cinematic portrait of an intellectual Chinese professional woman, 29 years old, elegant intelligent features with tortoiseshell glasses, medium-length soft wavy hair naturally styled, slim graceful figure, wearing a smart tailored grey vest over a silk blouse paired with wide-leg trousers, holding a coffee cup with both hands, warm knowing smile with a hint of playful wisdom, sitting by the window in a stylish cafe, photorealistic, 8K --ar 1:1', '理性又仗义的知性女性，五官知性优雅，戴细框或玳瑁眼镜，中长发微卷自然披散，身材苗条，穿着剪裁利落的西装马甲配阔腿裤或修身连衣裙，手握咖啡杯或文件夹，表情理性中带一丝俏皮', '/aid/lib/character/2026/07/09/知性闺蜜·律师·女·26-32岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/知性闺蜜·律师·女·26-32岁.png');
INSERT INTO `aid_comic_asset` VALUES (107, 'reference_character', '外卖·快递小哥·男·20-28岁', 'cinematic portrait of a young Chinese delivery rider, 24 years old, healthy sun-kissed wheat complexion, bright energetic eyes full of determination, short neat black hair, lean wiry build, wearing a bright yellow delivery platform uniform jacket with reflective stripes, safety helmet tucked under arm, electric scooter keys clipped to belt, slight sweat on brow but a genuine bright smile, standing beside his scooter on a busy street, photorealistic, 8K --ar 1:1', '朴实阳光的年轻劳动者，皮肤因日晒呈健康小麦色，眼神明亮有干劲，短发清爽，身材精瘦结实，穿着黄色或蓝色外卖平台工服头戴安全头盔，电动车钥匙挂在腰间，汗水浸湿衣领但笑容灿烂', '/aid/lib/character/2026/07/09/外卖·快递小哥·男·20-28岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/外卖·快递小哥·男·20-28岁.png');
INSERT INTO `aid_comic_asset` VALUES (108, 'reference_character', '夜市摊主·市井大叔·男·35-45岁', 'cinematic portrait of a hearty middle-aged Chinese street food vendor, 40 years old, round ruddy face with deep laugh lines around crinkly warm eyes, stocky strong build with powerful arms from years of wok cooking, wearing a white tank top under a well-worn apron, a white hand towel draped around his neck, holding a well-used metal wok spatula, broad genuine grin, standing in front of his steaming food stall at night, photorealistic, 8K --ar 1:1', '热情豪爽的市井中年，圆脸微胖面色红润，笑起来眼角满是褶子，手臂粗壮有力常年在灶台前忙碌，穿白色背心或宽松T恤外罩围裙，脖子上搭一条白毛巾，手拿炒勺或蒲扇，市井烟火气十足', '/aid/lib/character/2026/07/09/夜市摊主·市井大叔·男·35-45岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/夜市摊主·市井大叔·男·35-45岁.png');
INSERT INTO `aid_comic_asset` VALUES (109, 'reference_character', '咖啡店老板·文艺青年·男·25-32岁', 'cinematic portrait of an artistic young Chinese cafe owner, 28 years old, lean sensitive face with slightly unkempt charm, warm but slightly distant contemplative eyes, shoulder-length slightly wavy hair loosely tied back, slender artistic build, wearing a rumpled linen shirt under a striped apron, wooden beaded bracelets on wrist, faint coffee stains on fingers, quiet observant expression, leaning against the counter of his cozy book-filled cafe, photorealistic, 8K --ar 1:1', '文艺气息的温暖青年，清瘦面孔略带不羁，眼神温暖又带疏离感，微长卷发随意扎起或披散，身材清瘦，穿着亚麻衬衫或条纹围裙，手腕有几串木质手串，手指有颜料或咖啡渍，安静观察者的气质', '/aid/lib/character/2026/07/09/咖啡店老板·文艺青年·男·25-32岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/咖啡店老板·文艺青年·男·25-32岁.png');
INSERT INTO `aid_comic_asset` VALUES (110, 'reference_character', '网约车司机·男·30-45岁', 'cinematic portrait of an ordinary middle-aged Chinese ride-share driver, 38 years old, average weary but kind face, observant eyes that have seen countless stories, slightly receding hairline, mild dad-bod build, wearing a comfortable striped polo shirt and casual jacket, phone mounted on dashboard with ride-hailing app visible, thermal flask and mints on the console, half-turned from driver seat looking back with a knowing patient expression, warm interior car lighting, photorealistic, 8K --ar 1:1', '平凡又有人情味的中年司机，普通中年面孔略显疲惫，眼睛通过后视镜观察一切，略秃顶或发际线后退，微胖体型，穿休闲Polo衫或宽松夹克，脖子上挂手机支架，车里仪表台放着保温杯和薄荷糖', '/aid/lib/character/2026/07/09/网约车司机·男·30-45岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/网约车司机·男·30-45岁.png');
INSERT INTO `aid_comic_asset` VALUES (111, 'reference_character', '老城区大爷·男·60-70岁', 'cinematic portrait of a spirited elderly Chinese man, 65 years old, weathered thin face with deep character lines, shrewd knowing eyes that miss nothing, short grey-white hair, lean slightly stooped frame, wearing a classic worn blue Mao suit jacket over a white undershirt, holding a well-used palm-leaf fan and a small portable radio, black cloth shoes, warm wrinkled smile hiding street-smart wisdom, sitting on a wooden stool in an old alleyway, photorealistic, 8K --ar 1:1', '悠闲又精明的老城区原住民，饱经风霜的瘦削面孔，眼神透着市井智慧，花白短发，身材清瘦微驼，穿着白色老头背心或旧中山装，手拿蒲扇和收音机，脚踩布鞋，笑容可掬实则门清', '/aid/lib/character/2026/07/09/老城区大爷·男·60-70岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/老城区大爷·男·60-70岁.png');
INSERT INTO `aid_comic_asset` VALUES (112, 'reference_character', '初恋白月光·女·18-24岁', 'cinematic portrait of an ethereal young Chinese woman, 20 years old, flawless porcelain skin glowing softly, extraordinarily clear innocent eyes, long flowing black hair with wispy bangs dancing in breeze, slender delicate figure, wearing a simple white cotton dress that catches the sunlight, white canvas shoes, a subtle luminous halo effect around her, gentle bittersweet smile with a touch of sadness, standing under cherry blossom trees in golden afternoon light, dreamlike nostalgic atmosphere, photorealistic, 8K --ar 1:1', '纯净美好的少女，瓷白肌肤吹弹可破，清澈眼眸不染尘埃，黑色长发飘飘刘海轻盈，身材纤细柔软，白色棉布连衣裙或校服白衬衫，帆布鞋，周身笼罩着淡淡光晕般的美好与易碎感', '/aid/lib/character/2026/07/09/初恋白月光·女·18-24岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/初恋白月光·女·18-24岁.png');
INSERT INTO `aid_comic_asset` VALUES (113, 'reference_character', '富二代纨绔·男·22-28岁', 'cinematic portrait of a rakish wealthy young Chinese playboy, 25 years old, handsome face with a perpetual mischievous smirk, flirtatious playful eyes, stylishly dyed ash-brown hair swept casually, tall lean build, wearing an expensive designer patterned silk shirt with top buttons undone revealing a silver chain, diamond stud earring, flashy luxury watch, one hand in pocket, cocky self-assured posture, leaning against a sports car at a rooftop bar at night, photorealistic, 8K --ar 1:1', '玩世不恭的富家公子，痞帅面孔带着玩味的笑容，桃花眼多情又漫不经心，染发或挑染潮色，身材高挑衣着张扬，穿各色奢侈品牌潮牌休闲装，大金表钻石耳钉，单手插兜嘴角上扬', '/aid/lib/character/2026/07/09/富二代纨绔·男·22-28岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/富二代纨绔·男·22-28岁.png');
INSERT INTO `aid_comic_asset` VALUES (114, 'reference_character', '叛逆少女·女·16-20岁', 'cinematic portrait of a rebellious Chinese teenage girl, 17 years old, thin angular face with defiant stubborn expression, slightly smudged self-applied dark eyeliner, dyed black hair with purple streaks, slender still-growing frame, wearing an oversized hoodie over a plaid mini skirt with combat boots, black choker necklace, temporary tattoo stickers on forearm, arms crossed defensively but eyes betraying vulnerability and longing, standing against a graffiti wall in an alley at dusk, photorealistic, 8K --ar 1:1', '倔强敏感的青春期女孩，清瘦面孔带着不服输的倔强，化着不太熟练的烟熏妆，黑发挑染紫色或蓝色，身材纤细未完全发育，穿宽松卫衣配短裙马丁靴戴choker项链，手臂有贴纸纹身，抱臂而立表情防御但眼底渴望温暖', '/aid/lib/character/2026/07/09/叛逆少女·女·16-20岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/叛逆少女·女·16-20岁.png');
INSERT INTO `aid_comic_asset` VALUES (115, 'reference_character', '温柔母亲·女·35-50岁', 'cinematic portrait of a warm gentle Chinese mother, 45 years old, soft kind face with fine smile lines around tender understanding eyes, black hair streaked with dignified silver threads neatly pinned up, slightly plump comforting build, wearing a cozy cream-colored knit cardigan over a simple blouse with a floral apron tied at the waist, holding a steaming cup of tea, warm maternal smile radiating unconditional love and home, standing in a sunlit cozy kitchen, photorealistic, 8K --ar 1:1', '慈爱包容的中年母亲，面容柔和眼角有细密笑纹，眼神温暖包容，黑发中夹杂几丝银发低盘或短发，身材微丰给人踏实感，穿素色开衫毛衣或棉麻家居服系着围裙，手里常端着一杯热茶或水果盘', '/aid/lib/character/2026/07/09/温柔母亲·女·35-50岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/温柔母亲·女·35-50岁.png');
INSERT INTO `aid_comic_asset` VALUES (116, 'reference_character', '深情父亲·男·38-50岁', 'cinematic portrait of a stoic loving Chinese father, 43 years old, weathered handsome face with quiet dignity, deep reserved eyes hiding unspoken love and concern, neat short hair with touches of grey at the temples, sturdy solid build, wearing a simple dark polo shirt with a practical jacket, an old but cherished watch on his wrist, rough capable hands that have worked hard, subtle gentle expression beneath the quiet exterior, standing beside his car looking out thoughtfully, photorealistic, 8K --ar 1:1', '沉默但深情的父亲，中年面孔略显沧桑但不失英俊，眼神深沉内敛藏着不表达的关爱，短发整齐微有白发，身材壮实或微胖，穿简约夹克或深色Polo衫，手腕戴旧手表，手掌粗糙有力，不善言辞但行动有力', '/aid/lib/character/2026/07/09/深情父亲·男·38-50岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/深情父亲·男·38-50岁.png');
INSERT INTO `aid_comic_asset` VALUES (117, 'reference_character', '冷面王爷·男·26-33岁', 'cinematic portrait of a cold commanding ancient Chinese prince, 30 years old, sharp sword-like eyebrows above piercing frost-cold phoenix eyes, angular chiseled features of devastating handsomeness, ink-black hair perfectly bound in a white jade crown, tall imposing figure, wearing a magnificent black brocade robe with subtle dark dragon patterns under a matching cloak with fur trim, jade belt with an ornate sword, powerful hands with prominent knuckles resting on a carved desk, cold unreadable expression radiating authority and danger, photorealistic ancient Chinese noble style, 8K --ar 1:1', '杀伐决断的冷峻王爷，剑眉入鬓冷眸如霜，五官如刀削斧劈般凌厉英俊，墨发以玉冠束起一丝不乱，身高185+，玄色或墨蓝暗纹锦袍外罩同色大氅，腰间玉带佩剑，指节分明的手轻叩桌面，气场令人不敢逼视', '/aid/lib/character/2026/07/09/冷面王爷·男·26-33岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/冷面王爷·男·26-33岁.png');
INSERT INTO `aid_comic_asset` VALUES (118, 'reference_character', '穿越庶女·王妃·女·18-24岁', 'cinematic portrait of a clever resilient young woman in ancient China, 20 years old, elegant oval face with refreshing natural beauty, lively intelligent eyes gleaming with modern wit and sharp perception, dark hair in simple maiden braids with a delicate silver hairpin, slender figure but with a straight determined posture, wearing a modest gracefully draped pale green ruqun with flowing sleeves, a small handmade charcoal pencil peeking from her sleeve, subtle knowing smile playing at her lips, standing in a moonlit ancient garden, photorealistic ancient Chinese palace style, 8K --ar 1:1', '聪慧机敏的穿越女/庶女，古典鹅蛋脸清丽脱俗，眼睛灵动有现代人的狡黠与清醒，乌发梳垂挂髻配简单银簪，身材纤细但脊背挺直，穿素雅的浅绿或月白色交领襦裙，袖中藏着自制的炭笔小本，唇角微扬心中有数', '/aid/lib/character/2026/07/09/穿越庶女·王妃·女·18-24岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/穿越庶女·王妃·女·18-24岁.png');
INSERT INTO `aid_comic_asset` VALUES (119, 'reference_character', '腹黑太子·男·22-30岁', 'cinematic portrait of a scheming handsome crown prince of ancient China, 27 years old, face as fine as carved jade with unnervingly perfect features, phoenix eyes curved in a gentle smile that never reaches their calculating depths, ink-black hair crowned with an elaborate gold guan, tall elegant figure, wearing a magnificent golden embroidered robe with five-clawed dragon motifs, holding a white jade ruyi scepter, surface warmth of a spring breeze but eyes cold as a winter lake, standing in a grand imperial hall, photorealistic ancient Chinese imperial style, 8K --ar 1:1', '城府极深的东宫太子，面如冠玉俊美非凡，凤眼含笑却不见底藏着算计，墨发金冠束顶，身材修长风度翩翩，明黄或朱红五爪龙纹蟒袍，手持折扇或玉如意，嘴角始终挂着温润如玉的微笑，眼底却是一片寒潭', '/aid/lib/character/2026/07/09/腹黑太子·男·22-30岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/腹黑太子·男·22-30岁.png');
INSERT INTO `aid_comic_asset` VALUES (120, 'reference_character', '倾城宠妃·女·18-26岁', 'cinematic portrait of a devastatingly beautiful imperial consort, 23 years old, exquisite heart-shaped face with mesmerizing peach-blossom eyes that captivate with every glance, luminous snow-white skin, elaborate cloud-bun hairstyle adorned with gold hairpins and dangling pearl ornaments, draped in a sumptuous pomegranate-red silk court gown with gold-thread phoenix embroidery and a sweeping train, red-painted fingernails holding an embroidered silk fan half-hiding her face, seductive yet calculating expression, standing in a lavish palace garden, photorealistic ancient Chinese imperial style, 8K --ar 1:1', '容貌倾国倾城的后宫宠妃，绝色瓜子脸桃花眼流转顾盼生辉，肌肤胜雪吹弹可破，青丝梳成华丽的朝云近香髻金步摇满头珠翠，身披华贵的石榴红或玫红织金宫装曳地长裙，指尖涂蔻丹持团扇半遮面，眼底野心与风情交织', '/aid/lib/character/2026/07/09/倾城宠妃·女·18-26岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/倾城宠妃·女·18-26岁.png');
INSERT INTO `aid_comic_asset` VALUES (121, 'reference_character', '少年剑客·男·16-22岁', 'cinematic portrait of a spirited young Chinese swordsman, 19 years old, handsome youthful face with boyish determination and wide-eyed wonder, clear bright eyes beneath sword-straight brows, long black hair tied in a high ponytail with a simple cloth band, lean agile build poised for action, wearing practical deep blue martial artist robes with fitted sleeves and leather bracers, a three-foot fine steel sword strapped across his back, clothes slightly travel-worn, brave hopeful expression, standing at the edge of a misty bamboo forest, photorealistic wuxia style, 8K --ar 1:1', '意气风发的初出江湖少年，俊朗青涩的面孔带着少年的锐气与好奇，剑眉星目眼神清澈明亮，黑发高马尾束起用布带随意绑着，身材清瘦但灵活有力，身穿青色或灰蓝色劲装短打，背负三尺青锋长剑，衣角微有风尘', '/aid/lib/character/2026/07/09/少年剑客·男·16-22岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/少年剑客·男·16-22岁.png');
INSERT INTO `aid_comic_asset` VALUES (122, 'reference_character', '江湖侠女·女·18-25岁', 'cinematic portrait of a fierce beautiful Chinese swordswoman, 22 years old, strikingly handsome features with a beauty that rivals any man, autumn-water eyes sharp with lethal grace, long black hair tied in a high warrior ponytail with flowing red ribbons, tall lithe athletic figure, wearing a form-fitting crimson martial arts outfit with a cinched waist and tight sleeves for combat, a flexible sword coiled at her hip, hand resting on the hilt ready to draw, proud fearless expression, standing atop a rocky outcrop with wind whipping her hair and ribbons, photorealistic wuxia style, 8K --ar 1:1', '英姿飒爽的红衣侠女，明艳五官英气逼人不输男儿，眼如秋水又含锋芒，墨发梳高马尾系红丝带随风飘扬，身材修长柔韧，一袭红衣劲装束腰窄袖，腰间缠绕软剑或长鞭，手握剑柄英姿勃发', '/aid/lib/character/2026/07/09/江湖侠女·女·18-25岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/江湖侠女·女·18-25岁.png');
INSERT INTO `aid_comic_asset` VALUES (123, 'reference_character', '茶馆老板娘·女·25-35岁', 'cinematic portrait of a captivating Chinese teahouse proprietress, 30 years old, mature alluring oval face with knowing phoenix eyes that switch between seductive half-lidded charm and razor-sharp perception, dark hair loosely pinned in an elegant lazy bun with a single jade hairpin, graceful voluptuous figure, wearing a deep purple embroidered fitted qipao-style dress, emerald bangle on her fair wrist, holding an elegant long-spout copper teapot mid-pour, welcoming smile with hidden steel, standing in her atmospheric lantern-lit teahouse, photorealistic ancient Chinese style, 8K --ar 1:1', '风情万种的消息灵通之人，成熟妩媚的鹅蛋脸，丹凤眼微眯时风情无限睁开时锐利洞察，乌发松松挽成慵懒髻斜插一根玉簪，身材丰腴有致，穿深紫或暗红绣花旗袍式改良襦裙，皓腕戴翡翠镯，手持长嘴铜壶斟茶，八面玲珑笑里藏刀', '/aid/lib/character/2026/07/09/茶馆老板娘·女·25-35岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/茶馆老板娘·女·25-35岁.png');
INSERT INTO `aid_comic_asset` VALUES (124, 'reference_character', '仙门师尊·男·外表30岁', 'cinematic portrait of an ageless transcendent immortal cultivator, appearing 35 years old, refined timeless face unmarked by age, eyes like ancient wells reflecting the cosmos itself, pure white hair half-bound with a simple jade hairpin the rest cascading like a silver waterfall, tall ethereal slender frame, wearing flowing pristine white Taoist robes with subtle cloud and crane embroidery, holding a white horsetail whisk, faint spiritual energy visible as luminescent particles around him, serene omniscient expression, floating above a sea of clouds at dawn, photorealistic xianxia style, 8K --ar 1:1', '仙风道骨的修行大成者，面容清隽看不出年龄痕迹，目如古井深邃有星辰流转，雪白长发以玉簪半束其余垂落如瀑，身材清瘦飘逸，纯白或浅青色广袖道袍绣有流云仙鹤暗纹，手持拂尘或背负古剑，周身淡淡灵气如烟', '/aid/lib/character/2026/07/09/仙门师尊·男·外表30岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/仙门师尊·男·外表30岁.png');
INSERT INTO `aid_comic_asset` VALUES (125, 'reference_character', '魔界少主·男·外表22-28岁', 'cinematic portrait of a dangerously beautiful demon realm prince, appearing 25 years old, unnervingly exquisite androgynous beauty, blood-red pupils that faintly glow in darkness, wild ink-purple hair cascading freely past his shoulders, pale translucent skin, tall lean body with subtle defined muscles, wearing an elaborate black and crimson brocade robe open at the chest revealing dark demonic markings on his collarbone, dark purple demonic energy swirling around him like smoke, seductive cruel smirk, sitting lazily on a throne of black iron and bone, photorealistic dark xianxia style, 8K --ar 1:1', '亦正亦邪的魔界继承人，极致的邪魅俊美雌雄莫辨，血色瞳孔在黑暗中微微发光，墨紫色长发不束不冠肆意披散，皮肤苍白近乎透明，身材修长肌肉精瘦，暗红与黑色交织的魔纹锦袍大敞领口露出锁骨与黑色魔纹，周身缭绕暗紫魔气', '/aid/lib/character/2026/07/09/魔界少主·男·外表22-28岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/魔界少主·男·外表22-28岁.png');
INSERT INTO `aid_comic_asset` VALUES (126, 'reference_character', '隐世高僧·老顽童·男·外表60-80岁', 'cinematic portrait of an eccentric enlightened old master, appearing 70 years old, round rosy-cheeked face with chrysanthemum-like laugh wrinkles, eyes usually squinted in mirth but occasionally flashing with profound wisdom, long white eyebrows and a flowing white beard merging into one majestic cascade, short roundish body that moves with surprising lightness, wearing simple patched but clean grey monk robes, a worn gourd of wine tied at his waist, holding a tattered palm-leaf fan, childlike mischievous grin that also holds the compassion of Buddha, sitting cross-legged on a rock amid swirling mountain mist, photorealistic xianxia style, 8K --ar 1:1', '深藏不露的世外高人，红光满面皱纹如菊却童颜鹤发，眼睛眯成一线偶尔精光乍现，雪白长眉垂落与长须白髯融为一体，身材矮小微胖但步伐轻盈，破旧但干净的灰色或黄色僧袍，腰间挂酒葫芦手持破蒲扇，笑容似孩童顽皮又似佛陀慈悲', '/aid/lib/character/2026/07/09/隐世高僧·老顽童·男·外表60-80岁.png', '0', NULL, '', NULL, '', '/aid/lib/character/2026/07/09/隐世高僧·老顽童·男·外表60-80岁.png');
INSERT INTO `aid_comic_asset` VALUES (127, 'reference_prop', '豪车钥匙·金属皮革', 'cinematic close-up product shot of a luxury car key fob, brushed silver metal casing with soft black leather key pouch embossed with subtle logo, placed on a dark polished mahogany desk surface, warm office lamp reflecting off the metal edges, shallow depth of field blurring the opulent background, symbol of wealth and power, photorealistic, 8K --ar 1:1', '顶级豪车品牌钥匙，银色金属外壳配真皮钥匙套，按键带品牌Logo镭射雕刻，放在深色木质桌面或真皮座椅上，低调却昭示身份，关联角色霸道总裁、富二代纨绔', '/aid/lib/prop/2026/06/17/豪车钥匙·金属皮革.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (128, 'reference_prop', '钻戒·珠宝盒·钻石铂金', 'cinematic close-up of an open navy blue velvet ring box, a stunning cushion-cut diamond solitaire ring nestled inside, platinum band with micro-pavé diamonds on the shoulders, brilliant fire and sparkle refracting under warm candlelight, gold-embossed luxury brand logo visible inside the lid, placed on a white linen tablecloth beside a single rose, romantic proposal atmosphere, photorealistic, 8K --ar 1:1', '打开的深蓝色天鹅绒戒指盒，内嵌一枚枕形切割大钻戒，铂金戒托密镶碎钻，盒盖内侧烫金品牌Logo，灯光下火彩璀璨，关联角色豪门千金、霸道总裁', '/aid/lib/prop/2026/06/17/钻戒·珠宝盒·钻石铂金.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (129, 'reference_prop', '名牌手包·皮革金属', 'cinematic product shot of an iconic luxury designer handbag, black quilted lambskin leather with gold-toned chain strap and signature turn-lock clasp, chain strap elegantly draped beside it, resting on a polished white marble surface, soft natural window light highlighting the leather texture and gold hardware, sophisticated and timeless, photorealistic, 8K --ar 1:1', '经典款奢侈品牌链条包，黑色荔枝纹小羊皮配金色五金件，翻盖上标志性菱格Logo扣，金属链条肩带垂落，放在大理石台面上，关联角色豪门千金、精英女强人', '/aid/lib/prop/2026/06/17/名牌手包·皮革金属.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (130, 'reference_prop', '雪茄与雪茄剪·烟草金属木材', 'cinematic close-up of a premium Cuban cigar resting on a Spanish cedar wood case, a stainless steel guillotine cigar cutter beside it, the dark oily wrapper of the cigar showing rich tobacco veins, a wisp of aromatic blue smoke curling upward from the tip, heavy crystal ashtray in the blurred background, warm amber lighting from a desk lamp, old money masculine atmosphere, photorealistic, 8K --ar 1:1', '古巴雪茄置于雪松木盒中，旁边一把断头台式不锈钢雪茄剪，木盒纹理细腻，雪茄深棕色茄衣泛着油光，烟灰缸中一缕青烟袅袅升起，关联角色中年董事长、霸道总裁', '/aid/lib/prop/2026/06/17/雪茄与雪茄剪·烟草金属木材.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (131, 'reference_prop', '笔记本电脑·金属玻璃', 'cinematic desk-level shot of a sleek silver ultrabook laptop, screen glowing with a half-finished presentation slide with colorful charts, keyboard backlit in soft white, a steaming cup of coffee beside it, scattered colorful sticky notes on the clean white desk surface, bright modern office background blurred out, focused productive atmosphere, photorealistic, 8K --ar 1:1', '超薄银色金属笔记本半开状态，屏幕显示未完成的PPT图表，键盘背光微微发光，旁边放着一杯还冒热气的咖啡，现代办公桌上散落几张便签纸，关联角色职场OL、实习小白', '/aid/lib/prop/2026/06/17/笔记本电脑·金属玻璃.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (132, 'reference_prop', '文件夹·合同·纸张皮革', 'cinematic overhead shot of an open dark brown leather portfolio folder, a stack of crisp white A4 contract documents inside with dense legal text and red annotated clauses, a signature half-completed in black fountain pen ink, a Montblanc pen resting diagonally across the page, cool white conference room lighting casting minimal shadows, professional and decisive atmosphere, photorealistic, 8K --ar 1:1', '深棕色皮质文件夹摊开，内夹一叠A4打印合同，纸张边缘整齐，黑色钢笔签名栏部分已签，旁边放着一支万宝龙钢笔，纸面在冷白会议灯光下清晰锐利，关联角色精英女强人、知性律师', '/aid/lib/prop/2026/07/09/文件夹·合同·纸张皮革.png', '0', NULL, '', NULL, '', '/aid/lib/prop/2026/07/09/文件夹·合同·纸张皮革.png');
INSERT INTO `aid_comic_asset` VALUES (133, 'reference_prop', '咖啡杯·陶瓷', 'cinematic close-up of a white ceramic coffee cup on a matching saucer, a perfect latte art rosetta pattern floating on the surface of the coffee, small silver spoon resting on the saucer edge, the cup casting a soft shadow on warm wooden table grain, gentle morning sunlight from a nearby window illuminating the steam, cozy cafe atmosphere, photorealistic, 8K --ar 1:1', '白色陶瓷马克杯配精致杯碟，杯中拉花拿铁图案完整，旁边小银勺搁在碟边，杯身有简约手写体文字或Logo，木桌纹理映衬下温暖舒适，关联角色实习小白、咖啡店老板', '/aid/lib/prop/2026/06/17/咖啡杯·陶瓷.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (134, 'reference_prop', '工牌·门禁卡·塑料金属', 'cinematic close-up of an employee ID badge on a dark blue lanyard, the transparent holder showing a professional headshot photo and corporate logo, a white RFID access card clipped beside it, the lanyard slightly frayed from daily use, hanging against a blurred modern office lobby background with glass turnstiles, everyday corporate life detail, photorealistic, 8K --ar 1:1', '挂在深蓝色挂绳上的员工工牌，透明卡套中露出证件照和公司Logo，旁边夹着一张感应门禁卡，挂绳微旧带着长期使用的痕迹，关联角色实习小白、职场OL', '/aid/lib/prop/2026/06/17/工牌·门禁卡·塑料金属.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (135, 'reference_prop', '外卖保温箱·牛津布铝箔', 'cinematic shot of a bright yellow insulated delivery food carrier box strapped to the back of an electric scooter, reflective safety strips and platform logo printed on the side, slightly dusty and rain-spotted from countless deliveries, several order receipts tucked under the securing bungee cords, parked in a narrow urban alley with warm street lamp glow, hardworking city life symbol, photorealistic, 8K --ar 1:1', '黄色方形外卖保温箱绑在电动车后座，箱体有平台Logo反光条，表面微脏有风雨痕迹，箱盖上用绑带固定着几份外卖小票，关联角色外卖小哥', '/aid/lib/prop/2026/06/17/外卖保温箱·牛津布铝箔.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (136, 'reference_prop', '老式收音机·塑料金属', 'cinematic close-up of a vintage 1980s portable radio, faded red plastic casing with silver metal speaker grille showing slight rust, telescopic antenna fully extended, analog tuning dial with Chinese frequency markings, resting on a weathered wooden stool beside a well-worn palm-leaf fan, soft afternoon light in an old alleyway, nostalgic generational atmosphere, photorealistic, 8K --ar 1:1', '80年代经典便携收音机，红色塑料外壳微有褪色，银色金属网罩上有些许锈迹，伸缩天线拉出，刻度盘手动调频，旁边放着一把蒲扇，关联角色老城区大爷', '/aid/lib/prop/2026/06/17/老式收音机·塑料金属.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (137, 'reference_prop', '保温杯·搪瓷茶缸·不锈钢', 'cinematic close-up of a well-used stainless steel thermal flask with slight scratches and paint chips, lid unscrewed with steam rising from the hot tea inside, next to a vintage enamel mug with faded red slogan lettering and a few chipped spots revealing the metal beneath, resting on a car center console with a phone mount in the blurred background, everyday working-class warmth, photorealistic, 8K --ar 1:1', '不锈钢保温杯杯身微有划痕和掉漆，杯盖拧开冒着热气，旁边一个老式搪瓷茶缸印着红字标语，杯沿搪瓷磕掉几块露出铁底，关联角色网约车司机、夜市摊主', '/aid/lib/prop/2026/06/17/保温杯·搪瓷茶缸·不锈钢.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (138, 'reference_prop', '雨伞·尼龙金属塑料', 'cinematic shot of a transparent long-handled umbrella leaning against a wet wooden bench, raindrops still clinging to the clear plastic canopy catching street lamp reflections, a single droplet about to fall from the metal tip, wet pavement reflecting warm city lights in the background, lonely yet romantic rainy night atmosphere, photorealistic, 8K --ar 1:1', '透明长柄雨伞靠在墙边或长椅旁，伞面水珠晶莹未干，伞骨末端水滴将落未落，地面湿漉漉倒映城市灯火，雨夜孤独又浪漫的氛围，关联角色灰姑娘女主、温柔母亲', '/aid/lib/prop/2026/07/09/雨伞·尼龙金属塑料.png', '0', NULL, '', NULL, '', '/aid/lib/prop/2026/07/09/雨伞·尼龙金属塑料.png');
INSERT INTO `aid_comic_asset` VALUES (139, 'reference_prop', '玫瑰花束·鲜花包装纸', 'cinematic close-up of a beautifully wrapped bouquet of fresh pink and red roses, deep green leaves framing the blooms, wrapped in cream-colored matte paper tied with a satin ribbon bow, tiny water droplets glistening on the velvet petals, resting on a wooden park bench in soft golden afternoon light, romantic and hopeful atmosphere, photorealistic, 8K --ar 1:1', '一束精心包扎的红玫瑰或粉玫瑰，深绿色叶片衬底，外层米色雾面纸包裹系着缎带，花瓣上还带着细小水珠，放在木质长椅或咖啡桌上，关联角色初恋白月光、温柔男二', '/aid/lib/prop/2026/06/17/玫瑰花束·鲜花包装纸.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (140, 'reference_prop', '电影票根·纸', 'cinematic top-down close-up of two torn movie ticket stubs placed side by side, printed with a romantic film title showtime and seat numbers, edges slightly curled and softened from being held, resting on a wooden cafe table next to a coffee cup, soft bokeh lights in the background, nostalgic memory of a shared moment, photorealistic, 8K --ar 1:1', '两张撕过的电影票根并排放置，票面印着片名时间座位号，边缘微微卷起，放在咖啡杯旁或夹在书页中，承载一段共同的回忆，关联角色初恋白月光、温柔男二', '/aid/lib/prop/2026/07/09/电影票根·纸.png', '0', NULL, '', NULL, '', '/aid/lib/prop/2026/07/09/电影票根·纸.png');
INSERT INTO `aid_comic_asset` VALUES (141, 'reference_prop', '红酒与高脚杯·玻璃酒液', 'cinematic close-up of two crystal wine glasses, one filled a third with deep ruby-red wine showing elegant legs on the glass wall, an opened bottle of premium red wine resting beside with the cork placed nearby, candlelight flickering through the glass creating warm amber reflections, white linen tablecloth beneath, intimate fine dining atmosphere, photorealistic, 8K --ar 1:1', '两只水晶高脚杯，一只已斟三分之一深红宝石色酒液，杯壁挂杯痕迹清晰，旁边斜躺一瓶打开的红酒，软木塞搁在一旁，烛光映在杯身光影流转，关联角色精英女强人、富二代纨绔', '/aid/lib/prop/2026/06/17/红酒与高脚杯·玻璃酒液.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (142, 'reference_prop', '老照片·拍立得·相纸', 'cinematic close-up of a slightly yellowed Polaroid photograph, a blurry but warm image of two silhouettes against a sunset background, a handwritten date scribbled in faded ink on the white border, held gently in open palms, edges softly curled from years of being treasured, warm nostalgic lighting, memory and longing atmosphere, photorealistic, 8K --ar 1:1', '一张微微泛黄的拍立得照片，画面是两个模糊人影的合影，照片一角有手写日期，放在手心里或夹在日记本扉页中，边缘微微卷翘带着时光痕迹，关联角色温柔母亲、初恋白月光', '/aid/lib/prop/2026/06/17/老照片·拍立得·相纸.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (143, 'reference_prop', '智能手机·玻璃金属', 'cinematic close-up of a modern smartphone with a slightly cracked screen protector, display glowing with an incoming call screen showing a contact photo, the phone vibrating subtly on a wooden nightstand, charging cable still connected, screen light illuminating the dark bedroom around it, connection and anticipation atmosphere, photorealistic, 8K --ar 1:1', '大屏智能手机屏幕亮着显示来电画面，手机壳微旧有使用痕迹，放在桌面或枕边，充电线还插着，屏幕光在昏暗房间中照亮周围，关联角色全角色通用', '/aid/lib/prop/2026/06/17/智能手机·玻璃金属.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (144, 'reference_prop', '围裙·棉麻', 'cinematic shot of a linen apron hanging on a wooden hook by the kitchen window, cream-colored with thin blue stripes, front pocket slightly frayed at the edges, faint traces of flour dusted on the fabric, soft morning light filtering through the window, warm homely kitchen atmosphere, photorealistic, 8K --ar 1:1', '一条挂在厨房窗边木钩上的米色条纹棉麻半身围裙，口袋边微微磨损，腰间系带自然垂落，布料上有淡淡的面粉印，温暖治愈的家居气息，关联角色温柔母亲', '/aid/lib/prop/2026/06/17/围裙·棉麻.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (145, 'reference_prop', '木质相框·木材玻璃', 'cinematic close-up of a dark walnut wood picture frame standing on a small side table, a warm family portrait visible through the slightly reflective glass, soft table lamp glow creating a gentle highlight on the frame edge, wood grain texture rich and natural, a cup of tea sitting beside it, home and belonging atmosphere, photorealistic, 8K --ar 1:1', '深色胡桃木相框立在小边柜上，框内是一张全家福合影，玻璃面反射柔和灯光，相框做工质朴有木纹，旁边放着一杯茶，关联角色温柔母亲、深情父亲', '/aid/lib/prop/2026/06/17/木质相框·木材玻璃.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (146, 'reference_prop', '医药箱·药瓶·塑料铝箔', 'cinematic overhead shot of an open white plastic home first-aid kit, compartments filled with medicine bottles band-aids and a digital thermometer, a few scattered pills on the lid beside cut aluminum foil blister packs, the warm glow of a bedside lamp casting soft shadows, quiet care and concern atmosphere, photorealistic, 8K --ar 1:1', '打开的家用塑料医药箱，内部分格装着感冒药瓶、创可贴、体温计，旁边散落着几粒药片和剪开的铝箔包装，台灯光线下透着关怀与担忧，关联角色深情父亲、温柔母亲', '/aid/lib/prop/2026/06/17/医药箱·药瓶·塑料铝箔.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (147, 'reference_prop', '团扇·丝绸竹刺绣', 'cinematic close-up of an exquisite ancient Chinese silk round fan, the delicate silk surface embroidered with blooming peonies and butterflies in gold and pink threads, sandalwood handle with a jade tassel and silk cord hanging elegantly, soft palace garden light filtering through the translucent silk, held by a delicate hand with red-painted fingernails just visible, elegant imperial harem atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '圆形绢面团扇，扇面绣着精致的牡丹或蝶恋花图案，紫檀或象牙扇柄垂着流苏与玉坠，半掩美人面时扇面轻薄透光，指尖蔻丹隐现，关联角色倾城宠妃、穿越庶女', '/aid/lib/prop/2026/06/17/团扇·丝绸竹刺绣.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (148, 'reference_prop', '圣旨·卷轴·丝绸黄绢玉', 'cinematic close-up of an unrolled imperial edict on a dark zitan wood desk, brilliant yellow silk brocade with white jade rollers at both ends, vermilion ink calligraphy and the imperial crimson jade seal stamp clearly visible, subtle five-clawed dragon patterns woven into the silk shimmering under warm lantern light, solemn imperial authority atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '明黄织锦圣旨在紫檀案几上展开，两端镶白玉卷轴，绢面上朱笔御批和玉玺朱印清晰可见，五爪龙纹暗花底纹在光下若隐若现，威严庄重，关联角色腹黑太子、冷面王爷', '/aid/lib/prop/2026/06/17/圣旨·卷轴·丝绸黄绢玉.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (149, 'reference_prop', '玉佩·令牌·玉石金绳结', 'cinematic close-up of a circular carved white jade pendant with intricate dragon relief patterns, warm translucent jade glowing under lantern light, tied with imperial yellow silk cords with elaborate knots, resting on top of a folded secret letter on a dark rosewood desk, a gold command token barely visible in the blurred edge, power and intrigue atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '圆形镂雕羊脂白玉佩系着明黄绦带结，玉质温润通透雕龙纹或螭纹，压在紫檀木桌案的一封密信上，旁边或许还有一枚纯金调兵令牌，关联角色冷面王爷、腹黑太子', '/aid/lib/prop/2026/06/17/玉佩·令牌·玉石金绳结.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (150, 'reference_prop', '长剑·钢铁皮革木材', 'cinematic close-up of an ancient Chinese straight sword resting on weathered stone, three feet of fine steel partially drawn from the scabbard revealing a cold gleaming blade with distinctive folded steel wave patterns, the scabbard wrapped in dark rayskin with ornate brass fittings, worn leather grip wrapping showing battle experience, misty bamboo forest in the soft-focus background, wuxia spirit atmosphere, photorealistic, 8K --ar 1:1', '一柄三尺青锋长剑横置于石上或木桌，剑鞘鲨鱼皮包裹铜件錾花，剑柄缠深色防滑绳结，剑身出鞘三寸露出寒光逼人的锻打钢面，刃纹如水波流转，关联角色少年剑客、江湖侠女', '/aid/lib/prop/2026/07/09/长剑·钢铁皮革木材.png', '0', NULL, '', NULL, '', '/aid/lib/prop/2026/07/09/长剑·钢铁皮革木材.png');
INSERT INTO `aid_comic_asset` VALUES (151, 'reference_prop', '酒葫芦·葫芦藤编红绳', 'cinematic close-up of an aged dark brown gourd wine flask, surface polished smooth and glossy from years of handling, partially wrapped in woven rattan netting, red cord tied around the neck with a wooden stopper and tassel, resting on a rough wooden inn table beside a simple ceramic wine bowl, faint crack lines on the gourd telling stories of the road, rustic wuxia atmosphere, photorealistic, 8K --ar 1:1', '深棕色老葫芦外壳光滑油亮，藤编网兜半裹，红绳系着塞子垂下流苏，放在客栈木桌上旁边一只粗瓷酒碗，葫芦身上有细微裂纹记录江湖岁月，关联角色隐世高僧、江湖侠女', '/aid/lib/prop/2026/06/17/酒葫芦·葫芦藤编红绳.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (152, 'reference_prop', '斗笠·竹粽叶麻绳', 'cinematic shot of a wide-brimmed conical bamboo rain hat leaning against the wooden doorframe of an ancient inn, outer layer covered with dried bamboo leaves for waterproofing, inner bamboo strip weave tight and symmetrical, hemp cord ties hanging loosely, slightly yellowed and frayed from sun and rain, warm lantern light from within the inn spilling onto it, wanderer and journey atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '宽檐圆锥竹编斗笠，外层覆粽叶防雨，内侧竹篾编纹紧密整齐，麻绳系带垂落，靠在客栈门边或挂在墙上，历经风霜微微泛黄，关联角色少年剑客、茶馆老板娘', '/aid/lib/prop/2026/06/17/斗笠·竹粽叶麻绳.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (153, 'reference_prop', '拂尘·白马尾檀木玉', 'cinematic close-up of a white horsetail whisk resting against a meditation cushion, the handle carved from luminous white jade with flowing Taoist talisman patterns, silver-white horsehair cascading like a waterfall of light, a jade ring and intricate knot at the handle end, faint spiritual energy particles glowing around the hairs, misty immortal realm visible beyond the temple pillars, transcendent xianxia atmosphere, photorealistic, 8K --ar 1:1', '一柄白玉柄白马尾拂尘斜倚在石台或蒲团旁，玉柄温润末端系着太极结，马尾长而银白如雪瀑垂落，手柄刻有道纹符箓在灵光下隐隐发亮，关联角色仙门师尊', '/aid/lib/prop/2026/06/17/拂尘·白马尾檀木玉.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (154, 'reference_prop', '丹药琉璃瓶·琉璃金丹', 'cinematic macro close-up of a small translucent glass bottle, several golden pills with intricate alchemical grain patterns visible inside, the neck sealed with red silk and tied with gold thread, one pill resting on the cork beside the bottle, faint luminescent medicinal vapor swirling around the pills, mysterious cultivation chamber lighting, magical alchemy atmosphere, photorealistic xianxia style, 8K --ar 1:1', '透明琉璃小瓶内装数粒金丹或暗紫色魔丹，丹药表面有细密丹纹，瓶口以红布或黑布封口系金丝绳，瓶身折射微光药气如烟缭绕，关联角色仙门师尊、魔界少主', '/aid/lib/prop/2026/06/17/丹药琉璃瓶·琉璃金丹.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (155, 'reference_prop', '红灯笼·纸竹丝绸', 'cinematic shot of a traditional Chinese red paper lantern hanging from dark wooden eaves, bamboo ribs forming an elegant oval shape, the red lantern surface hand-painted with gold calligraphy and flower motifs, warm candlelight glowing softly through the paper casting a warm amber halo, strings of identical lanterns receding into the background, festive yet nostalgic ancient Chinese atmosphere, photorealistic, 8K --ar 1:1', '传统中国红色纸灯笼，竹骨撑起椭圆或圆形灯体，灯面绘金色福字或花鸟，内置烛光透过红纸晕出温暖柔光，成串悬挂在木质屋檐下，关联角色茶馆老板娘、全古风角色', '/aid/lib/prop/2026/06/17/红灯笼·纸竹丝绸.png', '0', NULL, '', NULL, '', NULL);
INSERT INTO `aid_comic_asset` VALUES (156, 'reference_prop', '紫砂茶具·紫砂陶瓷', 'cinematic close-up of an exquisite Yixing purple clay tea set on a dark lacquered tea tray, a round Xi Shi teapot with a beautiful natural patina from years of use, two matching tiny tea cups beside it, fragrant steam drifting from the spout, a copper kettle simmering on a small charcoal brazier in the soft-focus background, tranquil tea ceremony atmosphere, photorealistic ancient Chinese style, 8K --ar 1:1', '一套宜兴紫砂茶具置于黑漆茶盘上，西施壶壶身圆润包浆莹润，两只紫砂小杯相配，壶嘴飘出缕缕茶香白雾，旁边铜壶在炭炉上咕嘟作响，关联角色茶馆老板娘、隐世高僧', '/aid/lib/prop/2026/06/17/紫砂茶具·紫砂陶瓷.png', '0', NULL, '', NULL, '', NULL);
