  '{}'

 UNION ALL SELECT 'screenplay_review','review-method',
  'classpath:skills/screenplay_review/1.1.0/references/review-method.md',
  'a01a41e1a82c13708742a5f9b7872b18f4aee7aecdc1a8d3a19ed95556244c2c',2677,'{"always":true}'
 UNION ALL SELECT 'screenplay_review','story-script-rubric',
  'classpath:skills/screenplay_review/1.1.0/references/story-script-rubric.md',
  '8eb21957efdce5ed80ee2c9d6c9f90e04858819b55a1d28a5a825fe9b543ede4',2727,'{"always":true}'
 UNION ALL SELECT 'screenplay_review','continuity-review',
  'classpath:skills/screenplay_review/1.1.0/references/continuity-review.md',
  '1c3d60fef4aeaf2ee84c5f717fd9467beb97a41b69c57e80d51376682fd85c56',1414,
  '{"keywords":["项目类型：series","连续","前集","剧集","当前集","人物关系","关键道具"]}'
 UNION ALL SELECT 'screenplay_review','anti-template-review',
