 '$.supportsReasoningDisable',JSON_EXTRACT('true','$'),
 '$.returnsReasoningContent',JSON_EXTRACT('true','$'),
 '$.reasoningApiStyle','DEEPSEEK','$.outputTokenApiField','max_tokens',
 '$.defaultReasoningEnabled',JSON_EXTRACT('false','$'),
