-- 修正 DeepSeek Flash 普通聊天路由与当前官方上游模型名。
START TRANSACTION;
UPDATE aid_ai_model AS m
JOIN aid_ai_provider AS p ON p.id = m.provider_id
SET m.real_model_code = 'deepseek-flash',
    m.model_name = CASE
        WHEN m.model_name IN ('DeepSeek V4 Flash', 'DeepSeek V4.1 Flash') THEN 'DeepSeek V4.1 Flash'
        ELSE m.model_name
    END,
    m.api_suffix = '/chat/completions',
    m.remark = CASE
        WHEN m.remark IS NULL THEN NULL
        ELSE REPLACE(m.remark, 'DeepSeek V4 Flash', 'DeepSeek V4.1 Flash')
    END,
    m.config_version = COALESCE(m.config_version, 0) + 1,
    m.update_time = NOW(),
    m.update_by = 'system'
WHERE p.provider_code = 'deepseek'
  AND p.del_flag = '0'
  AND m.model_code = 'deepseek-flash'
  AND m.del_flag = '0';

UPDATE aid_ai_model_protocol_binding AS b
JOIN aid_ai_model AS m ON m.id = b.model_id
JOIN aid_ai_provider AS p ON p.id = m.provider_id
SET b.definition_json = JSON_SET(
        b.definition_json,
        '$.upstreamModel', 'deepseek-flash',
        '$.apiSuffix', CASE
            WHEN b.capability_code = 'fim' OR b.protocol = 'deepseek:fim'
                THEN '/beta/completions'
            ELSE '/chat/completions'
        END
    ),
    b.update_time = NOW(),
    b.update_by = 'system'
WHERE p.provider_code = 'deepseek'
  AND p.del_flag = '0'
  AND m.model_code = 'deepseek-flash'
  AND m.del_flag = '0'
  AND JSON_VALID(b.definition_json);

COMMIT;

-- Positional seed INSERTs run before this schema change; only active model codes remain unique.
ALTER TABLE `aid_ai_model`
  ADD COLUMN `active_model_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci
    GENERATED ALWAYS AS (CASE WHEN `del_flag` = '0' THEN `model_code` ELSE NULL END) VIRTUAL,
  ADD UNIQUE INDEX `uk_aid_ai_model_active_code` (`active_model_code`),
  ADD INDEX `idx_aid_ai_model_model_code` (`model_code`),
  DROP INDEX `uk_aid_ai_model_model_code`;

