SET @newapi_ddl = IF(EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_ai_provider' AND COLUMN_NAME='new_api_token_id'), 'SELECT 1', 'ALTER TABLE `aid_ai_provider` ADD COLUMN `new_api_token_id` BIGINT NULL COMMENT ''上游调用令牌编号''');
PREPARE newapi_stmt FROM @newapi_ddl;
EXECUTE newapi_stmt;
DEALLOCATE PREPARE newapi_stmt;

-- Restore the verified MiniMax H3 scenes on previously imported TokenDance catalog models.
-- Keep administrator-defined sceneRules untouched; repeat execution is a no-op.
UPDATE aid_ai_model m
JOIN aid_ai_provider p ON p.id=m.provider_id AND p.provider_code='tokendance'
SET m.capability_json=JSON_SET(m.capability_json, '$.sceneRules', JSON_OBJECT(
      'textToVideo', JSON_OBJECT('requiredInputs',JSON_ARRAY('text'),'allowedInputs',JSON_ARRAY('text')),
      'imageToVideo', JSON_OBJECT('requiredInputs',JSON_ARRAY('firstFrame'),
          'allowedInputs',JSON_ARRAY('text','firstFrame'),'aspectRatioFollowInput',TRUE),
      'startEndToVideo', JSON_OBJECT('requiredInputs',JSON_ARRAY('firstFrame','lastFrame'),
          'allowedInputs',JSON_ARRAY('text','firstFrame','lastFrame'),'aspectRatioFollowInput',TRUE),
      'referenceToVideo', JSON_OBJECT('requiredInputs',JSON_ARRAY('text'),
          'requiredAnyOf',JSON_ARRAY('image','video'),
          'allowedInputs',JSON_ARRAY('text','image','video','audio')))),
    m.supports_first_frame=1, m.supports_last_frame=1, m.supports_multi_image_input=1,
    m.config_version=COALESCE(m.config_version,0)+1,
    m.update_time=NOW(), m.update_by='capability-repair'
WHERE m.real_model_code='minimax-h3'
  AND m.protocol='tokendance:minimax:video_generation_v2'
  AND m.del_flag='0' AND JSON_VALID(m.capability_json)
  AND JSON_CONTAINS_PATH(m.capability_json,'one','$.sceneRules')=0;

-- Generic compute node draft configuration. Activation requires a verified worker registration.
CREATE TABLE IF NOT EXISTS aid_business_entrypoint (
 id bigint NOT NULL AUTO_INCREMENT,
 func_code varchar(100) NOT NULL,
 provider_code varchar(100) NOT NULL,
 entry_kind varchar(16) NOT NULL,
 entry_code varchar(100) NOT NULL,
 version_id varchar(19) NOT NULL,
 package_digest char(64) NOT NULL,
 default_entry tinyint NOT NULL DEFAULT 0,
 sort_order int NOT NULL DEFAULT 0,
 update_by varchar(64) NOT NULL,
 update_time datetime NOT NULL,
 PRIMARY KEY(id),
 UNIQUE KEY uk_business_entrypoint(func_code,provider_code,entry_kind,entry_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='业务场景固定执行入口引用';
INSERT INTO sys_config(config_name,config_key,config_value,config_type,create_by,create_time,remark)
SELECT '计算节点健康检查开关','aid.compute.health.enabled','true','N','system',NOW(),'通过后台参数设置调整；关闭不会释放已有资源占用'
WHERE NOT EXISTS(SELECT 1 FROM sys_config WHERE config_key='aid.compute.health.enabled');
INSERT INTO sys_config(config_name,config_key,config_value,config_type,create_by,create_time,remark)
SELECT '计算节点健康检查间隔秒','aid.compute.health.intervalSeconds','20','N','system',NOW(),'10至300秒；使用有界后台检查，不提交生成任务'
WHERE NOT EXISTS(SELECT 1 FROM sys_config WHERE config_key='aid.compute.health.intervalSeconds');
INSERT INTO sys_config(config_name,config_key,config_value,config_type,create_by,create_time,remark)
SELECT '计算节点健康证据有效秒','aid.compute.health.freshnessSeconds','60','N','system',NOW(),'30至900秒且至少两个检查周期；过期停止新预留'
WHERE NOT EXISTS(SELECT 1 FROM sys_config WHERE config_key='aid.compute.health.freshnessSeconds');
INSERT INTO sys_config(config_name,config_key,config_value,config_type,create_by,create_time,remark)
SELECT '计算任务回执核对开关','aid.compute.reconciliation.enabled','true','N','system',NOW(),'只核对原任务，不重发执行或自行退款'
WHERE NOT EXISTS(SELECT 1 FROM sys_config WHERE config_key='aid.compute.reconciliation.enabled');
INSERT INTO sys_config(config_name,config_key,config_value,config_type,create_by,create_time,remark)
SELECT '计算任务回执核对间隔秒','aid.compute.reconciliation.intervalSeconds','30','N','system',NOW(),'10至3600秒；不可信或未知回执继续保留资源占用'
WHERE NOT EXISTS(SELECT 1 FROM sys_config WHERE config_key='aid.compute.reconciliation.intervalSeconds');
CREATE TABLE IF NOT EXISTS `aid_compute_reservation` (
 `request_key` varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 `request_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 `node_key` varchar(100) DEFAULT NULL,
 `task_key` varchar(100) NOT NULL,
 `project_key` varchar(100) NOT NULL,
 `config_revision` bigint DEFAULT NULL,
 `engine` varchar(100) NOT NULL,
 `task_kind` varchar(100) NOT NULL,
 `cpu_millis` bigint NOT NULL DEFAULT 0,
 `memory_bytes` bigint NOT NULL DEFAULT 0,
 `scratch_bytes` bigint NOT NULL DEFAULT 0,
 `state` varchar(24) NOT NULL DEFAULT 'PENDING',
 `worker_job_id` varchar(100) DEFAULT NULL,
 `terminal_receipt_digest` char(64) DEFAULT NULL,
 `create_time` datetime NOT NULL,
 `update_time` datetime NOT NULL,
 PRIMARY KEY (`request_key`),
 KEY `idx_compute_reservation_node` (`node_key`,`state`),
 KEY `idx_compute_reservation_task` (`task_key`,`project_key`),
 KEY `idx_compute_reservation_due` (`state`,`update_time`,`request_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='既有任务的计算额度预留，不替代任务与计费账本';
SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_reservation' AND INDEX_NAME='idx_compute_reservation_due')=0,'ALTER TABLE aid_compute_reservation ADD INDEX idx_compute_reservation_due(state,update_time,request_key)','SELECT 1');
PREPARE compute_stmt FROM @compute_ddl;
EXECUTE compute_stmt;
DEALLOCATE PREPARE compute_stmt;

CREATE TABLE IF NOT EXISTS `aid_compute_node` (
  `node_key` varchar(100) NOT NULL,
  `name` varchar(100) NOT NULL,
  `pool_code` varchar(100) NOT NULL,
  `draft_config_json` longtext NOT NULL,
  `revision` bigint NOT NULL,
  `active_config_json` longtext DEFAULT NULL,
  `active_revision` bigint DEFAULT NULL,
  `state` varchar(24) NOT NULL DEFAULT 'DRAFT',
  `health_status` varchar(24) DEFAULT NULL,
  `health_generation` bigint NOT NULL DEFAULT 0,
  `health_json` longtext DEFAULT NULL,
  `health_checked_at` datetime DEFAULT NULL,
  `draft_worker_id` varchar(100) DEFAULT NULL,
  `draft_credential_ciphertext` text DEFAULT NULL,
  `verification_json` longtext DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `create_by` varchar(64) NOT NULL,
  `update_by` varchar(64) NOT NULL,
  `create_time` datetime NOT NULL,
  `update_time` datetime NOT NULL,
  PRIMARY KEY (`node_key`),
  KEY `idx_compute_pool_state` (`pool_code`,`state`),
  KEY `idx_compute_updated` (`update_time`,`node_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='计算节点配置及已确认版本';

SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_node' AND COLUMN_NAME='health_generation')=0,'ALTER TABLE aid_compute_node ADD COLUMN health_generation bigint NOT NULL DEFAULT 0','SELECT 1');
