SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_node' AND COLUMN_NAME='health_checked_at')=0,'ALTER TABLE aid_compute_node ADD COLUMN health_checked_at datetime DEFAULT NULL','SELECT 1');
PREPARE compute_stmt FROM @compute_ddl;
