SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_node' AND COLUMN_NAME='draft_worker_id')=0,'ALTER TABLE aid_compute_node ADD COLUMN draft_worker_id varchar(100) DEFAULT NULL','SELECT 1');
PREPARE compute_stmt FROM @compute_ddl;
EXECUTE compute_stmt;
DEALLOCATE PREPARE compute_stmt;
SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_node' AND COLUMN_NAME='draft_credential_ciphertext')=0,'ALTER TABLE aid_compute_node ADD COLUMN draft_credential_ciphertext text DEFAULT NULL','SELECT 1');
PREPARE compute_stmt FROM @compute_ddl;
EXECUTE compute_stmt;
DEALLOCATE PREPARE compute_stmt;
SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_node' AND COLUMN_NAME='verification_json')=0,'ALTER TABLE aid_compute_node ADD COLUMN verification_json longtext DEFAULT NULL','SELECT 1');
PREPARE compute_stmt FROM @compute_ddl;
