SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_node' AND COLUMN_NAME='verified_at')=0,'ALTER TABLE aid_compute_node ADD COLUMN verified_at datetime DEFAULT NULL','SELECT 1');
PREPARE compute_stmt FROM @compute_ddl;
EXECUTE compute_stmt;
DEALLOCATE PREPARE compute_stmt;

CREATE TABLE IF NOT EXISTS `aid_compute_node_revision` (
 `node_key` varchar(100) NOT NULL,
 `revision` bigint NOT NULL,
 `config_json` longtext NOT NULL,
 `worker_id` varchar(100) DEFAULT NULL,
 `credential_ciphertext` text DEFAULT NULL,
 `verification_json` longtext DEFAULT NULL,
 `verified_at` datetime DEFAULT NULL,
 `create_by` varchar(64) NOT NULL,
 `create_time` datetime NOT NULL,
 PRIMARY KEY (`node_key`,`revision`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='计算节点不可变配置版本';

