upportsFrames":false,"supportsDraft":false,"supportsDraftUpgrade":false,"serviceTierOptions":["default"],"seedanceTaskTypeOptions":[],"timestampIntegerOnly":false,"allowedScenes":["textToVideo","imageToVideo","startEndToVideo","referenceToVideo","videoToVideo"],"strictSceneRules":true,"sceneRules":{"textToVideo":{"allowedInputs":["text"]},"imageToVideo":{"requiredInputs":["firstFrame"],"allowedInputs":["text","firstFrame"],"aspectRatioOptions":["adaptive","16:9","9:16","4:3","3:4","1:1","21:9"],"defaultAspectRatio":"16:9"},"startEndToVideo":{"requiredInputs":["firstFrame","lastFrame"],"allowedInputs":["text","firstFrame","lastFrame"],"aspectRatioOptions":["adaptive","16:9","9:16","4:3","3:4","1:1","21:9"],"defaultAspectRatio":"16:9"},"referenceToVideo":{"requiredAnyOf":["image","video"],"allowedInputs":["text","image","video","audio"]},"videoToVideo":{"requiredInputs":["video"],"allowedInputs":["text","image","video","audio"]}}}';
