WHERE NOT EXISTS (SELECT 1 FROM aid_config WHERE category='storage_sync' AND config_name='fingerprint');

-- 助手会话、运行控制、预算授权与后台治理菜单：仅本次变更的商业环境幂等增量。
-- MySQL 5.7；不导入运营 Prompt、供应商、模型、价格或业务数据。
-- 授权记录只约束本次运行的可消费上限，不是余额、钱包或可转移资产。
SET NAMES utf8mb4 COLLATE utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `aid_chat_session` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `skill_id` bigint DEFAULT NULL,
  `project_id` bigint NOT NULL DEFAULT 0,
  `episode_id` bigint NOT NULL DEFAULT 0,
  `workspace_id` bigint DEFAULT NULL,
  `node_object_id` varchar(64) DEFAULT NULL,
  `session_type` varchar(20) NOT NULL DEFAULT 'SKILL',
  `entry_transport` varchar(16) DEFAULT NULL COMMENT '助手入口 MAIN/CANVAS，NULL 为历史兼容',
  `client_session_id` varchar(64) DEFAULT NULL,
  `module_code` varchar(20) DEFAULT NULL,
  `mode` varchar(20) DEFAULT NULL,
  `title` varchar(100) NOT NULL,
  `base_input_json` longtext NOT NULL,
  `active_runtime_run_id` bigint DEFAULT NULL,
  `state_revision` bigint NOT NULL DEFAULT 0,
  `reasoning_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `reasoning_level` varchar(20) DEFAULT NULL,
  `show_reasoning` tinyint(1) NOT NULL DEFAULT 0,
  `context_summary` longtext DEFAULT NULL,
  `summary_until_seq` bigint DEFAULT NULL,
  `context_anchor_message_id` bigint DEFAULT NULL,
  `last_message_seq` bigint NOT NULL DEFAULT 0,
  `last_event_seq` bigint NOT NULL DEFAULT 0,
  `favorite` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `last_active_time` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chat_client_session` (`user_id`,`client_session_id`),
  KEY `idx_chat_session_entry` (`user_id`,`session_type`,`entry_transport`,`del_flag`,`id`),
  KEY `idx_chat_session_user` (`user_id`,`session_type`,`del_flag`,`last_active_time`,`id`),
  KEY `idx_chat_session_scope` (`user_id`,`project_id`,`episode_id`,`skill_id`,`del_flag`,`last_active_time`,`id`),
  KEY `idx_chat_session_skill` (`skill_id`,`del_flag`,`id`),
  KEY `idx_chat_canvas_node` (`user_id`,`workspace_id`,`node_object_id`,`last_active_time`),
  KEY `idx_chat_session_active` (`user_id`,`active_runtime_run_id`,`del_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用生成、Skill与助手共用会话';

CREATE TABLE IF NOT EXISTS `aid_chat_message` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `run_id` bigint DEFAULT NULL,
  `runtime_run_id` bigint DEFAULT NULL,
  `turn_id` bigint DEFAULT NULL,
  `media_task_id` bigint DEFAULT NULL,
  `seq_no` bigint NOT NULL,
  `client_message_id` varchar(64) DEFAULT NULL,
  `request_hash` varchar(64) DEFAULT NULL,
  `role` varchar(20) NOT NULL,
  `status` varchar(20) NOT NULL,
  `message_kind` varchar(30) NOT NULL DEFAULT 'STATUS',
  `media_type` varchar(20) NOT NULL DEFAULT 'TEXT',
  `model_code` varchar(100) DEFAULT NULL,
  `tool_call_id` varchar(64) DEFAULT NULL,
  `content_text` varchar(1000) DEFAULT NULL,
  `error_message` varchar(500) DEFAULT NULL,
  `context_anchor` tinyint(1) NOT NULL DEFAULT 0,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chat_message_seq` (`session_id`,`seq_no`),
  UNIQUE KEY `uk_chat_client_message` (`session_id`,`client_message_id`),
  KEY `idx_chat_message_run` (`run_id`),
  KEY `idx_chat_message_runtime` (`runtime_run_id`,`seq_no`),
  KEY `idx_chat_message_task` (`media_task_id`),
  KEY `idx_chat_message_cursor` (`session_id`,`status`,`del_flag`,`seq_no`),
  KEY `idx_chat_message_reconcile` (`role`,`del_flag`,`status`,`media_type`,`update_time`,`media_task_id`),
  KEY `idx_chat_message_anchor` (`session_id`,`context_anchor`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用会话消息';

CREATE TABLE IF NOT EXISTS `aid_chat_message_part` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `message_id` bigint NOT NULL,
  `part_seq` int NOT NULL,
  `part_type` varchar(20) NOT NULL,
  `slot_name` varchar(50) NOT NULL,
  `text_content` longtext DEFAULT NULL,
  `resource_id` bigint DEFAULT NULL,
  `resource_role` varchar(20) DEFAULT NULL,
  `resource_url` varchar(2000) DEFAULT NULL,
  `thumbnail_url` varchar(2000) DEFAULT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `metadata_json` longtext DEFAULT NULL,
  `context_scope` varchar(30) NOT NULL DEFAULT 'CURRENT_TURN',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chat_message_part` (`message_id`,`part_seq`),
  KEY `idx_chat_part_type` (`part_type`),
  KEY `idx_chat_part_resource` (`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用会话有序内容块';

CREATE TABLE IF NOT EXISTS `aid_runtime_run` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `session_id` bigint DEFAULT NULL,
  `turn_id` bigint DEFAULT NULL,
  `member_type` varchar(10) DEFAULT NULL,
  `member_id` bigint DEFAULT NULL,
  `version_id` bigint DEFAULT NULL,
  `version_digest` varchar(64) DEFAULT NULL,
  `model_code` varchar(100) DEFAULT NULL,
  `output_kind` varchar(10) DEFAULT NULL,
  `executor_strategy` varchar(30) DEFAULT NULL,
  `project_id` bigint DEFAULT NULL,
  `workspace_id` bigint DEFAULT NULL,
  `node_object_id` varchar(64) DEFAULT NULL,
  `active_node_key` varchar(96) GENERATED ALWAYS AS (CASE WHEN `del_flag`='0' AND `status` IN ('CREATED','RUNNING','WAITING_INPUT') AND `workspace_id` IS NOT NULL AND `node_object_id` IS NOT NULL THEN CONCAT(`workspace_id`,':',`node_object_id`) ELSE NULL END) STORED,
  `node_version` bigint DEFAULT NULL,
  `client_request_id` varchar(64) NOT NULL,
  `request_digest` varchar(64) NOT NULL,
  `request_json` longtext NOT NULL,
  `trial_grant_id` bigint DEFAULT NULL,
  `estimated_tokens_used` int NOT NULL DEFAULT 0,
  `clarification_key` varchar(64) DEFAULT NULL,
  `clarification_digest` varchar(64) DEFAULT NULL,
  `media_task_id` bigint DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'CREATED',
  `state_revision` bigint NOT NULL DEFAULT 0,
  `plan_revision` bigint NOT NULL DEFAULT 0,
  `budget_authorization_id` bigint DEFAULT NULL,
  `context_digest` char(64) DEFAULT NULL,
  `checkpoint_ref` varchar(500) DEFAULT NULL,
  `pause_reason` varchar(30) DEFAULT NULL,
  `resume_status` varchar(30) DEFAULT NULL,
  `stop_requested` tinyint(1) NOT NULL DEFAULT 0,
  `next_action` varchar(40) DEFAULT NULL,
  `lease_owner` varchar(64) DEFAULT NULL,
  `lease_until` datetime DEFAULT NULL,
  `fencing_token` bigint NOT NULL DEFAULT 0,
  `next_retry_at` datetime DEFAULT NULL,
  `result_json` longtext DEFAULT NULL,
  `error_message` varchar(1000) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_run_request` (`user_id`,`session_id`,`client_request_id`),
  UNIQUE KEY `uk_runtime_run_legacy_request` (`user_id`,`member_type`,`member_id`,`client_request_id`),
  UNIQUE KEY `uk_runtime_active_node` (`active_node_key`),
  KEY `idx_runtime_run_task` (`media_task_id`),
  KEY `idx_runtime_run_recovery` (`status`,`update_time`,`id`),
  KEY `idx_runtime_run_next_retry` (`status`,`next_retry_at`,`id`),
  KEY `idx_runtime_run_session` (`session_id`,`id`),
  KEY `idx_runtime_run_budget_authorization` (`budget_authorization_id`),
  KEY `idx_runtime_run_history` (`user_id`,`workspace_id`,`node_object_id`,`create_time`,`id`),
  KEY `idx_runtime_canvas_active` (`workspace_id`,`status`,`create_time`,`id`),
  KEY `idx_runtime_canvas_node_history` (`workspace_id`,`node_object_id`,`create_time`,`id`),
  KEY `idx_runtime_run_version` (`member_type`,`member_id`,`version_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent、Skill与助手通用运行快照';

