  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_step` (`run_id`,`step_index`),
  UNIQUE KEY `uk_runtime_step_attempt` (`run_id`,`plan_revision`,`stable_step_id`,`attempt_no`),
  UNIQUE KEY `uk_runtime_step_idempotency` (`run_id`,`idempotency_key`),
  KEY `idx_runtime_step_plan` (`run_id`,`plan_revision`,`plan_position`,`id`),
  KEY `idx_runtime_step_lease` (`status`,`lease_until`,`id`),
  KEY `idx_runtime_step_reservation` (`reservation_id`),
  KEY `idx_runtime_step_task` (`media_task_id`),
  KEY `idx_runtime_step_child` (`child_run_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用运行有界步骤与任务关联';

CREATE TABLE IF NOT EXISTS `aid_runtime_input_request` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `request_key` varchar(64) NOT NULL,
  `round_no` int NOT NULL,
  `schema_digest` char(64) NOT NULL,
  `context_digest` char(64) NOT NULL,
  `plan_revision` bigint NOT NULL,
  `status` varchar(20) NOT NULL,
  `question_bundle_json` text NOT NULL,
  `accepted_answers_json` text DEFAULT NULL,
  `accepted_digest` char(64) DEFAULT NULL,
  `accepted_key` varchar(64) DEFAULT NULL,
  `suspended_at` datetime DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_input_request` (`run_id`,`request_key`),
  KEY `idx_runtime_input_request_status` (`run_id`,`status`,`round_no`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手结构化问题请求';

CREATE TABLE IF NOT EXISTS `aid_runtime_input_draft` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `input_request_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `question_id` varchar(64) NOT NULL,
  `draft_revision` bigint NOT NULL DEFAULT 0,
  `choice_ids_json` text DEFAULT NULL,
  `free_text` text DEFAULT NULL,
  `answer_state` varchar(20) NOT NULL,
  `last_client_operation_id` varchar(64) DEFAULT NULL,
  `last_payload_digest` char(64) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_input_draft` (`input_request_id`,`user_id`,`question_id`),
  KEY `idx_runtime_input_draft_user` (`user_id`,`update_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手问题逐题草稿';

CREATE TABLE IF NOT EXISTS `aid_runtime_input_view` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `input_request_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `cursor_question_id` varchar(64) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_input_view` (`input_request_id`,`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手问题浏览位置';

CREATE TABLE IF NOT EXISTS `aid_runtime_event` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `run_id` bigint DEFAULT NULL,
  `seq` bigint NOT NULL,
  `event_type` varchar(50) NOT NULL,
  `entity_id` varchar(64) DEFAULT NULL,
  `entity_revision` bigint DEFAULT NULL,
  `causation_id` varchar(64) DEFAULT NULL,
  `payload_json` text DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `publish_attempt` int NOT NULL DEFAULT 0,
  `next_retry_at` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_event_seq` (`session_id`,`seq`),
  KEY `idx_runtime_event_run` (`run_id`,`seq`),
  KEY `idx_runtime_event_publish` (`published_at`,`next_retry_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手权威事件与发布Outbox';

CREATE TABLE IF NOT EXISTS `aid_runtime_command` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `actor_id` bigint NOT NULL,
  `session_id` bigint NOT NULL,
  `client_request_id` varchar(64) NOT NULL,
  `payload_digest` char(64) NOT NULL,
  `command_type` varchar(40) NOT NULL,
  `status` varchar(20) NOT NULL,
  `result_json` text DEFAULT NULL,
  `error_code` varchar(64) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_command_request` (`actor_id`,`session_id`,`client_request_id`),
  KEY `idx_runtime_command_session` (`session_id`,`create_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手幂等控制命令';

CREATE TABLE IF NOT EXISTS `aid_billing_authorization` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `payer_user_id` bigint NOT NULL,
  `runtime_run_id` bigint NOT NULL,
  `approved_total` decimal(14,4) NOT NULL,
  `reserved_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `settled_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `currency_unit` varchar(16) NOT NULL DEFAULT 'BALANCE',
  `precision_scale` tinyint NOT NULL DEFAULT 4,
  `status` varchar(16) NOT NULL,
  `revision` bigint NOT NULL DEFAULT 1,
  `state_revision` bigint NOT NULL DEFAULT 1,
  `policy_digest` char(64) NOT NULL,
  `expires_at` datetime DEFAULT NULL,
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_run` (`runtime_run_id`),
  KEY `idx_payer_status` (`payer_user_id`,`status`),
  KEY `idx_status_expiry` (`status`,`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手运行预算授权上限，不存放账户余额';

CREATE TABLE IF NOT EXISTS `aid_billing_authorization_reservation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `authorization_id` bigint NOT NULL,
  `authorization_revision` bigint NOT NULL,
  `runtime_run_id` bigint NOT NULL,
  `runtime_step_id` bigint DEFAULT NULL,
  `stable_step_key` varchar(128) NOT NULL,
  `approval_id` bigint DEFAULT NULL,
  `attempt_no` int NOT NULL,
  `operation_kind` varchar(32) NOT NULL,
  `logical_call_key` varchar(128) NOT NULL,
  `request_digest` char(64) NOT NULL,
  `quote_id` varchar(80) NOT NULL,
  `quote_digest` char(64) NOT NULL,
  `quote_expires_at` datetime NOT NULL,
  `media_task_id` bigint DEFAULT NULL,
  `billing_trace_id` varchar(64) NOT NULL,
  `quoted_upper_bound` decimal(14,4) NOT NULL,
  `reserved_amount` decimal(14,4) NOT NULL,
  `wallet_frozen_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `settled_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `released_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `wallet_refunded_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `state` varchar(20) NOT NULL,
  `settlement_key` varchar(128) DEFAULT NULL,
  `revision` bigint NOT NULL DEFAULT 1,
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_logical_call_key` (`logical_call_key`),
  UNIQUE KEY `uk_quote_id` (`quote_id`),
  UNIQUE KEY `uk_billing_trace_id` (`billing_trace_id`),
  UNIQUE KEY `uk_media_task_id` (`media_task_id`),
  UNIQUE KEY `uk_settlement_key` (`settlement_key`),
  KEY `idx_authorization_state` (`authorization_id`,`state`),
  KEY `idx_runtime_step` (`runtime_run_id`,`stable_step_key`,`attempt_no`),
  KEY `idx_physical_runtime_step` (`runtime_step_id`),
  KEY `idx_reservation_approval` (`approval_id`),
  KEY `idx_reconciliation` (`state`,`update_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手预算预留与既有账本关联';

-- Runtime budget policy is the durable absolute execution boundary; account balances remain authoritative elsewhere.
CREATE TABLE IF NOT EXISTS `aid_runtime_budget_policy` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `authorization_id` bigint NOT NULL,
  `authorization_revision` bigint NOT NULL,
  `renewal_confirmation_revision` bigint DEFAULT NULL COMMENT 'Authorization revision awaiting explicit execution confirmation',
  `mode` varchar(20) NOT NULL,
  `absolute_max_charge` decimal(14,4) NOT NULL,
  `per_call_max_charge` decimal(14,4) NOT NULL,
  `allowed_tool_codes_json` text NOT NULL,
  `allowed_model_codes_json` text NOT NULL,
  `allowed_capability_codes_json` text NOT NULL,
  `allowed_media_types_json` text NOT NULL,
  `target_refs_json` mediumtext NOT NULL,
  `automatic_forbidden_operation_kinds_json` text NOT NULL,
  `max_iterations` int NOT NULL,
  `max_operations` int NOT NULL,
  `used_iterations` int NOT NULL DEFAULT 0,
  `used_operations` int NOT NULL DEFAULT 0,
  `expires_at` datetime NOT NULL,
  `scope_digest` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `state_revision` bigint NOT NULL DEFAULT 0,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_budget_policy_run` (`run_id`),
  UNIQUE KEY `uk_runtime_budget_policy_authorization` (`authorization_id`),
  KEY `idx_runtime_budget_policy_expiry` (`status`,`expires_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手运行绝对预算与能力策略，不存放钱包金额';

