SET @assistant_ddl := IF(@assistant_column_nullable='NO','ALTER TABLE `aid_runtime_approval` MODIFY COLUMN `quote_digest` char(64) DEFAULT NULL','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_column_nullable := (SELECT IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_approval' AND COLUMN_NAME='accepted_at');
SET @assistant_ddl := IF(@assistant_column_nullable='NO','ALTER TABLE `aid_runtime_approval` MODIFY COLUMN `accepted_at` datetime DEFAULT NULL','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_column_default := (SELECT COLUMN_DEFAULT FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_approval' AND COLUMN_NAME='status');
