SET @assistant_column_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_source_coverage' AND COLUMN_NAME='del_flag');
SET @assistant_ddl := IF(@assistant_column_exists=0,'ALTER TABLE `aid_runtime_source_coverage` ADD COLUMN `del_flag` char(1) NOT NULL DEFAULT ''0'' AFTER `status`','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_column_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_artifact_review' AND COLUMN_NAME='del_flag');
SET @assistant_ddl := IF(@assistant_column_exists=0,'ALTER TABLE `aid_runtime_artifact_review` ADD COLUMN `del_flag` char(1) NOT NULL DEFAULT ''0'' AFTER `status`','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
