-- Register the Assistant creative text business pool without binding a guessed model.
INSERT INTO `aid_ai_model_func_config`
  (`func_name`,`func_code`,`model_type`,`generate_mode`,`model_ids`,`status`,`remark`,
   `create_by`,`create_time`,`update_by`,`update_time`,`del_flag`)
SELECT '助手创作文本','ASSISTANT_CREATIVE_TEXT','text','text',JSON_ARRAY(),'0',
       '助手创作文本业务池；模型由管理员显式绑定','system',NOW(),'system',NOW(),'0'
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM `aid_ai_model_func_config`
  WHERE `func_code`='ASSISTANT_CREATIVE_TEXT'
);


