-- Persisted Runtime Agent family boundary. Existing content is classified once and never rewritten.
SET @assistant_agent_family_column_exists := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_runtime_agent' AND COLUMN_NAME='agent_family'
);
SET @assistant_ddl := IF(
  @assistant_agent_family_column_exists=0,
  'ALTER TABLE aid_runtime_agent ADD COLUMN agent_family varchar(20) DEFAULT NULL AFTER agent_code',
  'SELECT 1'
);
PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;

DROP PROCEDURE IF EXISTS aid_migrate_runtime_agent_family;
DELIMITER $$
CREATE PROCEDURE aid_migrate_runtime_agent_family()
BEGIN
  DECLARE v_orphan_count bigint DEFAULT 0;
  DECLARE v_conflict_count bigint DEFAULT 0;
  DECLARE v_invalid_count bigint DEFAULT 0;

  SELECT
      (SELECT COUNT(*) FROM aid_runtime_agent_version v
       LEFT JOIN aid_runtime_agent a ON a.id=v.agent_id
       WHERE a.id IS NULL)
    + (SELECT COUNT(*) FROM aid_runtime_agent_draft d
       LEFT JOIN aid_runtime_agent a ON a.id=d.agent_id
       WHERE a.id IS NULL)
    + (SELECT COUNT(*) FROM aid_runtime_agent a
       LEFT JOIN aid_runtime_agent_version v ON v.id=a.current_version_id
       WHERE a.current_version_id IS NOT NULL
         AND (v.id IS NULL OR v.agent_id<>a.id OR v.del_flag<>'0'))
    + (SELECT COUNT(*) FROM aid_runtime_agent_skill_ref r
       LEFT JOIN aid_runtime_agent_version v ON v.id=r.agent_version_id
       WHERE v.id IS NULL)
    + (SELECT COUNT(*) FROM aid_runtime_agent_tool_ref r
       LEFT JOIN aid_runtime_agent_version v ON v.id=r.agent_version_id
       WHERE v.id IS NULL)
    + (SELECT COUNT(*) FROM aid_runtime_module_agent_binding b
       LEFT JOIN aid_runtime_agent a ON a.id=b.runtime_agent_id
       LEFT JOIN aid_runtime_agent_version v ON v.id=b.active_version_id
       WHERE b.status='ACTIVE' AND b.del_flag='0'
         AND (a.id IS NULL OR v.id IS NULL OR v.del_flag<>'0'
              OR v.agent_id<>a.id OR a.current_version_id<>b.active_version_id))
  INTO v_orphan_count;
  IF v_orphan_count > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AGENT_FAMILY_ORPHAN_DATA';
  END IF;

  DROP TEMPORARY TABLE IF EXISTS tmp_agent_family_evidence;
  CREATE TEMPORARY TABLE tmp_agent_family_evidence (
    agent_id bigint NOT NULL,
    source_kind varchar(16) NOT NULL,
    source_id bigint NOT NULL,
    marker varchar(16) NOT NULL,
    PRIMARY KEY (source_kind,source_id),
    KEY idx_tmp_agent_family_evidence (agent_id,marker)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

  INSERT INTO tmp_agent_family_evidence(agent_id,source_kind,source_id,marker)
  SELECT v.agent_id,'VERSION',v.id,
    CASE
      WHEN JSON_VALID(v.definition_json)=1
       AND JSON_TYPE(JSON_EXTRACT(CASE WHEN JSON_VALID(v.definition_json)=1 THEN v.definition_json ELSE '{}' END,'$'))='OBJECT'
       AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(v.definition_json)=1 THEN v.definition_json ELSE '{}' END,'$.executorType')) IN ('MODEL_PLAN','SKILL_ORCHESTRATOR')
       AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(v.definition_json)=1 THEN v.definition_json ELSE '{}' END,'$.protocolVersion')),'')=''
        THEN 'LEGACY'
      WHEN JSON_VALID(v.definition_json)=1
       AND JSON_TYPE(JSON_EXTRACT(CASE WHEN JSON_VALID(v.definition_json)=1 THEN v.definition_json ELSE '{}' END,'$'))='OBJECT'
       AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(v.definition_json)=1 THEN v.definition_json ELSE '{}' END,'$.executorType'))='ASSISTANT_LOOP'
       AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(v.definition_json)=1 THEN v.definition_json ELSE '{}' END,'$.protocolVersion')) IN ('assistant-loop/v1','assistant-loop/native-v1')
        THEN 'ASSISTANT'
      ELSE 'INVALID'
    END
  FROM aid_runtime_agent_version v
  WHERE v.del_flag='0';

  INSERT INTO tmp_agent_family_evidence(agent_id,source_kind,source_id,marker)
  SELECT d.agent_id,'ACTIVE_DRAFT',d.id,
    CASE
      WHEN JSON_VALID(d.draft_json)=1
       AND JSON_TYPE(JSON_EXTRACT(CASE WHEN JSON_VALID(d.draft_json)=1 THEN d.draft_json ELSE '{}' END,'$'))='OBJECT'
       AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(d.draft_json)=1 THEN d.draft_json ELSE '{}' END,'$.executorType')) IN ('MODEL_PLAN','SKILL_ORCHESTRATOR')
       AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(d.draft_json)=1 THEN d.draft_json ELSE '{}' END,'$.protocolVersion')),'')=''
        THEN 'LEGACY'
      WHEN JSON_VALID(d.draft_json)=1
       AND JSON_TYPE(JSON_EXTRACT(CASE WHEN JSON_VALID(d.draft_json)=1 THEN d.draft_json ELSE '{}' END,'$'))='OBJECT'
       AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(d.draft_json)=1 THEN d.draft_json ELSE '{}' END,'$.executorType'))='ASSISTANT_LOOP'
       AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(d.draft_json)=1 THEN d.draft_json ELSE '{}' END,'$.protocolVersion')) IN ('assistant-loop/v1','assistant-loop/native-v1')
        THEN 'ASSISTANT'
      ELSE 'INVALID'
    END
  FROM aid_runtime_agent_draft d
  WHERE d.status='EDITING' OR d.active_key IS NOT NULL;

  DROP TEMPORARY TABLE IF EXISTS tmp_agent_family_classification;
  CREATE TEMPORARY TABLE tmp_agent_family_classification (
    agent_id bigint NOT NULL,
    agent_family varchar(20) NOT NULL,
    PRIMARY KEY (agent_id)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

  INSERT INTO tmp_agent_family_classification(agent_id,agent_family)
  SELECT a.id,
    CASE
      WHEN COALESCE(SUM(e.marker='INVALID'),0)>0 THEN 'UNKNOWN'
      WHEN COALESCE(SUM(e.marker='LEGACY'),0)>0
       AND COALESCE(SUM(e.marker='ASSISTANT'),0)=0 THEN 'LEGACY_PLAN'
      WHEN COALESCE(SUM(e.marker='ASSISTANT'),0)>0
       AND COALESCE(SUM(e.marker='LEGACY'),0)=0 THEN 'ASSISTANT_LOOP'
      ELSE 'UNKNOWN'
    END
  FROM aid_runtime_agent a
  LEFT JOIN tmp_agent_family_evidence e ON e.agent_id=a.id
  GROUP BY a.id;

  SELECT COUNT(*) INTO v_conflict_count
  FROM aid_runtime_agent a
  JOIN tmp_agent_family_classification c ON c.agent_id=a.id
  WHERE a.agent_family IS NOT NULL AND a.agent_family<>''
    AND a.agent_family<>c.agent_family;
  IF v_conflict_count > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AGENT_FAMILY_EXISTING_CONFLICT';
  END IF;

  SELECT COUNT(*) INTO v_conflict_count
  FROM aid_runtime_module_agent_binding b
  JOIN tmp_agent_family_classification c ON c.agent_id=b.runtime_agent_id
  WHERE b.status='ACTIVE' AND b.del_flag='0' AND c.agent_family<>'ASSISTANT_LOOP';
  IF v_conflict_count > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AGENT_FAMILY_BINDING_CONFLICT';
  END IF;

  UPDATE aid_runtime_agent a
  JOIN tmp_agent_family_classification c ON c.agent_id=a.id
  SET a.agent_family=c.agent_family
  WHERE a.agent_family IS NULL OR a.agent_family='';

  UPDATE aid_runtime_agent
  SET status='1',update_by='agent-family-migration',update_time=NOW()
  WHERE agent_family='UNKNOWN' AND status<>'1';

  SELECT COUNT(*) INTO v_invalid_count
  FROM aid_runtime_agent
  WHERE agent_family IS NULL OR agent_family=''
     OR agent_family NOT IN ('LEGACY_PLAN','ASSISTANT_LOOP','UNKNOWN');
  IF v_invalid_count > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='AGENT_FAMILY_BACKFILL_INCOMPLETE';
  END IF;

  DROP TEMPORARY TABLE IF EXISTS tmp_agent_family_classification;
  DROP TEMPORARY TABLE IF EXISTS tmp_agent_family_evidence;
END$$
DELIMITER ;

CALL aid_migrate_runtime_agent_family();
DROP PROCEDURE IF EXISTS aid_migrate_runtime_agent_family;

SET @assistant_agent_family_index_exists := (
  SELECT COUNT(*) FROM information_schema.STATISTICS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_runtime_agent'
    AND INDEX_NAME='idx_runtime_agent_family'
);
SET @assistant_ddl := IF(
  @assistant_agent_family_index_exists=0,
  'ALTER TABLE aid_runtime_agent ADD KEY idx_runtime_agent_family (agent_family,status,del_flag,id)',
  'SELECT 1'
);
PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;

SET @assistant_agent_family_nullable := (
  SELECT IS_NULLABLE FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_runtime_agent' AND COLUMN_NAME='agent_family'
);
SET @assistant_agent_family_default := (
  SELECT COLUMN_DEFAULT FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_runtime_agent' AND COLUMN_NAME='agent_family'
);
SET @assistant_ddl := IF(
  @assistant_agent_family_nullable='YES' OR @assistant_agent_family_default IS NOT NULL,
  'ALTER TABLE aid_runtime_agent MODIFY COLUMN agent_family varchar(20) NOT NULL AFTER agent_code',
  'SELECT 1'
);
PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;

-- BEGIN STORYBOARD GRID REFERENCE CAPABILITY
-- 宫格按多模态参考提交；只迁移官方 Agnes 2.5 的旧默认首帧绑定。
-- 自定义默认参数或其他模型绑定保持不变；新安装与升级共用此幂等规则。
DROP TEMPORARY TABLE IF EXISTS tmp_aid_grid_reference_models;
CREATE TEMPORARY TABLE tmp_aid_grid_reference_models (model_id bigint NOT NULL PRIMARY KEY);
INSERT INTO tmp_aid_grid_reference_models (model_id)
SELECT m.id FROM aid_ai_model m
JOIN aid_ai_business_model_binding b ON b.model_id=m.id AND b.func_code='main_storyboard_video_grid'
  AND b.capability_code='image_to_video' AND b.default_capability=1 AND b.defaults_json IS NULL
JOIN aid_ai_model_capability c ON c.model_id=m.id AND c.capability_code='reference_to_video'
WHERE m.model_code IN ('agnes-video-2.5','agnes-video-2.5-flash') AND m.del_flag='0'
  AND NOT EXISTS (SELECT 1 FROM aid_ai_business_model_binding custom
    WHERE custom.model_id=m.id AND custom.func_code=b.func_code
      AND (custom.defaults_json IS NOT NULL OR (custom.default_capability=1 AND custom.capability_code<>'image_to_video')));
INSERT INTO aid_ai_business_model_binding
  (func_code,model_id,capability_code,default_capability,defaults_json,sort_order,create_time,create_by)
SELECT 'main_storyboard_video_grid',m.model_id,'reference_to_video',0,NULL,0,NOW(),'system'
FROM tmp_aid_grid_reference_models m
WHERE NOT EXISTS (SELECT 1 FROM aid_ai_business_model_binding b
  WHERE b.model_id=m.model_id AND b.func_code='main_storyboard_video_grid' AND b.capability_code='reference_to_video');
UPDATE aid_ai_business_model_binding b JOIN tmp_aid_grid_reference_models m ON m.model_id=b.model_id
SET b.default_capability=IF(b.capability_code='reference_to_video',1,0),b.update_time=NOW(),b.update_by='system'
WHERE b.func_code='main_storyboard_video_grid' AND b.capability_code IN ('image_to_video','reference_to_video');
DROP TEMPORARY TABLE tmp_aid_grid_reference_models;
-- END STORYBOARD GRID REFERENCE CAPABILITY

