-- BEGIN ASSISTANT BALANCE LOG RELATED-ID INDEX 20261004

DELIMITER $$
DROP PROCEDURE IF EXISTS `aid_ensure_balance_log_related_index`$$
CREATE PROCEDURE `aid_ensure_balance_log_related_index`()
BEGIN
  DECLARE v_index_count int DEFAULT 0;
  DECLARE v_index_columns text DEFAULT NULL;
  DECLARE v_non_unique int DEFAULT NULL;
  DECLARE v_prefix_or_order_invalid int DEFAULT 0;
  DECLARE v_index_type varchar(20) DEFAULT NULL;

  SELECT COUNT(DISTINCT `INDEX_NAME`),
         GROUP_CONCAT(`COLUMN_NAME` ORDER BY `SEQ_IN_INDEX` SEPARATOR ','),
         MIN(`NON_UNIQUE`),
         MAX(CASE WHEN `SUB_PART` IS NOT NULL OR COALESCE(`COLLATION`,'')<>'A' THEN 1 ELSE 0 END),
         MIN(`INDEX_TYPE`)
    INTO v_index_count, v_index_columns, v_non_unique,
         v_prefix_or_order_invalid, v_index_type
  FROM information_schema.STATISTICS
  WHERE `TABLE_SCHEMA`=DATABASE()
    AND `TABLE_NAME`='aid_balance_log'
    AND `INDEX_NAME`='idx_balance_log_related_id';

  IF v_index_count=0 THEN
    ALTER TABLE `aid_balance_log`
      ADD KEY `idx_balance_log_related_id` (`related_id`);
  ELSEIF v_index_count<>1 OR v_index_columns<>'related_id' OR v_non_unique<>1
      OR v_prefix_or_order_invalid<>0 OR v_index_type<>'BTREE' THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT='BALANCE_LOG_RELATED_ID_INDEX_INVALID';
  END IF;
END$$
DELIMITER ;

CALL `aid_ensure_balance_log_related_index`();
DROP PROCEDURE IF EXISTS `aid_ensure_balance_log_related_index`;

-- END ASSISTANT BALANCE LOG RELATED-ID INDEX 20261004

