-- Fresh seed bodies use the canonical root identity. Recompute only a current,
-- resource-free V1 seed when its digest differs; an already-correct package is untouched.
UPDATE aid_skill_version v JOIN aid_skill s ON s.current_version_id=v.id AND s.id=v.skill_id
SET v.package_digest=SHA2(CONCAT(
  '{"format":"aid-db-package-v1"',
  IF(s.skill_code IS NULL,'',CONCAT(',"skillCode":',JSON_QUOTE(s.skill_code))),
  IF(v.version_code IS NULL,'',CONCAT(',"versionCode":',JSON_QUOTE(v.version_code))),
  IF(v.visibility IS NULL,'',CONCAT(',"visibility":',JSON_QUOTE(v.visibility))),
  IF(v.invocation_scope IS NULL,'',CONCAT(',"invocationScope":',JSON_QUOTE(v.invocation_scope))),
  IF(v.executor_type IS NULL,'',CONCAT(',"executorType":',JSON_QUOTE(v.executor_type))),
  IF(v.model_code IS NULL,'',CONCAT(',"modelCode":',JSON_QUOTE(v.model_code))),
  CONCAT(',"systemPromptDigest":"',SHA2(COALESCE(v.system_prompt,''),256),'"'),
  CONCAT(',"inputSchemaDigest":"',SHA2(COALESCE(v.input_schema_json,''),256),'"'),
  CONCAT(',"outputSchemaDigest":"',SHA2(COALESCE(v.output_schema_json,''),256),'"'),
  CONCAT(',"definitionDigest":"',SHA2(COALESCE(v.definition_json,''),256),'"'),
  IF(v.max_output_tokens IS NULL,'',CONCAT(',"maxOutputTokens":',v.max_output_tokens)),
  IF(v.context_window_tokens IS NULL,'',CONCAT(',"contextWindowTokens":',v.context_window_tokens)),
  IF(v.safety_margin_tokens IS NULL,'',CONCAT(',"safetyMarginTokens":',v.safety_margin_tokens)),
  ',"resources":[],"relations":[]}'
),256),v.update_by='skill_identity_migration',v.update_time=NOW()
WHERE s.skill_code IN ('aid_screenwriter_craft','aid_screenwriter_adapt','aid_screenwriter_review','aid_method_automotive_sensory_ad','aid_method_branching_boxing_drama','aid_method_character_turnaround','aid_method_character_wardrobe','aid_method_cinematic_travelogue','aid_method_classic_wuxia_direction','aid_method_combat_motion','aid_method_eastern_atmosphere','aid_method_feminine_character','aid_method_frontier_duel_cinema','aid_method_gameplay_promo','aid_method_gothic_power_drama','aid_method_grounded_fight_choreography','aid_method_immersive_one_take','aid_method_manga_hero','aid_method_manga_heroine','aid_method_modern_oriental_ad','aid_method_observational_family_cinema','aid_method_photoreal_restoration','aid_method_reference_video_remake','aid_method_romance_fantasy_series','aid_method_script_character_visuals','aid_method_story_led_commercial','aid_method_symmetry_color_cinema','aid_method_youthful_character_look','character_card_image','character_turnaround_image','character_face_turnaround_image','character_form_image','storyboard_scene_image','storyboard_prop_image','storyboard_nine_grid','storyboard_four_grid','storyboard_25_grid','storyboard_light_correction','storyboard_time_forward','storyboard_time_backward','screenplay_write','screenplay_review') AND s.owner_type='PLATFORM' AND s.del_flag='0' AND v.del_flag='0' AND v.status='0'
  AND JSON_UNQUOTE(JSON_EXTRACT(v.manifest_json,'$.digestAlgorithm'))='aid-db-package-v1'
  AND NOT EXISTS (SELECT 1 FROM aid_skill_resource r WHERE r.skill_version_id=v.id AND r.status='0' AND r.del_flag='0')
  AND NOT EXISTS (SELECT 1 FROM aid_skill_relation r WHERE r.parent_version_id=v.id AND r.del_flag='0')
  AND v.package_digest<>SHA2(CONCAT(
  '{"format":"aid-db-package-v1"',
  IF(s.skill_code IS NULL,'',CONCAT(',"skillCode":',JSON_QUOTE(s.skill_code))),
  IF(v.version_code IS NULL,'',CONCAT(',"versionCode":',JSON_QUOTE(v.version_code))),
  IF(v.visibility IS NULL,'',CONCAT(',"visibility":',JSON_QUOTE(v.visibility))),
  IF(v.invocation_scope IS NULL,'',CONCAT(',"invocationScope":',JSON_QUOTE(v.invocation_scope))),
  IF(v.executor_type IS NULL,'',CONCAT(',"executorType":',JSON_QUOTE(v.executor_type))),
  IF(v.model_code IS NULL,'',CONCAT(',"modelCode":',JSON_QUOTE(v.model_code))),
  CONCAT(',"systemPromptDigest":"',SHA2(COALESCE(v.system_prompt,''),256),'"'),
  CONCAT(',"inputSchemaDigest":"',SHA2(COALESCE(v.input_schema_json,''),256),'"'),
  CONCAT(',"outputSchemaDigest":"',SHA2(COALESCE(v.output_schema_json,''),256),'"'),
  CONCAT(',"definitionDigest":"',SHA2(COALESCE(v.definition_json,''),256),'"'),
  IF(v.max_output_tokens IS NULL,'',CONCAT(',"maxOutputTokens":',v.max_output_tokens)),
  IF(v.context_window_tokens IS NULL,'',CONCAT(',"contextWindowTokens":',v.context_window_tokens)),
  IF(v.safety_margin_tokens IS NULL,'',CONCAT(',"safetyMarginTokens":',v.safety_margin_tokens)),
  ',"resources":[],"relations":[]}'
),256);
UPDATE aid_skill s JOIN aid_skill_version v ON v.id=s.current_version_id AND v.skill_id=s.id
SET s.config_hash=SHA2(CONCAT(s.skill_code,'|',v.version_code,'|',v.package_digest),256),
    s.update_by='skill_identity_migration',s.update_time=NOW()
WHERE s.skill_code IN ('aid_screenwriter_craft','aid_screenwriter_adapt','aid_screenwriter_review','aid_method_automotive_sensory_ad','aid_method_branching_boxing_drama','aid_method_character_turnaround','aid_method_character_wardrobe','aid_method_cinematic_travelogue','aid_method_classic_wuxia_direction','aid_method_combat_motion','aid_method_eastern_atmosphere','aid_method_feminine_character','aid_method_frontier_duel_cinema','aid_method_gameplay_promo','aid_method_gothic_power_drama','aid_method_grounded_fight_choreography','aid_method_immersive_one_take','aid_method_manga_hero','aid_method_manga_heroine','aid_method_modern_oriental_ad','aid_method_observational_family_cinema','aid_method_photoreal_restoration','aid_method_reference_video_remake','aid_method_romance_fantasy_series','aid_method_script_character_visuals','aid_method_story_led_commercial','aid_method_symmetry_color_cinema','aid_method_youthful_character_look','character_card_image','character_turnaround_image','character_face_turnaround_image','character_form_image','storyboard_scene_image','storyboard_prop_image','storyboard_nine_grid','storyboard_four_grid','storyboard_25_grid','storyboard_light_correction','storyboard_time_forward','storyboard_time_backward','screenplay_write','screenplay_review') AND s.owner_type='PLATFORM' AND s.del_flag='0'
  AND JSON_UNQUOTE(JSON_EXTRACT(v.manifest_json,'$.digestAlgorithm'))='aid-db-package-v1'
  AND s.config_hash<>SHA2(CONCAT(s.skill_code,'|',v.version_code,'|',v.package_digest),256);

-- Preserve the first explicit execution confirmation after renewing an expired run budget.
SET @assistant_schema := DATABASE();
SET @assistant_column_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_budget_policy' AND COLUMN_NAME='renewal_confirmation_revision');
SET @assistant_ddl := IF(@assistant_column_exists=0,'ALTER TABLE `aid_runtime_budget_policy` ADD COLUMN `renewal_confirmation_revision` bigint DEFAULT NULL COMMENT ''Authorization revision awaiting explicit execution confirmation'' AFTER `authorization_revision`','SELECT 1');
PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;

-- Index the global approval identity used to reject contradictory reservation evidence.
-- A same-name index is accepted only with exactly this full, non-unique BTREE column.
-- On a conflicting existing definition the ADD deliberately fails with duplicate-key-name;
-- never silently accept it or drop/rewrite an operator's index.
SET @assistant_schema := DATABASE();
SET @assistant_index_matches := (SELECT IF(COUNT(*)=1 AND SUM(CASE WHEN COLUMN_NAME='approval_id' AND SEQ_IN_INDEX=1 AND SUB_PART IS NULL AND NON_UNIQUE=1 AND INDEX_TYPE='BTREE' THEN 1 ELSE 0 END)=1,1,0) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_billing_authorization_reservation' AND INDEX_NAME='idx_reservation_approval');
SET @assistant_ddl := IF(@assistant_index_matches=1,'SELECT 1','ALTER TABLE `aid_billing_authorization_reservation` ADD INDEX `idx_reservation_approval` (`approval_id`)');
PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;

-- Derived conversation memory shared by authorized conversation consumers.
-- Original messages, accepted answers, artifacts and accounting records are retained separately.
CREATE TABLE IF NOT EXISTS `aid_conversation_context_memory` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `scope_type` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `scope_key` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `revision` bigint NOT NULL DEFAULT 1,
  `source_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `memory_json` longtext NOT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_context_memory_scope` (`user_id`,`scope_type`,`scope_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Derived context memory with source provenance';

-- Durable execution admission is separate from task outcomes and billing.
CREATE TABLE IF NOT EXISTS `aid_media_execution_admission_guard` (
  `id` tinyint NOT NULL,
  `ready` tinyint NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO `aid_media_execution_admission_guard` (`id`,`ready`) VALUES (1,0);

CREATE TABLE IF NOT EXISTS `aid_media_execution_permit` (
  `token` char(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `task_id` bigint NOT NULL,
  `user_id` bigint DEFAULT NULL,
  `user_bucket` varchar(160) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `model_code` varchar(160) NOT NULL,
  `provider_id` bigint DEFAULT NULL,
  `state` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `execution_mode` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `lease_until` datetime(3) DEFAULT NULL,
  `release_reason` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `create_time` datetime(3) NOT NULL,
  `update_time` datetime(3) NOT NULL,
  `released_at` datetime(3) DEFAULT NULL,
  `active_task_id` bigint GENERATED ALWAYS AS
    (CASE WHEN `state` IN ('RESERVED','ACTIVE') THEN `task_id` ELSE NULL END) STORED,
  PRIMARY KEY (`token`),
  UNIQUE KEY `uk_execution_active_task` (`active_task_id`),
  KEY `idx_execution_state` (`state`),
  KEY `idx_execution_user` (`user_bucket`,`state`),
  KEY `idx_execution_model` (`model_code`,`state`),
  KEY `idx_execution_provider` (`provider_id`,`state`),
  KEY `idx_execution_lease` (`state`,`execution_mode`,`lease_until`),
  KEY `idx_execution_task_history` (`task_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Execution permits independent from media outcomes and billing';

-- Reconcile obsolete current errors after successful assistant recovery.
-- Requires the runtime tables created earlier in this baseline/batch.
-- Clear only obsolete current errors whose original failure remains preserved.
-- No task outcome, step, message, authorization or ledger is changed.
UPDATE `aid_runtime_run` AS r
SET r.error_message = NULL
WHERE r.status = 'SUCCEEDED' AND r.del_flag = '0'
  AND r.error_message IS NOT NULL AND r.error_message <> ''
  AND EXISTS (
    SELECT 1 FROM `aid_runtime_run_step` AS failed
    WHERE failed.run_id = r.id AND failed.del_flag = '0'
      AND failed.status IN ('FAILED', 'FAILED_PRETASK')
      AND BINARY failed.error_message = BINARY r.error_message
  )
  AND NOT EXISTS (
    SELECT 1 FROM `aid_runtime_run_step` AS pending
    WHERE pending.run_id = r.id AND pending.del_flag = '0'
      AND (pending.status IS NULL OR pending.status NOT IN
        ('SUCCEEDED', 'FAILED', 'CANCELLED', 'FAILED_PRETASK', 'CANCELLED_PRETASK')
        OR pending.provider_acceptance_state = 'UNKNOWN')
  );

-- Scope execution-attempt uniqueness to the immutable plan revision.
-- No historical steps, task statuses, approvals or ledger rows are rewritten.
DROP PROCEDURE IF EXISTS aid_fix_runtime_step_plan_identity;
DELIMITER $$
CREATE PROCEDURE aid_fix_runtime_step_plan_identity()
BEGIN
  DECLARE existing_columns TEXT DEFAULT NULL;
  DECLARE existing_non_unique INT DEFAULT NULL;
  SELECT GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX SEPARATOR ','), MAX(NON_UNIQUE)
    INTO existing_columns, existing_non_unique
    FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_runtime_run_step'
      AND INDEX_NAME='uk_runtime_step_attempt';
  IF existing_columns IS NULL THEN
    ALTER TABLE aid_runtime_run_step ADD UNIQUE INDEX uk_runtime_step_attempt
      (run_id,plan_revision,stable_step_id,attempt_no);
  ELSEIF existing_columns='run_id,stable_step_id,attempt_no' AND existing_non_unique=0 THEN
    ALTER TABLE aid_runtime_run_step
      DROP INDEX uk_runtime_step_attempt,
      ADD UNIQUE INDEX uk_runtime_step_attempt (run_id,plan_revision,stable_step_id,attempt_no);
  ELSEIF existing_columns<>'run_id,plan_revision,stable_step_id,attempt_no' OR existing_non_unique<>0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RUNTIME_STEP_ATTEMPT_INDEX_UNEXPECTED';
  END IF;
END$$
DELIMITER ;
CALL aid_fix_runtime_step_plan_identity();
DROP PROCEDURE aid_fix_runtime_step_plan_identity;


-- 补齐官方视频模型历史空参数定义；保留已有自定义参数、启用状态、路由和价格。
UPDATE aid_ai_model_capability c
JOIN aid_ai_model m ON m.id=c.model_id
JOIN aid_ai_provider p ON p.id=m.provider_id
SET c.definition_json=JSON_SET(c.definition_json,
  '$.parameters', JSON_ARRAY(
    JSON_OBJECT('name','prompt','label','视频描述','type','string','widget','textarea','required',TRUE),
    JSON_OBJECT('name','durationSeconds','label','时长','type','integer','unit','秒','minimum',4,'maximum',12,'choices',JSON_ARRAY(4,5,6,7,8,9,10,11,12),'defaultValue',5),
    JSON_OBJECT('name','aspectRatio','label','画面比例','type','string','choices',JSON_ARRAY('21:9','16:9','4:3','1:1','3:4','9:16'),'defaultValue','16:9'),
    JSON_OBJECT('name','options','label','生成参数','type','object','properties',JSON_ARRAY(
      JSON_OBJECT('name','resolution','label','分辨率','type','string','choices',IF(m.model_code='agnes-video-2.5-flash',JSON_ARRAY('720P'),JSON_ARRAY('720P','960P','2K')),'defaultValue','720P'),
      JSON_OBJECT('name','seed','label','随机种子','type','integer'),
      JSON_OBJECT('name','n','label','生成数量','type','integer','choices',JSON_ARRAY(1),'defaultValue',1)
    ))
  ),
  '$.sourceUrls',JSON_ARRAY(IF(m.model_code='agnes-video-2.5-flash',
    'https://wiki.agnes-ai.cn/zh-Hans/docs/agnes-video-25-flash',
    'https://wiki.agnes-ai.cn/zh-Hans/docs/agnes-video-25'))),
  c.update_time=NOW(),c.update_by='system'
WHERE p.provider_code='agnes' AND m.del_flag='0'
  AND m.model_code IN ('agnes-video-2.5','agnes-video-2.5-flash')
  AND c.capability_code IN ('text_to_video','image_to_video','start_end_to_video','reference_to_video')
  AND JSON_VALID(c.definition_json)
  AND JSON_UNQUOTE(JSON_EXTRACT(c.definition_json,'$.evidenceStatus'))='VERIFIED_OFFICIAL'
  AND (JSON_EXTRACT(c.definition_json,'$.parameters') IS NULL
       OR (JSON_TYPE(JSON_EXTRACT(c.definition_json,'$.parameters'))='ARRAY'
           AND JSON_LENGTH(JSON_EXTRACT(c.definition_json,'$.parameters'))=0))
  AND JSON_CONTAINS(JSON_EXTRACT(c.definition_json,'$.sourceUrls'),
       JSON_QUOTE('https://wiki.agnes-ai.cn/models/agnes-video-2.5'));

-- Thinking output capability correction for the supported text protocol.
UPDATE aid_ai_model
SET capability_json=JSON_SET(capability_json,'$.supportsReasoningContent',true),
    config_version=COALESCE(config_version,0)+1
WHERE model_code='agnes-3.0-flash' AND model_type='text' AND del_flag='0'
  AND JSON_VALID(capability_json)=1
  AND JSON_EXTRACT(capability_json,'$.supportsReasoning')=true
  AND JSON_EXTRACT(capability_json,'$.supportsReasoningContent')=false;

UPDATE aid_ai_model_protocol_binding b JOIN aid_ai_model m ON m.id=b.model_id
SET b.definition_json=JSON_SET(b.definition_json,'$.capability.supportsReasoningContent',true)
WHERE m.model_code='agnes-3.0-flash' AND m.model_type='text' AND m.del_flag='0'
 AND b.protocol='openai-compatible-text' AND JSON_VALID(b.definition_json)=1
 AND JSON_EXTRACT(b.definition_json,'$.capability.supportsReasoning')=true
 AND JSON_EXTRACT(b.definition_json,'$.capability.supportsReasoningContent')=false;

-- Official audio model protocols and account resource ownership.
SET NAMES utf8mb4 COLLATE utf8mb4_general_ci;
SET @aid_audio_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_ai_provider' AND COLUMN_NAME='account_operations_json')=0,'ALTER TABLE aid_ai_provider ADD COLUMN account_operations_json TEXT NULL COMMENT ''官方账户查询相对路径配置''','SELECT 1');
PREPARE aid_audio_stmt FROM @aid_audio_ddl;
EXECUTE aid_audio_stmt;
DEALLOCATE PREPARE aid_audio_stmt;
