 id BIGINT NOT NULL AUTO_INCREMENT, provider_id BIGINT NOT NULL, user_id BIGINT NOT NULL,
 resource_kind VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, resource_id VARCHAR(192) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 purpose VARCHAR(32) NULL, create_time DATETIME NULL, PRIMARY KEY(id),
 UNIQUE KEY uk_audio_resource_owner(provider_id,user_id,resource_kind,resource_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='官方音频资源用户归属';
