":[{"skuCode":"post_audio_generate","skuName":"多模态音频生成","remark":"按秒计价，多版本按总时长计价","enabled":true,"priority":1,"match":{},"meterType":"PER_SECOND","pricePerSecond":0.016666666667}],"settleRule":{"settleMode":"REFUND_ONLY","usageSource":"PROVIDER_USAGE","allowRefund":true,"allowExtraCharge":false}}}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='seed-audio-1.0' AND p.provider_code='volcengine_seed_audio' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_protocol_binding x WHERE x.model_id=m.id AND x.capability_code='post_audio_generate' AND x.binding_code='official');
