SELECT m.id,'post_lyrics_generation','lyrics','{"code":"post_lyrics_generation","label":"歌词生成或编辑","generateMode":"lyrics","enabled":false,"defaultCapability":false,"evidenceStatus":"VERIFIED","sourceUrls":["https://platform.minimax.cn/docs/api-reference/music-generation"],"parameters":[{"name":"options","label":"官方参数","type":"object","properties":[{"name":"mode","label":"mode","type":"string","description":"生成模式。<br>`write_full_song`：写完整歌曲<br>`edit`：编辑/续写歌词","required":true,"choices":["write_full_song","edit"],"widget":"textarea"},{"name":"prompt","label":"prompt","type":"string","description":"提示词/指令，用于描述歌曲主题、风格或编辑方向。为空时随机生成。","required":false,"maximum":2000,"widget":"textarea"},{"name":"lyrics","label":"lyrics","type":"string","description":"现有歌词内容，仅在 `edit` 模式下有效。可用于续写或修改已有歌词。","required":false,"maximum":3500,"widget":"textarea"},{"name":"title","label":"title","type":"string","description":"歌曲标题。传入后输出将保持该标题不变。","required":false,"widget":"textarea"}]}],"rules":[],"presentation":{"supportsTextInput":false,"maxOutputCount":1,"defaultOutputCount":1}}',1,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='music-3.0' AND p.provider_code='minimax' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_capability x WHERE x.model_id=m.id AND x.capability_code='post_lyrics_generation');
