SELECT m.id,'post_lyrics_generation','official','minimax-music','{"code":"official","protocol":"minimax-music","upstreamModel":"music-3.0","apiSuffix":"/v1/lyrics_generation","defaultBinding":true,"enabled":true,"capability":{"officialAudioOperation":"minimax.post.lyrics_generation","ttsTextRequired":false,"ttsVoiceRequired":false,"audioOperation":"official_audio","officialRequestSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","required":["mode"],"properties":{"mode":{"type":"string","description":"生成模式。<br>`write_full_song`：写完整歌曲<br>`edit`：编辑/续写歌词","enum":["write_full_song","edit"]},"prompt":{"type":"string","description":"提示词/指令，用于描述歌曲主题、风格或编辑方向。为空时随机生成。","maxLength":2000},"lyrics":{"type":"string","description":"现有歌词内容，仅在 `edit` 模式下有效。可用于续写或修改已有歌词。","maxLength":3500},"title":{"type":"string","description":"歌曲标题。传入后输出将保持该标题不变。"}},"additionalProperties":false,"$defs":{}}},"fixedParameters":{},"mappings":[],"billingMode":"SKU","billingRule":{"mode":"SKU","meterType":"SKU_PACKAGE","chargeType":"AUDIO","preHold":true,"priceCurrency":"CNY","exchangeRateToCny":1,"matchStrategy":"FIRST_HIT","params":[],"skus":[{"skuCode":"post_lyrics_generation","skuName":"歌词生成或编辑","remark":"按生成歌曲数量计价，数量由官方参数服务端验证","enabled":false,"priority":1,"match":{},"meterType":"SKU_PACKAGE"}],"settleRule":{"settleMode":"REFUND_ONLY","usageSource":"PROVIDER_USAGE","allowRefund":true,"allowExtraCharge":false}}}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='music-3.0' AND p.provider_code='minimax' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_protocol_binding x WHERE x.model_id=m.id AND x.capability_code='post_lyrics_generation' AND x.binding_code='official');
