thesis.","required":false,"items":{"name":"item","label":"TextToDialogueWebsocketVoiceInput","type":"object","required":false,"properties":[{"name":"text","label":"text","type":"string","description":"Text appended for this voice. Buffered with prior text until the server triggers generation.","required":true,"widget":"textarea"},{"name":"voice_id","label":"voice_id","type":"string","description":"Must be one of the IDs from the initial `voices` array.","required":true,"widget":"textarea"},{"name":"new_turn","label":"new_turn","type":"boolean","description":"When `true`, the server finalizes the current pending segment (as if the speaker finished their turn) before applying this input.","required":false}]}},{"name":"flush","label":"flush","type":"boolean","description":"Force generation of buffered text without closing the connection.","required":false},{"name":"close_socket","label":"close_socket","type":"boolean","description":"Flush buffers, emit remaining audio, send `is_final`, and close the WebSocket.","required":false},{"name":"keep_alive","label":"keep_alive","type":"boolean","description":"Resets the 20s inactivity timer; performs no synthesis.","required":false},{"name":"voices","label":"voices","type":"array","description":"Voice IDs to load for the session (first message only, required on first message).","required":false,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"voice_settings","label":"TextToDialogueWebsocketVoiceSettings","type":"object","description":"Voice settings for dialogue generation. Only `stability` is supported for `eleven_v3` dialogue models.","required":false,"properties":[{"name":"stability","label":"stability","type":"number","description":"Determines how stable the voice is and the randomness between each generation. Lower values introduce broader emotional range for the voice. Higher values can result in a monotonous voice with limited emotion.","required":false,"minimum":0,"m