SELECT p.id,'music_v2_5','music_v2_5','Eleven Music 2.5','audio','text_to_music','/v1/music','elevenlabs-audio','1','0','SKU','{"mode":"SKU","meterType":"PER_SECOND","chargeType":"AUDIO","preHold":true,"priceCurrency":"USD","exchangeRateToCny":null,"matchStrategy":"FIRST_HIT","params":[],"skus":[{"skuCode":"post_music","skuName":"音乐作曲","remark":"按秒计价，多版本按总时长计价","enabled":true,"priority":1,"match":{},"meterType":"PER_SECOND","pricePerSecond":0.0025}],"settleRule":{"settleMode":"REFUND_ONLY","usageSource":"PROVIDER_USAGE","allowRefund":true,"allowExtraCharge":false}}','1','{"officialAudioOperation":"elevenlabs.post.music","ttsTextRequired":false,"ttsVoiceRequired":false,"audioOperation":"official_audio","officialRequestSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"prompt":{"type":["string","null"],"maxLength":4100,"description":"A simple text prompt to generate a song from. Cannot be used in conjunction with `composition_plan`."},"composition_plan":{"oneOf":[{"$ref":"#/$defs/BodyComposeMusicV1MusicPostCompositionPlan"},{"type":"null"}],"description":"A detailed composition plan to guide music generation. Cannot be used in conjunction with `prompt`."},"music_length_ms":{"type":["integer","null"],"minimum":3000,"maximum":600000,"description":"The length of the song to generate in milliseconds. Used only in conjunction with `prompt`. Must be between 3000ms and 600000ms. Optional - if not provided, the model will choose a length based on the prompt."},"model_id":{"$ref":"#/$defs/MusicModelID","default":"music_v1","description":"The model to use for the generation."},"seed":{"type":["integer","null"],"minimum":0,"maximum":2147483647,"description":"Random seed to initialize the music generation process. Providing the same seed with the same parameters can help achieve more consistent results, but exact reproducibility is not guaranteed and outputs may change across system updates. Cannot be used in conjunction with prompt."},"force_instrumental":{"type":"boolean","default":false,"description":"If true, guarantees that the generated song will be instrumental. If false, the song may or may not be instrumental depending on the `prompt`. Can only be used with `prompt`."},"finetune_id":{"type":["string","null"],"maxLength":100,"description":"The ID of the finetune to use for the generation"},"respect_sections_durations":{"type":"boolean","default":true,"description":"Controls how strictly section durations in the `composition_plan` are enforced. Only used with `composition_plan` and only applies to `music_v1`; for `music_v2` and `music_v2_5` section durations are always enforced and this is ignored. When false for `music_v1`, the model may adjust individual section durations for better quality and latency, while preserving the total song duration from the plan."},"store_for_inpainting":{"type":"boolean","default":false,"description":"Whether to store the generated song for inpainting."},"sign_with_c2pa":{"type":"boolean","default":false,"description":"Whether to sign the generated song with C2PA. Applicable only for mp3 files."},"queryParameters":{"type":"object","properties":{"output_format":{"$ref":"#/$defs/V1MusicPostParametersOutputFormat","default":"auto"},"enable_logging":{"type":"boolean","default":true}},"additionalProperties":false}},"title":"Body_Compose_music_v1_music_post","additionalProperties":false,"$defs":{"BodyComposeMusicV1MusicPostCompositionPlan":{"oneOf":[{"$ref":"#/$defs/MusicPrompt"},{"$ref":"#/$defs/CompositionPlan"}],"description":"A detailed composition plan to guide music generation. Cannot be used in conjunction with `prompt`.","title":"BodyComposeMusicV1MusicPostCompositionPlan"},"MusicModelID":{"type":"string","enum":["music_v1","music_v2","music_v2_5"],"default":"music_v1","title":"MusicModelID"},"V1MusicPostParametersOutputFormat":{"type":"string","enum":["auto","mp3_48000_128","mp3_48000_192","mp3_48000_240","mp3_48000_320","mp3_22050_32","mp3_24000_48","mp