SELECT m.id,'post_music_video_to_music','official','elevenlabs-audio','{"code":"official","protocol":"elevenlabs-audio","upstreamModel":"music_v2_5","apiSuffix":"/v1/music/video-to-music","defaultBinding":true,"enabled":true,"capability":{"officialAudioOperation":"elevenlabs.post.music_video_to_music","ttsTextRequired":false,"ttsVoiceRequired":false,"audioOperation":"official_audio","officialRequestSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"videos":{"type":"array","items":{"type":"string","format":"binary"},"description":"\\n            One or more video files sent via FormData array (multipart/form-data). They will be combined into one codec in order.\\n            A maximum of 10 videos is allowed, where the total size of the combined video is limited to 200MB.\\n            In total, the video can be up to 600 seconds long. Note that combining multiple videos may increase the request duration significantly. If possible, combine the videos beforehand.\\n            ","maxItems":10,"minItems":1},"description":{"type":["string","null"],"minLength":1,"maxLength":4100,"description":"Optional text description of the music you want. A maximum of 4100 characters is allowed."},"tags":{"type":"array","items":{"type":"string"},"default":[],"description":"Optional list of style tags (e.g. [''upbeat'', ''cinematic'']). A maximum of 10 tags is allowed.","maxItems":10},"model_id":{"$ref":"#/$defs/MusicModelID","default":"music_v1","description":"The model to use for the generation."},"add_sfx":{"type":"boolean","default":false,"description":"When true, incorporate SFX cues from the video."},"separate_tracks":{"type":"boolean","default":false,"description":"When true, return a ZIP with separate music and SFX audio tracks instead of a single mixed file. Use this for more flexibility to layer the tracks."},"use_audio_as_reference":{"type":"boolean","default":false,"description":"When true, analyze the video''s audio track and use its genres, BPM, instrumentation, mood, and arc as reference characteristics for music generation."},"sign_with_c2pa":{"type":"boolean","default":false,"description":"Whether to sign the generated song with C2PA. Applicable only for mp3 files."},"queryParameters":{"type":"object","properties":{"output_format":{"$ref":"#/$defs/AllowedOutputFormats"},"enable_logging":{"type":"boolean","default":true}},"additionalProperties":false}},"required":["videos"],"additionalProperties":false,"$defs":{"MusicModelID":{"type":"string","enum":["music_v1","music_v2","music_v2_5"],"default":"music_v1","title":"MusicModelID"},"AllowedOutputFormats":{"type":"string","enum":["mp3_22050_32","mp3_24000_48","mp3_44100_32","mp3_44100_64","mp3_44100_96","mp3_44100_128","mp3_44100_192","pcm_8000","pcm_16000","pcm_22050","pcm_24000","pcm_32000","pcm_44100","pcm_48000","ulaw_8000","alaw_8000","opus_48000_32","opus_48000_64","opus_48000_96","opus_48000_128","opus_48000_192"],"title":"AllowedOutputFormats"}}}},"fixedParameters":{},"mappings":[],"billingMode":"SKU","billingRule":{"mode":"SKU","meterType":"PER_SECOND","chargeType":"AUDIO","preHold":true,"priceCurrency":"USD","exchangeRateToCny":null,"matchStrategy":"FIRST_HIT","params":[],"skus":[{"skuCode":"post_music_video_to_music","skuName":"视频配乐","remark":"按秒计价，多版本按总时长计价","enabled":true,"priority":1,"match":{},"meterType":"PER_SECOND","pricePerSecond":0.0025}],"settleRule":{"settleMode":"REFUND_ONLY","usageSource":"PROVIDER_USAGE","allowRefund":true,"allowExtraCharge":false}}}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='music_v2_5' AND p.provider_code='elevenlabs' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_protocol_binding x WHERE x.model_id=m.id AND x.capability_code='post_music_video_to_music' AND x.binding_code='official');
