   status, del_flag, billing_mode, billing_rule_json, capability_json, capability_inited, official_price_url,
   supports_text_input, supports_image_input, supports_multi_image_input, supports_duration, supports_first_frame,
   supports_size_preset, default_size_code, default_duration_seconds, create_time, create_by)
