-- Reuse configured business capabilities of the existing official GPT Image family.
INSERT INTO aid_ai_business_model_binding
(func_code,model_id,capability_code,default_capability,defaults_json,sort_order,create_time,create_by)
SELECT b.func_code,n.id,b.capability_code,b.default_capability,b.defaults_json,b.sort_order,NOW(),'system'
FROM aid_ai_model prior
JOIN aid_ai_business_model_binding b ON b.model_id=prior.id
JOIN aid_ai_model n ON n.provider_id=prior.provider_id AND n.model_code IN ('gpt-image-2.6-flare','gpt-image-2.6-sunburst') AND n.del_flag='0'
JOIN aid_ai_model_capability c ON c.model_id=n.id AND c.capability_code=b.capability_code
WHERE prior.model_code='gpt-image-2.5-flare' AND prior.del_flag='0'
AND NOT EXISTS (SELECT 1 FROM aid_ai_business_model_binding x WHERE x.model_id=n.id AND x.func_code=b.func_code AND x.capability_code=b.capability_code);

UPDATE aid_ai_model_func_config f
JOIN aid_ai_model m ON m.model_code='gpt-image-2.6-flare' AND m.del_flag='0'
SET f.model_ids=JSON_ARRAY_APPEND(f.model_ids,'$',m.id)
WHERE f.del_flag='0'
AND EXISTS (SELECT 1 FROM aid_ai_business_model_binding b WHERE b.model_id=m.id AND b.func_code=f.func_code)
AND NOT JSON_CONTAINS(f.model_ids,CAST(m.id AS JSON));

UPDATE aid_ai_model_func_config f
JOIN aid_ai_model m ON m.model_code='gpt-image-2.6-sunburst' AND m.del_flag='0'
SET f.model_ids=JSON_ARRAY_APPEND(f.model_ids,'$',m.id)
WHERE f.del_flag='0'
AND EXISTS (SELECT 1 FROM aid_ai_business_model_binding b WHERE b.model_id=m.id AND b.func_code=f.func_code)
AND NOT JSON_CONTAINS(f.model_ids,CAST(m.id AS JSON));

COMMIT;


