INSERT INTO aid_ai_business_model_binding (func_code,model_id,capability_code,default_capability,defaults_json,sort_order,create_time,create_by) SELECT b.func_code,@k4_model,b.capability_code,b.default_capability,b.defaults_json,b.sort_order,NOW(),'system' FROM aid_ai_model prior JOIN aid_ai_business_model_binding b ON b.model_id=prior.id JOIN aid_ai_model_capability c ON c.model_id=@k4_model AND c.capability_code=b.capability_code WHERE prior.model_code='kling-3.0-omni-t2v' AND prior.del_flag='0' AND NOT EXISTS(SELECT 1 FROM aid_ai_business_model_binding x WHERE x.model_id=@k4_model AND x.func_code=b.func_code AND x.capability_code=b.capability_code);

UPDATE aid_ai_model_func_config f SET f.model_ids=JSON_ARRAY_APPEND(f.model_ids,'$',@k4_model) WHERE @k4_model IS NOT NULL AND f.del_flag='0' AND EXISTS(SELECT 1 FROM aid_ai_business_model_binding b WHERE b.model_id=@k4_model AND b.func_code=f.func_code) AND NOT JSON_CONTAINS(f.model_ids,CAST(@k4_model AS JSON));

COMMIT;

