WHERE b.module_code='UNIVERSAL' AND b.runtime_agent_id=@aid_starter_agent AND b.active_version_id=@aid_starter_old_version
  AND b.status='ACTIVE' AND b.del_flag='0' AND @aid_starter_version IS NOT NULL;
