SELECT 'UNIVERSAL',@aid_starter_agent,@aid_starter_version,1,'ACTIVE','0','community-starter',NOW()
WHERE @aid_starter_version IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM aid_runtime_module_agent_binding WHERE module_code='UNIVERSAL');

-- SCREENWRITER
INSERT INTO aid_runtime_agent (agent_code,agent_family,name,description,owner_type,visibility,status,del_flag,create_by,create_time)
SELECT 'story_script_agent','ASSISTANT_LOOP',CONVERT(0xe589a7e69cace5b7a5e4bd9ce58fb0 USING utf8mb4),CONVERT( USING utf8mb4),'PLATFORM','PUBLIC','0','0','community-starter',NOW()
WHERE NOT EXISTS(SELECT 1 FROM aid_runtime_agent WHERE agent_code='story_script_agent');
SET @aid_starter_agent := (SELECT a.id FROM aid_runtime_agent a WHERE a.agent_code='story_script_agent'
  AND a.owner_type='PLATFORM' AND a.del_flag='0' AND a.status='0'
  AND ((a.current_version_id IS NULL AND a.create_by='community-starter') OR EXISTS (SELECT 1 FROM aid_runtime_agent_version old
    JOIN aid_runtime_module_agent_binding b ON b.active_version_id=old.id AND b.runtime_agent_id=old.agent_id
    WHERE old.id=a.current_version_id AND b.module_code='SCREENWRITER' AND b.status='ACTIVE'
      AND b.del_flag='0' AND ((old.version_code='3.0.0-community-starter' AND old.create_by='community-starter' AND b.binding_revision=1)))) LIMIT 1);
SET @aid_starter_old_version := (SELECT current_version_id FROM aid_runtime_agent WHERE id=@aid_starter_agent);
SET @aid_starter_refs := (SELECT CONCAT('[',COALESCE(GROUP_CONCAT(CONCAT(
  '{"skillCode":',JSON_QUOTE(s.skill_code),',"skillId":"',s.id,'","skillVersionId":"',v.id,
  '","packageDigest":',JSON_QUOTE(v.package_digest),'}') ORDER BY s.skill_code SEPARATOR ','),''),']')
  FROM aid_skill s JOIN aid_skill_version v ON v.id=s.current_version_id AND v.skill_id=s.id
  WHERE s.skill_code IN ('story_creation_flow','story_creation_design','story_adaptation_flow','story_adaptation_design') AND s.owner_type='PLATFORM' AND s.visibility='PUBLIC'
    AND s.status='0' AND s.del_flag='0' AND v.visibility='PUBLIC' AND v.status='0' AND v.del_flag='0'
    AND v.publish_status='PUBLISHED');
SET @aid_starter_instruction := CONVERT( USING utf8mb4);
SET @aid_starter_previous_model := (SELECT model_config_json FROM aid_runtime_agent_version
  WHERE id=@aid_starter_old_version AND version_code='3.0.0-community-starter' AND create_by='community-starter');
SET @aid_starter_model := COALESCE(@aid_starter_previous_model,
  REPLACE(CONVERT( USING utf8mb4),'"__AID_DEFAULT_MODEL__"',JSON_QUOTE(@aid_community_text_model)));
SET @aid_starter_definition := REPLACE(REPLACE(CONVERT( USING utf8mb4),
  '__AID_AGENT_ID__',CAST(@aid_starter_agent AS CHAR)),'"__AID_BOUND_SKILLS__"',@aid_starter_refs);
SET @aid_starter_agent_digest := SHA2(CONCAT(@aid_starter_instruction,CHAR(10),@aid_starter_model,CHAR(10),
  @aid_starter_common_input,CHAR(10),@aid_starter_common_output,CHAR(10),@aid_starter_definition),256);
INSERT INTO aid_runtime_agent_version (agent_id,version_code,publish_status,instruction,model_config_json,input_schema_json,
  output_schema_json,definition_json,package_digest,status,del_flag,create_by,create_time,update_by,update_time)
SELECT @aid_starter_agent,'3.0.0-community-starter-v2','FROZEN',@aid_starter_instruction,@aid_starter_model,@aid_starter_common_input,
  @aid_starter_common_output,@aid_starter_definition,@aid_starter_agent_digest,'0','0','community-starter',NOW(),'community-starter',NOW()
WHERE @aid_starter_agent IS NOT NULL AND JSON_LENGTH(@aid_starter_refs)=4
AND NOT EXISTS(SELECT 1 FROM aid_runtime_agent_version WHERE agent_id=@aid_starter_agent AND version_code='3.0.0-community-starter-v2');
SET @aid_starter_version := (SELECT id FROM aid_runtime_agent_version WHERE agent_id=@aid_starter_agent
  AND version_code='3.0.0-community-starter-v2' AND BINARY package_digest=BINARY @aid_starter_agent_digest AND create_by='community-starter' LIMIT 1);
