-- Complete storage metadata for starter packages from earlier private candidates.
UPDATE aid_runtime_agent_version
SET update_by=create_by,update_time=create_time
WHERE create_by='community-starter' AND version_code='3.0.0-community-starter' AND update_time IS NULL;
UPDATE aid_skill_version
SET update_by=create_by,update_time=create_time
WHERE create_by='community-starter' AND version_code='1.0.0-community' AND update_time IS NULL;
UPDATE aid_skill_resource r
JOIN aid_skill_version v ON v.id=r.skill_version_id
JOIN aid_skill s ON s.id=v.skill_id
SET r.object_key=CONCAT('database:skills/platform/official/',s.skill_code,'/',v.version_code,'/SKILL.md')
WHERE r.resource_key='__skill_md' AND r.create_by='community-starter'
  AND v.create_by='community-starter' AND v.version_code='1.0.0-community'
  AND BINARY r.object_key=BINARY CONCAT('skill/',s.id,'/',v.id,'/SKILL.md');
COMMIT;
SET SESSION group_concat_max_len = @aid_previous_group_concat;

-- Refresh stock assistant instructions for resources already available to the deployment.
START TRANSACTION;

SET @aid_auto_resource_prompt := CONVERT( USING utf8mb4);
SET @aid_auto_resource_previous := (
  SELECT v.id FROM aid_runtime_agent a
  JOIN aid_runtime_agent_version v ON v.id=a.current_version_id AND v.agent_id=a.id
  JOIN aid_runtime_module_agent_binding b ON b.runtime_agent_id=a.id AND b.active_version_id=v.id
  WHERE a.agent_code='universal_canvas_agent' AND a.owner_type='PLATFORM' AND a.status='0' AND a.del_flag='0'
    AND v.version_code='3.0.0-community-starter-v2' AND v.create_by='community-starter'
    AND v.publish_status='FROZEN' AND v.status='0' AND v.del_flag='0'
    AND b.module_code='UNIVERSAL' AND b.status='ACTIVE' AND b.del_flag='0'
    AND COALESCE(b.update_by,'') IN ('','community-starter','system')
    AND NOT EXISTS (SELECT 1 FROM aid_runtime_agent_version n
                    WHERE n.agent_id=a.id AND n.version_code='3.0.0-community-starter-v3')
);
SET @aid_auto_resource_definition := (SELECT JSON_SET(definition_json,
  '$.mainMarkdown',@aid_auto_resource_prompt,'$.systemPrompt',@aid_auto_resource_prompt,
  '$.packageVersionCode','3.0.0-community-starter-v3')
  FROM aid_runtime_agent_version WHERE id=@aid_auto_resource_previous);
INSERT INTO aid_runtime_agent_version (agent_id,version_code,publish_status,instruction,model_config_json,input_schema_json,
  output_schema_json,definition_json,package_digest,status,del_flag,create_by,create_time,update_by,update_time)
SELECT agent_id,'3.0.0-community-starter-v3','FROZEN',@aid_auto_resource_prompt,model_config_json,input_schema_json,
  output_schema_json,@aid_auto_resource_definition,
  SHA2(CONCAT_WS(CHAR(10),@aid_auto_resource_prompt,model_config_json,input_schema_json,output_schema_json,@aid_auto_resource_definition),256),
  '0','0','community-starter',NOW(),'community-starter',NOW()
FROM aid_runtime_agent_version WHERE id=@aid_auto_resource_previous;
SET @aid_auto_resource_new := IF(ROW_COUNT()=1,LAST_INSERT_ID(),NULL);
INSERT INTO aid_runtime_agent_skill_ref (agent_version_id,skill_id,skill_version_id,skill_code,package_digest)
SELECT @aid_auto_resource_new,skill_id,skill_version_id,skill_code,package_digest FROM aid_runtime_agent_skill_ref
WHERE agent_version_id=@aid_auto_resource_previous AND @aid_auto_resource_new IS NOT NULL;
INSERT INTO aid_runtime_agent_tool_ref (agent_version_id,tool_code,contract_version,schema_digest)
SELECT @aid_auto_resource_new,tool_code,contract_version,schema_digest FROM aid_runtime_agent_tool_ref
WHERE agent_version_id=@aid_auto_resource_previous AND @aid_auto_resource_new IS NOT NULL;
UPDATE aid_runtime_agent SET current_version_id=@aid_auto_resource_new
WHERE agent_code='universal_canvas_agent' AND current_version_id=@aid_auto_resource_previous AND @aid_auto_resource_new IS NOT NULL;
UPDATE aid_runtime_module_agent_binding SET active_version_id=@aid_auto_resource_new,binding_revision=binding_revision+1
WHERE module_code='UNIVERSAL' AND active_version_id=@aid_auto_resource_previous AND @aid_auto_resource_new IS NOT NULL;

SET @aid_auto_resource_prompt := CONVERT( USING utf8mb4);
SET @aid_auto_resource_previous := (
  SELECT v.id FROM aid_runtime_agent a
  JOIN aid_runtime_agent_version v ON v.id=a.current_version_id AND v.agent_id=a.id
  JOIN aid_runtime_module_agent_binding b ON b.runtime_agent_id=a.id AND b.active_version_id=v.id
  WHERE a.agent_code='previz_3dbox_agent' AND a.owner_type='PLATFORM' AND a.status='0' AND a.del_flag='0'
    AND v.version_code IN ('3.0.0-community-starter-v2','3.0.0-community-starter-v3') AND v.create_by='community-starter'
    AND v.publish_status='FROZEN' AND v.status='0' AND v.del_flag='0'
    AND b.module_code='PREVIZ_3DBOX' AND b.status='ACTIVE' AND b.del_flag='0'
    AND COALESCE(b.update_by,'') IN ('','community-starter','system')
    AND NOT EXISTS (SELECT 1 FROM aid_runtime_agent_version n
                    WHERE n.agent_id=a.id AND n.version_code='3.0.0-community-starter-v4')
);
SET @aid_hub_method_version := (
  SELECT v.id FROM aid_skill s
  JOIN aid_skill_version v ON v.id=s.current_version_id AND v.skill_id=s.id
  JOIN aid_runtime_agent_skill_ref r ON r.skill_id=s.id AND r.agent_version_id=@aid_auto_resource_previous
  JOIN aid_skill_version old ON old.id=r.skill_version_id AND old.skill_id=s.id
  WHERE s.skill_code='previz_3dbox_method' AND s.owner_type='PLATFORM' AND s.create_by='community-starter'
    AND v.version_code='1.0.2-community' AND v.create_by='community-starter'
    AND old.version_code IN ('1.0.1-community','1.0.2-community') AND old.create_by='community-starter'
);
SET @aid_hub_method_binding := (
  SELECT JSON_ARRAY(JSON_OBJECT('skillCode',s.skill_code,'skillId',CAST(s.id AS CHAR),
    'skillVersionId',CAST(v.id AS CHAR),'packageDigest',v.package_digest))
  FROM aid_skill_version v JOIN aid_skill s ON s.id=v.skill_id WHERE v.id=@aid_hub_method_version
);
SET @aid_auto_resource_definition := (SELECT JSON_SET(definition_json,
  '$.skillBindings',IF(@aid_hub_method_version IS NULL,JSON_EXTRACT(definition_json,'$.skillBindings'),
    JSON_EXTRACT(@aid_hub_method_binding,'$')),
  '$.mainMarkdown',@aid_auto_resource_prompt,'$.systemPrompt',@aid_auto_resource_prompt,
  '$.packageVersionCode','3.0.0-community-starter-v4')
  FROM aid_runtime_agent_version WHERE id=@aid_auto_resource_previous);
INSERT INTO aid_runtime_agent_version (agent_id,version_code,publish_status,instruction,model_config_json,input_schema_json,
  output_schema_json,definition_json,package_digest,status,del_flag,create_by,create_time,update_by,update_time)
SELECT agent_id,'3.0.0-community-starter-v4','FROZEN',@aid_auto_resource_prompt,model_config_json,input_schema_json,
  output_schema_json,@aid_auto_resource_definition,
  SHA2(CONCAT_WS(CHAR(10),@aid_auto_resource_prompt,model_config_json,input_schema_json,output_schema_json,@aid_auto_resource_definition),256),
  '0','0','community-starter',NOW(),'community-starter',NOW()
FROM aid_runtime_agent_version WHERE id=@aid_auto_resource_previous;
SET @aid_auto_resource_new := IF(ROW_COUNT()=1,LAST_INSERT_ID(),NULL);
INSERT INTO aid_runtime_agent_skill_ref (agent_version_id,skill_id,skill_version_id,skill_code,package_digest)
SELECT @aid_auto_resource_new,r.skill_id,COALESCE(v.id,r.skill_version_id),r.skill_code,
  COALESCE(v.package_digest,r.package_digest)
FROM aid_runtime_agent_skill_ref r
LEFT JOIN aid_skill_version v ON v.id=@aid_hub_method_version AND v.skill_id=r.skill_id
WHERE r.agent_version_id=@aid_auto_resource_previous AND @aid_auto_resource_new IS NOT NULL;
INSERT INTO aid_runtime_agent_tool_ref (agent_version_id,tool_code,contract_version,schema_digest)
SELECT @aid_auto_resource_new,tool_code,contract_version,schema_digest FROM aid_runtime_agent_tool_ref
WHERE agent_version_id=@aid_auto_resource_previous AND @aid_auto_resource_new IS NOT NULL;
UPDATE aid_runtime_agent SET current_version_id=@aid_auto_resource_new
WHERE agent_code='previz_3dbox_agent' AND current_version_id=@aid_auto_resource_previous AND @aid_auto_resource_new IS NOT NULL;
UPDATE aid_runtime_module_agent_binding SET active_version_id=@aid_auto_resource_new,binding_revision=binding_revision+1
WHERE module_code='PREVIZ_3DBOX' AND active_version_id=@aid_auto_resource_previous AND @aid_auto_resource_new IS NOT NULL;
COMMIT;


