-- 发现内容浏览、投稿与后台审核。
CREATE TABLE IF NOT EXISTS `aid_discovery_media` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '投稿或创建用户ID',
  `source_type` varchar(16) NOT NULL COMMENT '来源：USER/ADMIN',
  `media_type` varchar(16) NOT NULL COMMENT '媒体类型：video/image',
  `name` varchar(100) NOT NULL COMMENT '内容名称',
  `description` varchar(1000) NOT NULL COMMENT '内容描述',
  `cover_url` varchar(500) NOT NULL COMMENT '封面地址；图片内容使用本字段保存图片',
  `media_url` varchar(500) NULL DEFAULT NULL COMMENT '视频地址；图片内容为空',
  `preview_video_url` varchar(500) NULL DEFAULT NULL COMMENT '视频预览地址',
  `media_width` int(11) NOT NULL COMMENT '媒体宽度',
  `media_height` int(11) NOT NULL COMMENT '媒体高度',
  `aspect_ratio` varchar(32) NOT NULL COMMENT '服务端归一化画幅比例',
  `ratio_source` varchar(16) NOT NULL DEFAULT 'declared' COMMENT '比例来源：measured/declared',
  `prompt_text` varchar(4000) NULL DEFAULT NULL COMMENT '后台预留提示词',
  `review_status` varchar(16) NOT NULL COMMENT '审核状态：PENDING/APPROVED/REJECTED/REVOKED',
  `review_reason` varchar(500) NULL DEFAULT NULL COMMENT '最近审核说明',
  `review_by` varchar(64) NULL DEFAULT NULL COMMENT '最近审核人',
  `review_time` datetime NULL DEFAULT NULL COMMENT '最近审核时间',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序值，越小越靠前',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '展示状态：0启用 1停用',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志：0正常 1删除',
  `create_by` varchar(64) NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  INDEX `idx_discovery_public` (`review_status`, `status`, `del_flag`, `sort_order`, `publish_time`, `id`),
  INDEX `idx_discovery_user` (`user_id`, `source_type`, `del_flag`, `create_time`, `id`),
  INDEX `idx_discovery_review` (`review_status`, `source_type`, `media_type`, `del_flag`, `create_time`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='发现内容投稿与发布';

CREATE TABLE IF NOT EXISTS `aid_discovery_media_review_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `media_id` bigint(20) NOT NULL COMMENT '发现内容ID',
  `action` varchar(24) NOT NULL COMMENT 'SUBMIT/RESUBMIT/APPROVE/REJECT/REVOKE/ADMIN_CREATE/UPDATE/DELETE',
  `before_status` varchar(16) NULL DEFAULT NULL COMMENT '变更前审核状态',
  `after_status` varchar(16) NULL DEFAULT NULL COMMENT '变更后审核状态',
  `reason` varchar(500) NULL DEFAULT NULL COMMENT '操作说明',
  `operator_type` varchar(16) NOT NULL COMMENT '操作人类型：USER/ADMIN',
  `operator_id` bigint(20) NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) NULL DEFAULT NULL COMMENT '操作人名称',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志：0正常 1删除',
  `create_by` varchar(64) NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  INDEX `idx_discovery_log_media` (`media_id`, `create_time`, `id`),
  INDEX `idx_discovery_log_operator` (`operator_id`, `create_time`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='发现内容审核操作记录';

SET @discovery_audit_root := (SELECT MIN(menu_id) FROM sys_menu WHERE menu_type='M' AND parent_id=0 AND menu_name='审核管理');
SET @discovery_menu := (SELECT MIN(menu_id) FROM sys_menu WHERE menu_type='C' AND
