-- 虚拟相机局域网直连：场景、机位及可恢复轨迹元数据。

CREATE TABLE IF NOT EXISTS aid_director_scene (
  id BIGINT NOT NULL,
  project_id BIGINT NOT NULL,
  workspace_id BIGINT NULL,
  scope_key VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  scene_key VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(100) NOT NULL,
  revision BIGINT NOT NULL DEFAULT 0,
  object_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  content_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  byte_size INT NOT NULL,
  last_request_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  last_request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  deleted TINYINT NOT NULL DEFAULT 0,
  create_by VARCHAR(64) NOT NULL,
  update_by VARCHAR(64) NOT NULL,
  create_time DATETIME(3) NOT NULL,
  update_time DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_director_scene_scope (project_id,scope_key,scene_key),
  KEY idx_director_scene_list (project_id,scope_key,deleted,id),
  KEY idx_director_scene_reap (deleted,update_time,id),
  KEY idx_director_scene_object (object_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS aid_director_camera (
  id BIGINT NOT NULL,
  scene_id BIGINT NOT NULL,
  camera_key VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  control_fence BIGINT NOT NULL DEFAULT 0,
  owner_room_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  owner_room_epoch VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  owner_expires_at DATETIME(3) NULL,
  deleted TINYINT NOT NULL DEFAULT 0,
  locked TINYINT NOT NULL DEFAULT 0,
  create_by VARCHAR(64) NOT NULL,
  update_by VARCHAR(64) NOT NULL,
  create_time DATETIME(3) NOT NULL,
  update_time DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_director_camera_scope (scene_id,camera_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS aid_director_take (
  id BIGINT NOT NULL,
  project_id BIGINT NOT NULL,
  workspace_id BIGINT NULL,
  scene_id BIGINT NOT NULL,
  camera_row_id BIGINT NOT NULL,
  host_user_id BIGINT NOT NULL,
  origin_room_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  room_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  room_epoch VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  control_fence BIGINT NOT NULL,
  context_version BIGINT NOT NULL DEFAULT 1,
  start_request_id CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  start_request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  stop_request_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  host_stopped TINYINT NOT NULL DEFAULT 0,
  state VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  durable_frame_seq BIGINT NOT NULL DEFAULT -1,
  chunk_count INT NOT NULL DEFAULT 0,
  frame_count INT NOT NULL DEFAULT 0,
  duration_ms BIGINT NOT NULL DEFAULT 0,
  manifest_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  content_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  scene_revision_at_start BIGINT NOT NULL,
  applied_revision BIGINT NULL,
  applied_clip_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  apply_request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  recovered TINYINT NOT NULL DEFAULT 0,
  last_activity_at DATETIME(3) NOT NULL,
  expire_at DATETIME(3) NOT NULL,
  create_by VARCHAR(64) NOT NULL,
  update_by VARCHAR(64) NOT NULL,
  create_time DATETIME(3) NOT NULL,
  update_time DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_director_take_request (host_user_id,start_request_id),
  KEY idx_director_take_drafts (host_user_id,state),
  KEY idx_director_take_scene (scene_id,id),
  KEY idx_director_take_list (scene_id,host_user_id,id),
  KEY idx_director_take_expire (state,expire_at,id),
  KEY idx_director_take_idle (state,last_activity_at,id),
  KEY idx_director_take_camera (camera_row_id,state,last_activity_at),
  KEY idx_director_take_manifest (manifest_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS aid_director_take_chunk (
  id BIGINT NOT NULL,
  take_id BIGINT NOT NULL,
  chunk_no INT NOT NULL,
  first_frame_seq BIGINT NOT NULL,
  last_frame_seq BIGINT NOT NULL,
  start_ms BIGINT NOT NULL,
  end_ms BIGINT NOT NULL,
  frame_count INT NOT NULL,
  byte_size INT NOT NULL,
  content_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  object_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  create_by VARCHAR(64) NOT NULL,
  update_by VARCHAR(64) NOT NULL,
  create_time DATETIME(3) NOT NULL,
  update_time DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_director_chunk_number (take_id,chunk_no),
  KEY idx_director_chunk_object (object_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;


