-- 自由画布项目协作基础表。新装及存量升级采用相同结构，并保留既有项目与权限数据。

CREATE TABLE IF NOT EXISTS `aid_project_invite` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '邀请记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `token_hash` char(64) NOT NULL COMMENT '邀请令牌SHA-256摘要',
  `default_role` varchar(16) NOT NULL COMMENT '申请默认角色',
  `max_uses` int NOT NULL COMMENT '最大使用次数',
  `used_count` int NOT NULL DEFAULT '0' COMMENT '已使用次数',
  `expire_time` datetime NOT NULL COMMENT '过期时间',
  `status` varchar(16) NOT NULL DEFAULT 'ACTIVE' COMMENT '邀请状态',
  `creator_user_id` bigint NOT NULL COMMENT '创建用户ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_invite_token` (`token_hash`),
  KEY `idx_project_invite_project` (`project_id`,`status`,`id`),
  KEY `idx_project_invite_expire` (`status`,`expire_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用项目邀请';

CREATE TABLE IF NOT EXISTS `aid_project_join_application` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '加入申请ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `invite_id` bigint NOT NULL COMMENT '邀请记录ID',
  `applicant_user_id` bigint NOT NULL COMMENT '申请用户ID',
  `requested_role` varchar(16) NOT NULL COMMENT '申请角色',
  `status` varchar(16) NOT NULL DEFAULT 'PENDING' COMMENT '申请状态',
  `apply_message` varchar(500) DEFAULT NULL COMMENT '申请留言',
  `reviewer_user_id` bigint DEFAULT NULL COMMENT '审核用户ID',
  `review_remark` varchar(500) DEFAULT NULL COMMENT '审核备注',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_application_user` (`invite_id`,`applicant_user_id`),
  KEY `idx_project_application_project` (`project_id`,`status`,`id`),
  KEY `idx_project_application_user` (`applicant_user_id`,`status`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用项目加入申请';

CREATE TABLE IF NOT EXISTS `aid_project_member` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '成员记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `user_id` bigint NOT NULL COMMENT '成员用户ID',
  `role_code` varchar(16) NOT NULL COMMENT '项目角色',
  `status` varchar(16) NOT NULL DEFAULT 'ACTIVE' COMMENT '成员状态',
  `invited_by` bigint DEFAULT NULL COMMENT '邀请人用户ID',
  `joined_time` datetime DEFAULT NULL COMMENT '加入时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_member_user` (`project_id`,`user_id`),
  KEY `idx_project_member_project_status` (`project_id`,`status`,`role_code`,`id`),
  KEY `idx_project_member_user_status` (`user_id`,`status`,`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用项目成员';

CREATE TABLE IF NOT EXISTS `aid_project_setting` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目设置ID',
  `project_id` bigint NOT NULL COMMENT '通用项目ID',
  `setting_key` varchar(100) NOT NULL COMMENT '设置键',
  `setting_value` longtext NOT NULL COMMENT '规范化JSON设置值',
  `setting_version` bigint NOT NULL DEFAULT '1' COMMENT '乐观锁版本',
  `last_actor_user_id` bigint NOT NULL COMMENT '最后修改用户ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_setting_key` (`project_id`,`setting_key`),
  KEY `idx_project_setting_update` (`project_id`,`update_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用项目设置';

CREATE TABLE IF NOT EXISTS `aid_project_share` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '分享记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `token_hash` char(64) NOT NULL COMMENT '分享令牌SHA-256摘要',
  `snapshot_revision` bigint NOT NULL COMMENT '分享快照修订号',
  `snapshot_json` longtext NOT NULL COMMENT '不可变分享快照JSON',
  `expire_time` datetime NOT NULL COMMENT '过期时间',
  `status` varchar(16) NOT NULL DEFAULT 'ACTIVE' COMMENT '分享状态',
  `creator_user_id` bigint NOT NULL COMMENT '创建用户ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_project_share_token` (`token_hash`),
  KEY `idx_project_share_project` (`project_id`,`status`,`id`),
  KEY `idx_project_share_expire` (`status`,`expire_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用项目只读分享';

