SET @aid_provider_balance_parent := (
  SELECT MIN(menu_id) FROM sys_menu WHERE menu_type='M' AND parent_id=0 AND path='ai-model'
);
SET @aid_provider_balance_menu := (
  SELECT MIN(menu_id) FROM sys_menu WHERE menu_type='C'
    AND (component='aid/providerbalance/index' OR perms='aid:providerbalance:list')
);
INSERT INTO sys_menu (menu_name,parent_id,order_num,path,component,menu_type,visible,status,perms,icon,create_by,create_time)
SELECT '供应商余额监控',@aid_provider_balance_parent,8,'providerbalance','aid/providerbalance/index',
       'C','0','0','aid:providerbalance:list','money','system',NOW()
WHERE @aid_provider_balance_parent IS NOT NULL AND @aid_provider_balance_menu IS NULL
  AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE parent_id=@aid_provider_balance_parent AND path='providerbalance');
SET @aid_provider_balance_menu := (
  SELECT MIN(menu_id) FROM sys_menu WHERE menu_type='C'
    AND (component='aid/providerbalance/index' OR perms='aid:providerbalance:list')
);

INSERT INTO sys_menu (menu_name,parent_id,order_num,path,menu_type,visible,status,perms,icon,create_by,create_time)
SELECT button.name,@aid_provider_balance_menu,button.position,'#','F','0','0',button.permission,'#','system',NOW()
FROM (SELECT '余额监控查询' name,1 position,'aid:providerbalance:query' permission
      UNION ALL SELECT '余额监控配置',2,'aid:providerbalance:edit'
      UNION ALL SELECT '提醒渠道测试',3,'aid:providerbalance:test') button
WHERE @aid_provider_balance_menu IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM sys_menu m WHERE BINARY m.perms=BINARY button.permission);

-- Previous fixed-ID seeds could attach these built-in actions to another page.
UPDATE sys_menu SET parent_id=@aid_provider_balance_menu
WHERE @aid_provider_balance_menu IS NOT NULL AND parent_id=1358 AND parent_id<>@aid_provider_balance_menu
  AND menu_type='F' AND create_by='system'
  AND perms IN ('aid:providerbalance:query','aid:providerbalance:edit','aid:providerbalance:test');

UPDATE sys_menu SET menu_name='作品审核',order_num=2
WHERE menu_type='C' AND component='aid/audit/index' AND path='comicaudit' AND perms='aid:audit:list'
  AND menu_name IN ('流程审核','作品审核');
UPDATE sys_menu SET menu_name='发现内容',order_num=1
WHERE menu_type='C' AND component='commercial/discovery/index' AND path='discovery'
  AND perms='commercial:discovery:list' AND menu_name IN ('发现审核','发现内容');
UPDATE sys_menu SET order_num=CASE WHEN order_num=3 THEN 2 ELSE order_num END,
    icon=CASE WHEN icon='eye-open' THEN 'upload' ELSE icon END
WHERE menu_type='C' AND component='aid/publishmanage/index' AND path='publishmanage'
  AND perms='aid:publish:list' AND menu_name='发布管理' AND (order_num=3 OR icon='eye-open');

COMMIT;

-- Open-source text defaults: copy the V4 Pro pool to DeepSeek Flash and switch active selections.
-- Keep the original model identity, historical runs and immutable Skill packages for audit.
DROP PROCEDURE IF EXISTS aid_open_switch_deepseek_flash;
DELIMITER $$
CREATE PROCEDURE aid_open_switch_deepseek_flash()
switch_models: BEGIN
    DECLARE pro_id BIGINT;
    DECLARE flash_id BIGINT;
    DECLARE finished BOOLEAN DEFAULT FALSE;
    DECLARE pool_id BIGINT;
    DECLARE members LONGTEXT;
    DECLARE replaced LONGTEXT;
    DECLARE entry_json LONGTEXT;
    DECLARE entry_id LONGTEXT;
    DECLARE position_no INT;
    DECLARE flash_included BOOLEAN;
    DECLARE pools CURSOR FOR
        SELECT id, model_ids FROM aid_ai_model_func_config
        WHERE del_flag = '0'
          AND CASE WHEN JSON_TYPE(IF(JSON_VALID(model_ids), model_ids, NULL)) = 'ARRAY'
              THEN JSON_CONTAINS(model_ids, CAST(pro_id AS CHAR))
                   OR JSON_CONTAINS(model_ids, JSON_QUOTE(CAST(pro_id AS CHAR)))
              ELSE FALSE END
        FOR UPDATE;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished = TRUE;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SET flash_id = (
        SELECT MIN(m.id) FROM aid_ai_model m JOIN aid_ai_provider p ON p.id = m.provider_id
        WHERE p.provider_code = 'deepseek' AND m.model_code = 'deepseek-flash'
          AND m.model_type = 'text' AND m.del_flag = '0' AND p.del_flag = '0'
    );
    IF flash_id IS NULL THEN
        LEAVE switch_models;
    END IF;
    SET pro_id = (
        SELECT MIN(m.id) FROM aid_ai_model m JOIN aid_ai_provider p ON p.id = m.provider_id
        WHERE p.provider_code = 'deepseek' AND m.model_code = 'deepseek-v4-pro'
          AND m.model_type = 'text' AND m.del_flag = '0' AND p.del_flag = '0'
    );

    START TRANSACTION;
    UPDATE aid_ai_model SET status = '0', update_by = 'system', update_time = NOW()
    WHERE id = flash_id AND status <> '0';

    IF pro_id IS NOT NULL THEN
        INSERT INTO aid_gen_agent_pool
            (step, biz_category_code, creation_mode, script_type, strategy, agent_code, model_code,
             resolution, aspect_ratio, is_default, sort_order, status, del_flag, create_by, create_time, remark)
        SELECT src.step, src.biz_category_code, src.creation_mode, src.script_type, src.strategy, src.agent_code,
               'deepseek-flash', src.resolution, src.aspect_ratio,
               MAX(src.is_default), MIN(src.sort_order), MIN(src.status), '0', 'system', NOW(),
               MIN(src.remark)
        FROM aid_gen_agent_pool src
        WHERE src.model_code = 'deepseek-v4-pro' AND src.del_flag = '0'
          AND NOT EXISTS (
              SELECT 1 FROM aid_gen_agent_pool dst
              WHERE dst.model_code = 'deepseek-flash' AND dst.del_flag = '0'
                AND dst.step = src.step AND dst.biz_category_code = src.biz_category_code
                AND dst.creation_mode = src.creation_mode AND dst.script_type = src.script_type
                AND dst.strategy = src.strategy AND dst.agent_code = src.agent_code
                AND dst.resolution <=> src.resolution AND dst.aspect_ratio <=> src.aspect_ratio
          )
        GROUP BY src.step, src.biz_category_code, src.creation_mode, src.script_type, src.strategy,
                 src.agent_code, src.resolution, src.aspect_ratio;

        INSERT INTO aid_ai_business_model_binding
            (func_code, model_id, capability_code, default_capability, defaults_json,
             sort_order, create_by, create_time, remark)
        SELECT src.func_code, flash_id, src.capability_code, src.default_capability, src.defaults_json,
               src.sort_order, 'system', NOW(), src.remark
        FROM aid_ai_business_model_binding src
        WHERE src.model_id = pro_id AND NOT EXISTS (
            SELECT 1 FROM aid_ai_business_model_binding dst
            WHERE dst.func_code = src.func_code AND dst.model_id = flash_id
              AND dst.capability_code = src.capability_code
        );

        OPEN pools;
        pool_loop: LOOP
            FETCH pools INTO pool_id, members;
            IF finished THEN LEAVE pool_loop; END IF;
            SET replaced = JSON_ARRAY(), position_no = 0, flash_included = FALSE;
            WHILE position_no < JSON_LENGTH(members) DO
                SET entry_json = JSON_EXTRACT(members, CONCAT('$[', position_no, ']'));
                SET entry_id = JSON_UNQUOTE(entry_json);
                IF entry_id IN (CAST(pro_id AS CHAR), CAST(flash_id AS CHAR)) THEN
                    IF NOT flash_included THEN
                        SET replaced = JSON_ARRAY_APPEND(replaced, '$', flash_id), flash_included = TRUE;
                    END IF;
                ELSE
                    SET replaced = JSON_ARRAY_APPEND(replaced, '$', JSON_EXTRACT(entry_json, '$'));
                END IF;
                SET position_no = position_no + 1;
            END WHILE;
            UPDATE aid_ai_model_func_config
            SET model_ids = replaced, update_by = 'system', update_time = NOW() WHERE id = pool_id;
        END LOOP;
        CLOSE pools;

        DELETE FROM aid_ai_business_model_binding WHERE model_id = pro_id;
        UPDATE aid_gen_agent_pool SET status = '1', update_by = 'system', update_time = NOW()
        WHERE model_code = 'deepseek-v4-pro' AND del_flag = '0' AND status <> '1';
        UPDATE aid_agent SET model_code = 'deepseek-flash', update_by = 'system', update_time = NOW()
        WHERE model_code = 'deepseek-v4-pro';
        UPDATE aid_skill SET model_code = 'deepseek-flash', update_by = 'system', update_time = NOW()
        WHERE model_code = 'deepseek-v4-pro' AND del_flag = '0';
        UPDATE aid_project_gen_config SET model_code = 'deepseek-flash', update_by = 'system', update_time = NOW()
        WHERE model_code = 'deepseek-v4-pro';
        UPDATE aid_ai_model SET status = '1', update_by = 'system', update_time = NOW()
        WHERE id = pro_id AND status <> '1';
    END IF;
    COMMIT;
END$$
DELIMITER ;
CALL aid_open_switch_deepseek_flash();
DROP PROCEDURE aid_open_switch_deepseek_flash;

-- Update existing built-in labels on upgrade without changing persisted identifiers.
SET @aid_hub_old_label := CONCAT('3D-', 'Box');
UPDATE aid_ai_model_func_config
SET func_name = CONVERT(REPLACE(BINARY func_name, BINARY @aid_hub_old_label, BINARY '3D-HUB') USING utf8mb4)
WHERE func_code = 'previz_3dbox' AND del_flag = '0'
  AND LOCATE(BINARY @aid_hub_old_label, BINARY func_name) > 0;

UPDATE aid_skill
SET name = CONVERT(REPLACE(BINARY name, BINARY @aid_hub_old_label, BINARY '3D-HUB') USING utf8mb4),
    description = CONVERT(REPLACE(BINARY description, BINARY @aid_hub_old_label, BINARY '3D-HUB') USING utf8mb4)
WHERE skill_code = 'previz_3dbox_method' AND owner_type = 'PLATFORM' AND del_flag = '0'
  AND (LOCATE(BINARY @aid_hub_old_label, BINARY name) > 0
       OR LOCATE(BINARY @aid_hub_old_label, BINARY description) > 0);

UPDATE aid_runtime_agent
SET name = CONVERT(REPLACE(BINARY name, BINARY @aid_hub_old_label, BINARY '3D-HUB') USING utf8mb4),
    description = CONVERT(REPLACE(BINARY description, BINARY @aid_hub_old_label, BINARY '3D-HUB') USING utf8mb4)
WHERE agent_code = 'previz_3dbox_agent' AND owner_type = 'PLATFORM' AND del_flag = '0'
  AND (LOCATE(BINARY @aid_hub_old_label, BINARY name) > 0
       OR LOCATE(BINARY @aid_hub_old_label, BINARY description) > 0);
UPDATE sys_config
SET config_name = CONVERT(REPLACE(BINARY config_name, BINARY @aid_hub_old_label, BINARY '3D-HUB') USING utf8mb4)
WHERE (config_key LIKE 'aid.previz.%' OR config_key LIKE 'aid.compute.scene.previz_3dbox.%')
  AND LOCATE(BINARY @aid_hub_old_label, BINARY config_name) > 0;

-- Allow the stock Screenwriter to deliver real Canvas text nodes.
START TRANSACTION;
SET @aid_screenwriter_previous := (
  SELECT v.id FROM aid_runtime_agent a
  JOIN aid_runtime_agent_version v ON v.id=a.current_version_id AND v.agent_id=a.id
  JOIN aid_runtime_module_agent_binding b ON b.runtime_agent_id=a.id AND b.active_version_id=v.id
  WHERE a.agent_code='story_script_agent' AND a.owner_type='PLATFORM' AND a.status='0' AND a.del_flag='0'
    AND v.version_code='3.0.0-community-starter-v2' AND v.create_by='community-starter'
    AND v.publish_status='FROZEN' AND v.status='0' AND v.del_flag='0'
    AND b.module_code='SCREENWRITER' AND b.status='ACTIVE' AND b.del_flag='0'
    AND COALESCE(b.update_by,'') IN ('','community-starter','system')
    AND NOT EXISTS (SELECT 1 FROM aid_runtime_agent_version n
                    WHERE n.agent_id=a.id AND n.version_code='3.0.0-community-starter-v3')
);
SET @aid_screenwriter_tool := 'canvas.node.create_text';
SET @aid_screenwriter_tool_digest := 'fed40a3d1369935500302a376a2f64a347371e7b46ed6c523ef9c986ce434d19';
SET @aid_screenwriter_instruction := (SELECT CONCAT(instruction,CHAR(10),CONVERT( USING utf8mb4))
  FROM aid_runtime_agent_version WHERE id=@aid_screenwriter_previous);
SET @aid_screenwriter_definition := (SELECT JSON_ARRAY_APPEND(JSON_SET(definition_json,
  '$.mainMarkdown',@aid_screenwriter_instruction,'$.systemPrompt',@aid_screenwriter_instruction,
  '$.packageVersionCode','3.0.0-community-starter-v3'),'$.toolBindings',
  JSON_OBJECT('toolCode',@aid_screenwriter_tool,'contractVersion','1.0.0','schemaDigest',@aid_screenwriter_tool_digest))
  FROM aid_runtime_agent_version WHERE id=@aid_screenwriter_previous);
INSERT INTO aid_runtime_agent_version (agent_id,version_code,publish_status,instruction,model_config_json,input_schema_json,
  output_schema_json,definition_json,package_digest,status,del_flag,create_by,create_time,update_by,update_time)
SELECT agent_id,'3.0.0-community-starter-v3','FROZEN',@aid_screenwriter_instruction,model_config_json,input_schema_json,
  output_schema_json,@aid_screenwriter_definition,
  SHA2(CONCAT_WS(CHAR(10),@aid_screenwriter_instruction,model_config_json,input_schema_json,output_schema_json,@aid_screenwriter_definition),256),
  '0','0','community-starter',NOW(),'community-starter',NOW()
FROM aid_runtime_agent_version WHERE id=@aid_screenwriter_previous;
SET @aid_screenwriter_version := IF(ROW_COUNT()=1,LAST_INSERT_ID(),NULL);
INSERT INTO aid_runtime_agent_skill_ref (agent_version_id,skill_id,skill_version_id,skill_code,package_digest)
SELECT @aid_screenwriter_version,skill_id,skill_version_id,skill_code,package_digest FROM aid_runtime_agent_skill_ref
WHERE agent_version_id=@aid_screenwriter_previous AND @aid_screenwriter_version IS NOT NULL;
INSERT INTO aid_runtime_agent_tool_ref (agent_version_id,tool_code,contract_version,schema_digest)
SELECT @aid_screenwriter_version,tool_code,contract_version,schema_digest FROM aid_runtime_agent_tool_ref
WHERE agent_version_id=@aid_screenwriter_previous AND @aid_screenwriter_version IS NOT NULL;
INSERT INTO aid_runtime_agent_tool_ref (agent_version_id,tool_code,contract_version,schema_digest)
SELECT @aid_screenwriter_version,@aid_screenwriter_tool,'1.0.0',@aid_screenwriter_tool_digest
WHERE @aid_screenwriter_version IS NOT NULL;
UPDATE aid_runtime_agent SET current_version_id=@aid_screenwriter_version
WHERE agent_code='story_script_agent' AND current_version_id=@aid_screenwriter_previous AND @aid_screenwriter_version IS NOT NULL;
UPDATE aid_runtime_module_agent_binding SET active_version_id=@aid_screenwriter_version,binding_revision=binding_revision+1
WHERE module_code='SCREENWRITER' AND active_version_id=@aid_screenwriter_previous AND @aid_screenwriter_version IS NOT NULL;
COMMIT;


SET @aid_workflow_fresh_install := 1;
-- Default model choices for the script-to-video workflow.
-- Keep other models in the catalog so sites can opt in later.
SET @workflow_saved_group_concat := @@session.group_concat_max_len;
SET SESSION group_concat_max_len = 1048576;

DROP TEMPORARY TABLE IF EXISTS tmp_workflow_choice, tmp_workflow_stock, tmp_workflow_pools, tmp_workflow_resolved;
CREATE TEMPORARY TABLE tmp_workflow_choice (
    func_code VARCHAR(100) NOT NULL,
    provider_code VARCHAR(50) NOT NULL,
    model_code VARCHAR(100) NOT NULL,
    capability_code VARCHAR(96) NOT NULL,
    model_order SMALLINT NOT NULL,
    is_default_capability TINYINT NOT NULL,
    PRIMARY KEY (func_code, provider_code, model_code, capability_code)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

